import{Y as e,q as t}from"./index-CJ7-JaRq.js";var n=(e,t,n,r)=>[{id:`a`,text:e},{id:`b`,text:t},{id:`c`,text:n},{id:`d`,text:r}],r=[{id:`Q-A01-1`,lessonId:`A-01`,type:`single`,difficulty:1,skill:`calculate`,prompt:`例として、ある家計の月間可処分所得が40万円、消費支出が30万円のとき、貯蓄率として正しいものはどれか。`,options:n(`10%`,`25%`,`33%`,`75%`),correctIds:[`b`],explanation:`貯蓄は40−30＝10万円で、貯蓄率は10÷40＝0.25、すなわち25%です。`,wrongExplanations:{a:`貯蓄額10万円をそのまま割合にした誤りです。`,c:`消費支出30万円を分母にした誤りです。分母は可処分所得です。`,d:`これは消費の割合（30÷40）であり貯蓄率ではありません。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A01-2`,lessonId:`A-01`,type:`single`,difficulty:1,skill:`apply`,prompt:`高金利の借入が残っており生活防衛資金もない人が、資産形成を始める際の優先順位として最も適切なものはどれか。`,options:n(`まず株式投資で資産を増やし、その利益で高金利の借入を返済する`,`生活防衛資金の確保と高金利負債の返済を優先する`,`借入を増やして投資資金にする`,`流動性の低い資産に全額を回す`),correctIds:[`b`],explanation:`高金利負債の金利負担は確実なマイナスリターンであり、生活防衛資金がない状態での投資は急な支出時に不利な売却を招きます。土台の確保が先です。`,wrongExplanations:{a:`投資リターンは不確実で、金利負担を確実に上回る保証はありません。`,c:`借入による投資は損失拡大と返済負担を同時に招きます。`,d:`流動性が低いと緊急時に換金できず本末転倒です。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A01-3`,lessonId:`A-01`,type:`multi`,difficulty:1,skill:`understand`,prompt:`次のうち、間接金融に分類されるものをすべて選べ。`,options:n(`家計が銀行に預金し、銀行が企業へ貸し付ける`,`企業が株式を発行し、投資家が直接引き受ける`,`企業が社債を発行し、投資家が直接引き受ける`,`企業が銀行から借り入れる`),correctIds:[`a`,`d`],explanation:`間接金融は金融機関が仲介する資金の流れで、銀行預金を原資とする貸付や銀行借入が当たります。株式や社債の発行は、投資家が発行体から直接引き受けてリスクを負う直接金融です。`,wrongExplanations:{b:`株式の発行は市場を通じた直接金融です。`,c:`社債の発行は市場を通じた直接金融です。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A01-4`,lessonId:`A-01`,type:`single`,difficulty:1,skill:`find-error`,prompt:`金融と家計に関する次の説明のうち、誤っているものはどれか。`,options:n(`生活防衛資金の必要額は、理論的に一意に決まる`,`貯蓄率は可処分所得に対する貯蓄の割合である`,`生活防衛資金は流動性の高い預金などで確保することが望ましい`,`負債は将来の収入を先取りするもので、金利負担と返済義務が生じる`),correctIds:[`a`],explanation:`生活防衛資金の「生活費の数か月分」は経験則であり、必要額は雇用形態や家族構成で変わります。理論的に一意に決まる金額ではありません。他の選択肢はいずれも正しい説明です。`,wrongExplanations:{b:`正しい説明です。貯蓄率は（可処分所得−消費支出）÷可処分所得で計算します。`,c:`正しい説明です。急な支出に備えるため流動性が重視されます。`,d:`正しい説明です。家計の信用リスクは、収入に対する返済負担の大きさとして現れます。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A02-1`,lessonId:`A-02`,type:`single`,difficulty:1,skill:`calculate`,prompt:`100万円を年利10%の複利で2年間運用したとき、2年後の将来価値はどれか（税金・手数料は考えない）。`,options:n(`120万円`,`121万円`,`110万円`,`200万円`),correctIds:[`b`],explanation:`FV＝100×1.10^2＝100×1.21＝121万円です。1年目の利息10万円にも2年目に利息が付くことが単利との違いです。`,wrongExplanations:{a:`単利（100＋10×2）の計算であり複利ではありません。`,c:`1年分しか計算していません。`,d:`元本が2倍になる計算であり誤りです。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A02-2`,lessonId:`A-02`,type:`single`,difficulty:2,skill:`calculate`,prompt:`名目金利が5%、インフレ率が3%のとき、フィッシャー方程式による正確な実質金利に最も近いものはどれか。`,options:n(`2.00%`,`1.94%`,`8.00%`,`−2.00%`),correctIds:[`b`],explanation:`正確な実質金利は1.05÷1.03−1≒0.0194、約1.94%です。近似値の2%（5−3）とは少し異なります。`,wrongExplanations:{a:`これは近似式（名目−インフレ）の値で、正確な値ではありません。`,c:`名目金利とインフレ率を足した誤りです。`,d:`符号を取り違えた誤りです。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A02-3`,lessonId:`A-02`,type:`single`,difficulty:2,skill:`calculate`,prompt:`年率8%で複利により割り引くとき、2年後に受け取る116.64万円の現在価値はどれか。`,options:n(`108万円`,`約100.6万円`,`116.64万円`,`100万円`),correctIds:[`d`],explanation:`現在価値＝116.64÷1.08^2＝116.64÷1.1664＝100万円です。検算すると100×1.1664＝116.64となります。`,wrongExplanations:{a:`1年分しか割り引いていない値（116.64÷1.08＝108）です。2年後の金額は2年分を割り引きます。`,b:`単利の割引（116.64÷（1＋0.08×2）≒100.6）で計算した値です。本問は複利前提で割り引きます。`,c:`割り引きを行っていない、将来の金額そのものです。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A02-4`,lessonId:`A-02`,type:`single`,difficulty:1,skill:`understand`,prompt:`預金金利が年1%、インフレ率が年3%の状況が続くとき、この預金に関する説明として正しいものはどれか。`,options:n(`名目金額が増えるため、購買力も増える`,`名目金額は増えるが、物価の上昇ほどには増えず購買力は低下する`,`金利とインフレは無関係であり、物価が上がっても購買力は変わらない`,`インフレは現金や預金の価値に影響しない`),correctIds:[`b`],explanation:`実質金利はおよそ1%−3%＝−2%であり、金額は増えても買える量は減ります。インフレ下では、現金や預金の保有にも購買力の低下という形の機会費用があります。`,wrongExplanations:{a:`名目金額の増加と実質的な購買力の増加は別の話です。`,c:`預金の実質的な増え方は、名目金利とインフレ率の関係で決まります。`,d:`インフレは貨幣の購買力を低下させるため、預金の実質価値に直接影響します。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A03-1`,lessonId:`A-03`,type:`single`,difficulty:1,skill:`understand`,prompt:`ドルコスト平均法の説明として正しいものはどれか。`,options:n(`価格が下がったと判断したときだけまとめて買い、平均取得単価を下げる方法である`,`定期的に一定額を買うことで平均取得単価を平準化する方法である`,`購入時期を分けることで、相場が下がっても元本割れを防げる方法である`,`購入時期を分散するため、一括投資より常に高いリターンになる方法である`),correctIds:[`b`],explanation:`一定額投資では高いときは少なく、安いときは多く買うため取得単価が平準化します。損失を防ぐ仕組みでも、常に有利な方法でもありません。`,wrongExplanations:{a:`安いときだけ買うのはタイミング投資であり、一定額投資の定義ではありません。`,c:`価格が下落し続ければ元本割れします。`,d:`右肩上がりの市場では一括投資が有利になる場合があります。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A03-2`,lessonId:`A-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`投資元本100が2年後に144になったとき（途中の入金・出金はないものとする）、CAGRはどれか。`,options:n(`22%`,`44%`,`20%`,`10%`),correctIds:[`c`],explanation:`CAGR＝(144÷100)^(1/2)−1＝1.2−1＝20%です。検算すると1.2×1.2＝1.44となります。`,wrongExplanations:{a:`2年間の上昇率44%を単純に2で割った22%ではありません。複利ベースで計算します。`,b:`44%は2年間通算の上昇率であり年率ではありません。`,d:`10%では2年で1.1×1.1＝1.21倍にしかならず、1.44倍には届きません。年率への換算には平方根を取る計算が必要です。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A03-3`,lessonId:`A-03`,type:`single`,difficulty:2,skill:`apply`,prompt:`運用担当者の腕を、投資家の入金・出金タイミングの影響を除いて評価したい。最も適した収益率はどれか。`,options:n(`金額加重収益率`,`時間加重収益率`,`期首・期末の値だけから求めるCAGR`,`期末残高と期首残高の差額`),correctIds:[`b`],explanation:`時間加重収益率は各期間のリターンを連結し、外部キャッシュフローの影響を除くため、運用者の評価に適します。金額加重収益率は投資家自身の体験リターンの評価に向きます。`,wrongExplanations:{a:`金額加重収益率は入金タイミングを反映するため、運用者ではなく投資家自身の体験の評価に適します。`,c:`CAGRは期首と期末の値だけから求めるため、途中の入金があると運用成果を正しく表しません。`,d:`差額は率ではなく、入金額の影響も含むため、収益率として比較できません。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A03-4`,lessonId:`A-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`ある投資信託を、価格80円のときに1.6万円分、価格40円のときに1.6万円分買った。平均取得単価はどれか。`,options:n(`約60円`,`約64円`,`約53円`,`約40円`),correctIds:[`c`],explanation:`購入口数は1.6万円÷80円＝200口と、1.6万円÷40円＝400口で、合計600口です。平均取得単価＝32,000円÷600口≒53.3円となり、価格の単純平均である60円より低くなります。`,wrongExplanations:{a:`価格の単純平均（80＋40）÷2＝60円です。一定額投資では買える口数が変わるため、投資総額と総口数から計算します。`,b:`総口数を500口と数えた誤りです。正しくは200口＋400口＝600口です。`,d:`40円は2回目の購入価格であり、平均取得単価ではありません。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A04-1`,lessonId:`A-04`,type:`single`,difficulty:2,skill:`understand`,prompt:`順序リスク（シーケンスリスク）の説明として正しいものはどれか。`,options:n(`手数料率の高い商品から順に資産が目減りし、長期の複利効果が失われていくリスク`,`取り崩し期には平均リターンが同じでも下落が初期に来ると資産枯渇の可能性が高まるリスク`,`生活費の通貨と運用資産の通貨が異なるとき、為替の変動で資産が減るリスク`,`多数の資産に分散しすぎた結果、個々の値上がりの効果が薄まり全体のリターンが下がるリスク`),correctIds:[`b`],explanation:`取り崩し期は下落時に資産を売却するため、その後の回復の恩恵を受ける元本が減ります。リターンの順序が結果を左右する点が本質です。`,wrongExplanations:{a:`手数料の影響は別概念です。`,c:`為替リスクとは異なります。`,d:`分散の効果とは別の概念です。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A04-2`,lessonId:`A-04`,type:`single`,difficulty:2,skill:`calculate`,prompt:`年間支出が300万円で、取り崩し率を5%と仮定するとき、必要資産額の目安はどれか（この目安が将来を保証するものではない前提で計算すること）。`,options:n(`1,500万円`,`6,000万円`,`3,000万円`,`600万円`),correctIds:[`b`],explanation:`必要資産額の目安＝300万円÷0.05＝6,000万円です。これは経験則に基づく目安であり保証ではありません。`,wrongExplanations:{a:`300×5の誤った計算です。取り崩し率で割ります。`,c:`取り崩し率10%で計算した値です。`,d:`単位を取り違えた誤りです。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A04-3`,lessonId:`A-04`,type:`single`,difficulty:2,skill:`apply`,prompt:`取り崩し期に入った人が、順序リスク（シーケンスリスク）への対策として最も適切なものはどれか。`,options:n(`下落したら取り崩し額を増やし、安値のうちに多く現金化する`,`平均リターンの最も高い資産に全額を集中させる`,`現金クッションを保持し、下落期はその現金で支出を賄って資産の売却を抑える`,`下落直後に全資産を売却して現金化し、その後の相場回復時も現金のまま保有し続ける`),correctIds:[`c`],explanation:`下落時に運用資産を売ると損失が固定され、その後の回復の恩恵を受ける元本が減ります。現金クッションで支出を賄うことや、取り崩し率を柔軟に調整することが代表的な対策です。`,wrongExplanations:{a:`下落時の売却を増やすことは損失の固定を加速させ、順序リスクを高めます。`,b:`集中投資は価格変動を大きくし、取り崩し期の資産枯渇リスクを高めます。`,d:`全売却は損失を確定させ、その後の回復局面に参加できなくなります。対策は下落期の売却を避けることであり、全資産の現金化ではありません。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-A04-4`,lessonId:`A-04`,type:`single`,difficulty:2,skill:`find-error`,prompt:`長期形成と取り崩しに関する次の説明のうち、誤っているものはどれか。`,options:n(`形成期の下落は、積立を続ける場合には安く買える機会になり得る`,`取り崩し期の下落は、資産を売却するため損失が固定されやすい`,`取り崩し率の目安は過去の特定市場データに基づく経験則であり、将来を保証しない`,`長寿化で取り崩し期間が延びても、インフレと資産枯渇のリスクは変わらない`),correctIds:[`d`],explanation:`取り崩し期間が延びるほど、インフレの累積的な影響と資産枯渇のリスクは高まります。他の選択肢はいずれも正しい説明です。`,wrongExplanations:{a:`正しい説明です。形成期と取り崩し期では、下落の意味が異なります。`,b:`正しい説明です。これが順序リスクの中心的な仕組みです。`,c:`正しい説明です。目安の利用には、税金・手数料・インフレを別途考慮する必要があります。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-B01-1`,lessonId:`B-01`,type:`single`,difficulty:1,skill:`understand`,prompt:`株式の「残余請求権」と有限責任の説明として正しいものはどれか。`,options:n(`株主は債権者より先に分配を受け、会社の負債を全額負う`,`株主は債権者への支払いの後に残った財産に請求でき、損失は出資額が上限である`,`株主は元本の返済を会社に請求できる`,`株主には議決権がない代わりに配当が保証される`),correctIds:[`b`],explanation:`株主の請求は債権者の後順位（残余）であり、その代わり損失は出資額が上限の有限責任です。配当は保証されません。`,wrongExplanations:{a:`請求の順位が逆で、責任も無限ではありません。`,c:`株式に元本返済請求権はありません。それは債券の性質です。`,d:`普通株式には議決権があり、配当は保証されません。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-B01-2`,lessonId:`B-01`,type:`single`,difficulty:1,skill:`calculate`,prompt:`株価1,500円、発行済株式数2,000万株の企業の時価総額はどれか。`,options:n(`30億円`,`300億円`,`3,000億円`,`3億円`),correctIds:[`b`],explanation:`時価総額＝1,500×2,000万＝300億円です（1,500×20,000,000＝30,000,000,000円）。`,wrongExplanations:{a:`桁が1つ小さい誤りです。`,c:`桁が1つ大きい誤りです。`,d:`桁が2つ小さい誤りです。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-B01-3`,lessonId:`B-01`,type:`single`,difficulty:2,skill:`compare`,prompt:`株価指数の算出方法に関する説明として正しいものはどれか。`,options:n(`株価平均型の指数は値がさ株の影響を受けやすく、時価総額加重型の指数は大型株の影響を受けやすい`,`TOPIXは株価の単純平均で算出される株価平均型の指数である`,`日経平均は時価総額加重型の指数である`,`算出方法が異なっても、同じ市場の指数は常に同じ動きをする`),correctIds:[`a`],explanation:`日経平均は株価平均型、TOPIXは時価総額加重型であり、算出方法が異なるため、同じ市場でも指数の動きは異なります。`,wrongExplanations:{b:`TOPIXは時価総額加重型の指数です。`,c:`日経平均は株価平均型です。時価総額加重型はTOPIXです。`,d:`構成銘柄と加重方法が異なるため、動きは一致しません。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-B01-4`,lessonId:`B-01`,type:`single`,difficulty:1,skill:`apply`,prompt:`未公開企業が新規上場（IPO）することの効果として、適切なものはどれか。`,options:n(`上場すれば、株価が下落することはなくなる`,`上場により、株主の議決権は消滅する`,`市場から広く資金を集められる一方、上場後は開示義務が生じる`,`上場企業は、負債を返済する必要がなくなる`),correctIds:[`c`],explanation:`上場には審査があり、上場後も継続的な開示が求められます。資金調達の幅が広がる代わりに、透明性の確保が義務づけられます。`,wrongExplanations:{a:`上場後も株価は市場で変動します。`,b:`普通株式の議決権は上場後も存続します。`,d:`負債の返済義務は上場とは無関係に存続します。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-B02-1`,lessonId:`B-02`,type:`single`,difficulty:1,skill:`compare`,prompt:`指値注文と成行注文の比較として正しいものはどれか。`,options:n(`指値は約定することを優先し、成行は指定した価格を優先するため、成行では想定より不利な約定は起きない`,`指値は価格を優先するが約定しないことがあり、成行は約定を優先するが不利な価格で約定することがある`,`どちらの注文も、発注時点で画面に表示されていた価格での約定が取引所により保証される`,`成行注文は価格を指定しない分、手数料が必ず無料になり、約定の速さも保証される`),correctIds:[`b`],explanation:`指値は希望価格以外で約定しない代わりに不約定のリスクがあり、成行は約定優先の代わりに板が薄いと不利な価格になります。`,wrongExplanations:{a:`優先するものが逆です。`,c:`成行に価格の保証はありません。`,d:`注文方法と手数料の有無は関係ありません。`},sources:[e.jpxTrading],reviewStatus:`verified`},{id:`Q-B02-2`,lessonId:`B-02`,type:`single`,difficulty:2,skill:`calculate`,prompt:`最良売り気配が2,010円、最良買い気配が1,990円のとき、スプレッド率（仲値に対する割合）はどれか。`,options:n(`2%`,`0.5%`,`1%`,`20%`),correctIds:[`c`],explanation:`スプレッドは20円、仲値は(2,010＋1,990)÷2＝2,000円なので、スプレッド率は20÷2,000＝1%です。`,wrongExplanations:{a:`2%は、仲値を（2,010＋1,990）÷2＝2,000円とすべきところを、その半分の1,000円でスプレッド20円を割った場合の値です。スプレッド率は仲値基準で20÷2,000＝1%です。`,b:`半分に計算した誤りです。`,d:`スプレッドの金額20円をそのまま割合にした誤りです。`},sources:[e.jpxTrading],reviewStatus:`verified`},{id:`Q-B02-3`,lessonId:`B-02`,type:`single`,difficulty:2,skill:`understand`,prompt:`取引所における注文の付け合わせの原則として正しいものはどれか。`,options:n(`先に出された注文が価格の高さや安さにかかわらず常に優先され、同時刻なら数量の大きい注文が優先される`,`数量の大きい注文が常に優先され、同じ数量では価格の高い買い注文と安い売り注文が優先される`,`買いでは価格の高い注文、売りでは価格の安い注文が優先され、同じ価格では先に出された注文が優先される`,`後から出された注文ほど最新の市場情報を反映しているため、同じ価格でも先の注文より優先される`),correctIds:[`c`],explanation:`価格優先・時間優先の原則により、有利な価格の注文が先に付け合わされ、同じ価格では時間の早い注文が優先されます。`,wrongExplanations:{a:`時間優先は同じ価格の場合に適用される原則です。まず価格優先が適用されます。`,b:`数量の大きさは優先順位の基準ではありません。`,d:`時間優先は、先に出された注文を優先する原則です。`},sources:[e.jpxTrading],reviewStatus:`verified`},{id:`Q-B02-4`,lessonId:`B-02`,type:`single`,difficulty:2,skill:`find-error`,prompt:`流動性と約定に関する次の説明のうち、誤っているものはどれか。`,options:n(`流動性の高い銘柄ほど、スプレッドは広くなる傾向がある`,`スリッページは、発注時点の想定価格と実際の約定価格の差である`,`マーケットインパクトは、自らの大口注文が価格を動かす効果である`,`板が薄い銘柄では、成行注文が想定より不利な価格で約定しやすい`),correctIds:[`a`],explanation:`スプレッドは実質的な取引コストの一部であり、流動性の高い銘柄ほど狭くなる傾向があります。他の選択肢はいずれも正しい説明です。`,wrongExplanations:{b:`正しい説明です。スリッページは想定価格と約定価格のずれです。`,c:`正しい説明です。自らの注文が需給を通じて価格を動かします。`,d:`正しい説明です。流動性が低いと、約定価格の不利な変動が大きくなります。`},sources:[e.jpxTrading],reviewStatus:`verified`},{id:`Q-B03-1`,lessonId:`B-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`純利益20億円、発行済株式数2億株の企業が新株5,000万株を発行した。増資資金による利益の変化がない前提で、増資後のEPSはどれか。`,options:n(`10円`,`8円`,`12.5円`,`4円`),correctIds:[`b`],explanation:`増資前EPSは20億÷2億＝10円。増資後は株式数が2.5億株となり、EPSは20億÷2.5億＝8円に低下します（希薄化）。`,wrongExplanations:{a:`増資前のEPSであり希薄化を反映していません。`,c:`株式数の変化を逆に扱った誤りです。`,d:`新株5,000万株を5億株と桁を取り違え、20億円÷5億株とした誤りです。正しくは発行済株式数の合計2.5億株で割ります。`},assumptions:`増資資金が利益を生むまでの間の静的な計算であり、実際の価値判断には資金使途の収益性が必要です。`,sources:[e.edinet],reviewStatus:`verified`},{id:`Q-B03-2`,lessonId:`B-03`,type:`single`,difficulty:1,skill:`understand`,prompt:`1株を2株にする株式分割が行われた場合の説明として正しいものはどれか（市場価格の変動は考えない）。`,options:n(`株数が2倍になるため、1株の価格が変わらなければ保有資産の価値も2倍になる`,`株価は理論上半分になり、保有株数は2倍になるが保有価値は変わらない`,`保有株数が2倍になるため、受け取る配当金の総額も必ず2倍になる`,`発行済株式数が2倍になるため、企業の利益も株数に比例して2倍になる`),correctIds:[`b`],explanation:`株式分割は株数と株価が比例して変わるだけで、持分割合と企業価値自体は変わりません。`,wrongExplanations:{a:`株数が増えても1株価格が下がるため価値は変わりません。`,c:`1株当たり配当は調整されるのが通常で、総額が必ず2倍にはなりません。`,d:`分割は企業の利益に影響しません。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-B03-3`,lessonId:`B-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`純利益12億円、発行済株式数1億2,000万株の企業が、自己株式2,000万株を取得して消却した。利益が変わらない前提で、消却後のEPSはどれか。`,options:n(`10円`,`8.3円`,`15円`,`12円`),correctIds:[`d`],explanation:`消却後の株式数は1億2,000万株−2,000万株＝1億株です。EPS＝12億円÷1億株＝12円となり、取得前の10円から上昇します。`,wrongExplanations:{a:`自己株式取得前のEPSです。消却で株式数が減る分を反映していません。`,b:`株式数が増えたとして計算した誤りです。自己株式の消却で株式数は減少します。`,c:`取得株数を二重に差し引いた（1億2,000万株−2,000万株−2,000万株＝8,000万株で割った）誤りです。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-B03-4`,lessonId:`B-03`,type:`single`,difficulty:2,skill:`apply`,prompt:`資本コストを上回る収益が見込める投資機会を持たない企業が、割高な株価水準で大規模な自社株買いを計画している。この計画への評価として最も適切なものはどれか。`,options:n(`自社株買いは常に株主価値を高めるため、株価水準にかかわらず評価できる`,`割高な価格での買いは残存株主の価値を損なう可能性があり、還元額の大きさではなく資本配分の質で評価すべきである`,`自社株買いをするとEPSが下がるため、常に否定的に評価すべきである`,`投資機会がないなら、株価水準にかかわらず全額を配当に回すべきである`),correctIds:[`b`],explanation:`自社株買いは株式数が減るため、利益が同じならEPSは上がりますが、割高な価格で買えば残存株主の価値は損なわれます。資本政策は還元の総額ではなく、買付け価格の妥当性を含む資本配分の質で評価します。`,wrongExplanations:{a:`自社株買いの効果は買付け価格に依存します。割高な買いは価値を損ないます。`,c:`自己株式の取得・消却は株式数を減らすため、利益が同じならEPSは上がる方向です。`,d:`配当と自社株買いの選択は、価格の妥当性なども含めた比較が必要です。「常に全額」が適切とは限りません。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-B04-1`,lessonId:`B-04`,type:`single`,difficulty:2,skill:`understand`,prompt:`空売りのリスクとして正しいものはどれか。`,options:n(`最大損失は売却代金が上限であり、株価が0円になったときに損失が最大になる`,`株価上昇に上限がないため損失も理論上無限大であり、買い戻し集中によるショートスクイーズが起こり得る`,`借りた株を売る取引なので、株価が上昇しても保証金の追加差入れ（追証）は発生しない`,`売却代金を先に受け取っているため、その後の株価の変動は損益に影響しない`),correctIds:[`b`],explanation:`空売りは買い戻しが義務であり、株価が上がるほど損失が拡大します。買い戻しが集中するとさらなる上昇を招くショートスクイーズが起こります。`,wrongExplanations:{a:`それは買いポジションの性質です。空売りの損失に上限はありません。`,c:`信用取引では保証金不足で追証が発生します。`,d:`価格変動がまさに損益の源泉です。`},sources:[e.jpxMargin],reviewStatus:`verified`},{id:`Q-B04-2`,lessonId:`B-04`,type:`single`,difficulty:2,skill:`calculate`,prompt:`委託保証金50万円で150万円分の信用買いをした。株価が10%下落したとき、保証金に対する損失率はどれか（金利・手数料は考えない）。`,options:n(`10%`,`20%`,`30%`,`3%`),correctIds:[`c`],explanation:`レバレッジは150÷50＝3倍。建玉の損失は150万円×10%＝15万円で、保証金に対する損失率は15÷50＝30%です。`,wrongExplanations:{a:`レバレッジを考慮していない値です。`,b:`レバレッジ2倍として計算した誤りです。`,d:`割合の計算を取り違えた誤りです。`},sources:[e.jpxMargin],reviewStatus:`verified`},{id:`Q-B04-3`,lessonId:`B-04`,type:`single`,difficulty:2,skill:`apply`,prompt:`信用買いの建玉で株価が下落し、保証金維持率が証券会社の定める基準を下回った。このとき投資家に起こり得ることとして正しいものはどれか。`,options:n(`追加の保証金（追証）の差し入れを求められ、応じられない場合は建玉が強制決済される`,`証券会社が損失を補填するため、何もする必要はない`,`制度信用取引であれば、返済期限まで追証は発生しない`,`損失は差し入れた委託保証金の範囲に自動的に限定され、それ以上の差し入れを求められることはない`),correctIds:[`a`],explanation:`信用取引では、維持率の低下により追証が発生し、差し入れできないと強制決済されます。損失が委託保証金を超えることがある点が、現物取引との大きな違いです。`,wrongExplanations:{b:`損失の補填は行われません。信用取引の損失は投資家自身が負います。`,c:`制度信用取引にも返済期限（原則6か月）と保証金維持の仕組みがあり、追証は発生します。`,d:`価格変動が大きい場合、損失が保証金を超えて追加の支払いが必要になることがあります。`},sources:[e.jpxMargin],reviewStatus:`verified`},{id:`Q-B04-4`,lessonId:`B-04`,type:`single`,difficulty:1,skill:`understand`,prompt:`逆日歩（品貸料）の説明として正しいものはどれか。`,options:n(`信用買いの建玉に課される金利である`,`空売りの約定のたびに、証券会社が売買代金に応じて徴収する売買手数料である`,`貸株の需給が逼迫したときに発生し、空売り側が負担するコストである`,`配当の代わりに空売り側が受け取る金額である`),correctIds:[`c`],explanation:`逆日歩は、空売りのための貸株が不足したときに発生する品貸料で、空売り側のコストになります。需給の逼迫の程度によって変動します。`,wrongExplanations:{a:`信用買いのコストは買方金利であり、逆日歩とは別のものです。`,b:`売買手数料とは別に、貸株の需給によって発生するコストです。`,d:`受け取るのではなく、空売り側が支払うコストです。`},sources:[e.jpxMargin],reviewStatus:`verified`},{id:`Q-C01-1`,lessonId:`C-01`,type:`single`,difficulty:1,skill:`calculate`,prompt:`ある企業の資産が800、負債が500のとき、純資産はどれか。`,options:n(`1,300`,`300`,`500`,`800`),correctIds:[`b`],explanation:`会計等式「資産＝負債＋純資産」より、純資産＝800−500＝300です。`,wrongExplanations:{a:`資産と負債を足した誤りです。`,c:`負債の金額そのものであり純資産ではありません。`,d:`資産の金額そのものであり純資産ではありません。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C01-2`,lessonId:`C-01`,type:`single`,difficulty:2,skill:`understand`,prompt:`財務三表のつながりの説明として正しいものはどれか。`,options:n(`損益計算書の純利益は当期の成績を示すだけで、貸借対照表の数値とは連動しない`,`純利益は配当などを調整して貸借対照表の利益剰余金に加わり、現金の増減はキャッシュフロー計算書で説明される`,`キャッシュフロー計算書で現金の増減が分かれば、発生主義の損益計算書は分析に不要である`,`貸借対照表は一期間の収益と費用を集計し、期末の利益を算出するための計算書である`),correctIds:[`b`],explanation:`純利益は利益剰余金を増やし、配当はそれを減らします。現金残高の変動はキャッシュフロー計算書が3区分で説明します。`,wrongExplanations:{a:`純利益は利益剰余金を通じて貸借対照表に直結します。`,c:`発生主義の利益情報はキャッシュフローとは別の重要情報です。`,d:`貸借対照表は一時点の残高を示すもので、期間の損益を示すのは損益計算書です。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C01-3`,lessonId:`C-01`,type:`single`,difficulty:1,skill:`understand`,prompt:`キャッシュフロー計算書（日本基準）の3区分に関する説明として正しいものはどれか。`,options:n(`工場や機械などの設備投資による支出は、資金を使う活動なので財務活動に区分される`,`営業活動は本業の現金の動き、投資活動は設備投資など、財務活動は資金調達と返済の現金の動きを示す`,`借入金の返済は、将来の利息負担を減らす投資と考えるため投資活動に区分される`,`配当金の支払いは、本業で稼いだ利益の分配なので営業活動に区分される`),correctIds:[`b`],explanation:`キャッシュフロー計算書は営業・投資・財務の3区分で現金の増減を示し、利益と現金のつながりを検証できます。`,wrongExplanations:{a:`設備投資の支出は投資活動に区分されます。`,c:`借入金の返済は財務活動に区分されます。`,d:`配当金の支払いは財務活動に区分されます。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C01-4`,lessonId:`C-01`,type:`single`,difficulty:2,skill:`find-error`,prompt:`財務三表に関する次の説明のうち、誤っているものはどれか。`,options:n(`売上債権の増加は、利益が出ていても現金がまだ回収されていないことを意味する`,`貸借対照表は、一時点の財政状態を示す`,`有価証券報告書の注記やセグメント情報も、重要な判断材料になる`,`損益計算書の純利益と、その期間の現金の増加額は常に一致する`),correctIds:[`d`],explanation:`利益は発生主義で計算されるため、純利益と現金の増加額は一致するとは限りません。その差はキャッシュフロー計算書で説明されます。他の選択肢はいずれも正しい説明です。`,wrongExplanations:{a:`正しい説明です。売上債権の増加は、利益と現金の差の主要因です。`,b:`正しい説明です。一期間の動きを示すのは損益計算書とキャッシュフロー計算書です。`,c:`正しい説明です。会計方針の変更や偶発債務などは注記に含まれます。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C02-1`,lessonId:`C-02`,type:`single`,difficulty:2,skill:`calculate`,prompt:`営業キャッシュフローが200、設備投資支出が70のとき、フリーキャッシュフロー（営業CF−設備投資支出の定義による）はどれか。`,options:n(`270`,`130`,`70`,`200`),correctIds:[`b`],explanation:`フリーキャッシュフロー＝200−70＝130です。`,wrongExplanations:{a:`加算した誤りです。設備投資は差し引きます。`,c:`設備投資支出そのものです。`,d:`営業キャッシュフローそのもので、設備投資を差し引いていません。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C02-2`,lessonId:`C-02`,type:`single`,difficulty:2,skill:`find-error`,prompt:`次の説明のうち、誤っているものはどれか。`,options:n(`減価償却費は現金支出を伴わない費用である`,`減価償却費が大きいほど、その金額だけ現金が会社から流出する`,`棚卸資産の増加は現金を拘束し営業キャッシュフローを悪化させる要因になる`,`フリーキャッシュフローは株主還元や借入返済の原資になる`),correctIds:[`b`],explanation:`減価償却は過去の設備投資の費用配分であり、当期の現金流出ではありません。間接法では純利益に加算して調整します。`,wrongExplanations:{a:`正しい説明です。減価償却は非現金費用です。`,c:`正しい説明です。在庫の積み増しは現金の拘束です。`,d:`正しい説明です。FCFは自由に使える現金です。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C02-3`,lessonId:`C-02`,type:`single`,difficulty:2,skill:`understand`,prompt:`営業キャッシュフロー（間接法）の調整に関する説明として正しいものはどれか。`,options:n(`売上債権が増加すると、その分だけ現金が増える`,`減価償却費は、現金支出を伴う費用として営業キャッシュフローから差し引く`,`仕入債務の増加は、支払いの繰り延べとして現金を増やす方向に働く`,`棚卸資産が減少すると、現金が拘束される`),correctIds:[`c`],explanation:`仕入債務の増加は支払いを先送りしている状態であり、営業キャッシュフローを増やす方向に働きます。逆に、売上債権や棚卸資産の増加は現金を拘束します。`,wrongExplanations:{a:`売上債権の増加は売上の未回収であり、現金を拘束する方向に働きます。`,b:`減価償却費は現金支出を伴わないため、間接法では純利益に加算して調整します。`,d:`棚卸資産の減少は、在庫に拘束されていた現金の解放であり、現金を増やす方向です。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C02-4`,lessonId:`C-02`,type:`single`,difficulty:2,skill:`apply`,prompt:`ある企業は3期連続で増益だが、営業キャッシュフローはマイナスが続き、売上債権と棚卸資産が大きく膨らんでいる。この企業への評価として最も適切なものはどれか。`,options:n(`売上の回収や在庫に問題がある可能性があり、利益の質が低いと評価される`,`増益が続いているため、利益の質は高いと評価できる`,`営業キャッシュフローは利益と無関係な指標であり、評価に使うべきではない`,`棚卸資産の増加は、将来の売上増加を保証するサインである`),correctIds:[`a`],explanation:`利益が増えているのに営業キャッシュフローが継続的にマイナスの企業は、売上の回収や在庫に問題がある可能性があり、利益の質が低いと評価されます。`,wrongExplanations:{b:`利益の質は、利益が現金に裏付けられているかで判断します。増益だけでは評価できません。`,c:`営業キャッシュフローは、利益の質を検証する中心的な指標です。`,d:`在庫の増加は売れ残りの可能性も含み、将来の売上を保証しません。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C03-1`,lessonId:`C-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`流動資産300、流動負債150の企業の流動比率はどれか。`,options:n(`50%`,`200%`,`150%`,`100%`),correctIds:[`b`],explanation:`流動比率＝300÷150＝2、すなわち200%です。`,wrongExplanations:{a:`流動負債÷流動資産と逆に計算した誤りです。`,c:`流動負債の金額をそのまま使った誤りです。`,d:`流動資産と流動負債が等しい場合の値です。本問では流動資産300は流動負債150の2倍です。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C03-2`,lessonId:`C-03`,type:`single`,difficulty:2,skill:`compare`,prompt:`ROICとWACCの比較に関する説明として正しいものはどれか。`,options:n(`ROICがWACCを継続的に上回る企業は、資本コストを超える収益を上げ価値創造していると判断される`,`ROICがWACCを下回っても成長率が高ければ必ず価値創造している`,`WACCは会計上の利益率である`,`ROICは株主だけのリターンを示す`),correctIds:[`a`],explanation:`ROIC−WACCのスプレッドが正で持続的であれば、投下資本に対して資本コストを超える収益を生んでいると判断されます。`,wrongExplanations:{b:`ROICがWACCを下回る成長は価値を毀損する方向に働きます。`,c:`WACCは市場データ等から推定する資本コストであり会計利益率ではありません。`,d:`ROICは負債と株主資本を含む投下資本全体に対する指標です。株主だけならROEです。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C03-3`,lessonId:`C-03`,type:`single`,difficulty:3,skill:`calculate`,prompt:`ある企業の売上高純利益率が5%、総資産回転率が1.6回、財務レバレッジ（総資産÷自己資本）が2.5倍のとき、デュポン分解によるROEはどれか。`,options:n(`9.1%`,`8%`,`12.5%`,`20%`),correctIds:[`d`],explanation:`ROE＝売上高純利益率×総資産回転率×財務レバレッジ＝5%×1.6×2.5＝20%です。ROEは収益性・効率性・負債活用の3要素に分解できます。`,wrongExplanations:{a:`3要素を足し算した誤りです（5＋1.6＋2.5＝9.1）。デュポン分解では掛け合わせます。`,b:`財務レバレッジを掛けていない値です（5%×1.6＝8%）。`,c:`総資産回転率を掛けていない値です（5%×2.5＝12.5%）。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C03-4`,lessonId:`C-03`,type:`single`,difficulty:2,skill:`find-error`,prompt:`財務健全性と資本効率に関する次の説明のうち、誤っているものはどれか。`,options:n(`流動比率が低い企業は、短期借入への依存や支払いの逼迫に注意が必要である`,`ROEは、負債の活用（財務レバレッジ）では高められない`,`在庫の多い業種では流動資産が大きく見えるため、業種特性を踏まえた比較が必要である`,`ROICの分母である投下資本は、有利子負債と自己資本を合わせたものである`),correctIds:[`b`],explanation:`ROEは自己資本に対する利益率であり、負債を活用すると自己資本の割合が小さくなる分、高められます。高ROEが財務レバレッジによるものかどうかを見極める必要があります。他の選択肢はいずれも正しい説明です。`,wrongExplanations:{a:`正しい説明です。短期の支払い能力を示すのが流動比率です。`,c:`正しい説明です。単一指標の単純な比較は誤解を招きます。`,d:`正しい説明です。ROICは事業に投じた資本全体に対する収益性です。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C04-1`,lessonId:`C-04`,type:`single`,difficulty:3,skill:`understand`,prompt:`監査意見と開示資料に関する説明として正しいものはどれか。`,options:n(`決算短信は取引所の規則で開示されるため、公表された時点で常に監査法人による監査が完了している`,`監査意見が不表明や否定的意見の場合、その企業の財務諸表の信頼性に重大な問題があるサインである`,`無限定適正意見が付いていれば、不正や誤りが一切ないことが監査法人によって保証される`,`有価証券報告書は証券会社の口座がないと閲覧できず、EDINETでは確認できない`),correctIds:[`b`],explanation:`不表明・否定的意見は重大な警告です。決算短信は監査完了前の公表があり得て、無限定適正でも不正の絶対的保証にはなりません。有報はEDINETで公開されます。`,wrongExplanations:{a:`決算短信は速報性が高く監査が完了していない場合があります。`,c:`監査は合理的な保証であり絶対的保証ではありません。`,d:`有価証券報告書はEDINETで誰でも確認できます。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C04-2`,lessonId:`C-04`,type:`multi`,difficulty:3,skill:`understand`,prompt:`財務分析で「追加確認すべき危険信号」に当たるものをすべて選べ。`,options:n(`利益の伸びを大きく上回る売上債権と棚卸資産の増加が続いている`,`営業キャッシュフローが複数期にわたり純利益を大きく下回っている`,`配当を継続して支払っている`,`株価が上昇している`),correctIds:[`a`,`b`],explanation:`売上債権・在庫の異常な増加と、利益に裏付けられない営業キャッシュフローの弱さは、売上の前倒し計上や回収悪化などの可能性を示す代表的な危険信号です。`,wrongExplanations:{c:`配当の継続自体は危険信号ではありません。原資の持続可能性を別途確認します。`,d:`株価の上昇は市場評価であり、会計上の危険信号ではありません。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C04-3`,lessonId:`C-04`,type:`single`,difficulty:2,skill:`calculate`,prompt:`売上高が1,460、売上債権が240のとき、売上債権回転期間（日）はどれか。`,options:n(`約6.1日`,`30日`,`60日`,`約305日`),correctIds:[`c`],explanation:`売上債権回転期間＝売上債権÷売上高×365＝240÷1,460×365＝60日です。`,wrongExplanations:{a:`売上高÷売上債権は回転率（回数）であり、その値約6.1は日数ではありません。`,b:`売上債権を半分の120として計算した誤りです。本問の売上債権は240です。`,d:`売上高から売上債権を差し引いて計算した誤りです。回転期間は売上債権そのものを売上高で割ります。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-C04-4`,lessonId:`C-04`,type:`multi`,difficulty:3,skill:`understand`,prompt:`日本基準とIFRSの会計処理の違いとして正しいものをすべて選べ。`,options:n(`のれんは、日本基準では規則的に償却される`,`のれんは、IFRSでは償却せず、減損によってのみ処理される`,`開発費は、IFRSではいかなる場合も資産計上できない`,`日本基準とIFRSに、会計処理の違いは存在しない`),correctIds:[`a`,`b`],explanation:`のれんの処理は代表的な基準間の差異で、日本基準は規則的な償却、IFRSとUS GAAPは非償却で減損のみです。国際比較では、こうした差異を調整する必要があります。`,wrongExplanations:{c:`IFRSでは、一定の条件を満たす開発費は資産計上が求められます。これも基準の違いの一つです。`,d:`のれんの償却や開発費の資産計上などに重要な違いがあり、比率比較の前提となります。`},sources:[e.edinet,e.asbjBusinessCombinations],reviewStatus:`verified`},{id:`Q-C04-5`,lessonId:`C-04`,type:`single`,difficulty:2,skill:`find-error`,prompt:`【資料読解】架空の会社Xの開示資料の抜粋（前期→当期）: 売上高 1,000億円→1,050億円、当期純利益 60億円→62億円、売上債権 100億円→180億円、営業キャッシュフロー 80億円→20億円。追加確認すべき危険信号として最も重要なものはどれか。`,options:n(`純利益が増加しているので、危険信号は存在しない`,`売上債権の増加率（+80%）が売上高の増加率（+5%）を大きく上回り、営業キャッシュフローが利益を大きく下回っている点`,`売上高が5%成長している点`,`売上債権が増えていること自体が常に成長の証拠であり、追加確認は不要である点`),correctIds:[`b`],explanation:`債権の増加率+80%（180÷100−1）は売上高の増加率+5%（1,050÷1,000−1）を大きく上回り、利益62億円に対し営業キャッシュフローは20億円にとどまります。売上計上と回収の実態（前倒し計上の有無、取引条件の変更、回収可能性）を注記と合わせて確認すべき代表的な危険信号です。`,wrongExplanations:{a:`利益が増えていても、利益とキャッシュフローの乖離や債権の異常な増加は危険信号です。利益の増加だけでは否定できません。`,c:`売上高の成長自体は危険信号ではありません。成長率の比較相手は売上債権の増加率です。`,d:`債権の増加が売上高の増加と見合う範囲なら自然ですが、本ケースでは+80%対+5%と乖離しており、常に無条件で良いとは言えません。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D01-1`,lessonId:`D-01`,type:`single`,difficulty:2,skill:`calculate`,prompt:`時価総額800億円、有利子負債300億円、現金100億円、EBITDA125億円の企業のEV/EBITDAはどれか。`,options:n(`6.4倍`,`8倍`,`8.8倍`,`10倍`),correctIds:[`b`],explanation:`EV＝800＋300−100＝1,000億円。EV/EBITDA＝1,000÷125＝8倍です。`,wrongExplanations:{a:`時価総額のみ（800÷125）で計算した誤りです。EVには負債と現金の調整が必要です。`,c:`現金を差し引いていない（1,100÷125）誤りです。`,d:`EBITDAを教材の計算例で使った100億円と取り違え、1,000÷100とした誤りです。本問のEBITDAは125億円です。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D01-2`,lessonId:`D-01`,type:`single`,difficulty:2,skill:`find-error`,prompt:`マルチプル評価に関する説明のうち、誤っているものはどれか。`,options:n(`PBRが1倍を下回れば、その株式は常に割安で買いである`,`景気敏感企業は利益のピーク時にPERが低く見えることがある`,`PSRは赤字企業にも使えるが利益率の違いを反映しない`,`相対評価は市場全体が割高な場合にその影響を受ける`),correctIds:[`a`],explanation:`ROEが資本コストを下回る企業ではPBR1倍割れが合理的であり得ます。マルチプルの低さだけで割安とは判断できません。他の選択肢はいずれも正しい説明です。`,wrongExplanations:{b:`正しい説明です。ピーク利益でPERを計算すると低く見えます。`,c:`正しい説明です。売上高ベースの限界です。`,d:`正しい説明です。相対評価の代表的な弱点です。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D01-3`,lessonId:`D-01`,type:`single`,difficulty:2,skill:`calculate`,prompt:`株価900円、1株当たり純資産（BPS）が1,200円の企業のPBRはどれか。`,options:n(`1.33倍`,`0.75倍`,`7.5倍`,`0.25倍`),correctIds:[`b`],explanation:`PBR＝株価÷BPS＝900÷1,200＝0.75倍です。1倍割れは、市場評価が純資産を下回っている状態を示します。`,wrongExplanations:{a:`BPS÷株価と逆に計算した値です。PBRは株価をBPSで割ります。`,c:`桁を取り違えた値です。900÷1,200は1未満になります。`,d:`（BPS−株価）÷BPSという差額の比率であり、PBRの定義ではありません。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D01-4`,lessonId:`D-01`,type:`single`,difficulty:2,skill:`apply`,prompt:`一時的な損失で当期利益が大きく落ち込んだため、ある企業のPERが通常の数倍に跳ね上がって見える。評価上の対応として最も適切なものはどれか。`,options:n(`PERが高いため、この株式は割高であると結論づける`,`マルチプル評価をやめ、株価の水準だけで判断する`,`PSRに切り替えれば、利益の状態にかかわらず常に正確に評価できる`,`一時的要因を除いた正常化利益でPERを計算し直して判断する`),correctIds:[`d`],explanation:`マルチプルの分母が一時的要因で歪む場合は、正常化した利益で計算し直すことが必要です。見かけの数値だけで判断しません。`,wrongExplanations:{a:`分母の一時的な落ち込みでPERが跳ね上がった状態であり、そのままでは割高と判断できません。`,b:`株価の水準そのものに、割安・割高の情報はありません。`,c:`PSRは利益率の違いを反映しないという別の限界があり、万能ではありません。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D01-5`,lessonId:`D-01`,type:`single`,difficulty:2,skill:`compare`,prompt:`【企業比較】架空の2社の数値: A社 株価2,000円・EPS 200円・1株配当100円、B社 株価3,000円・EPS 100円・1株配当30円。数値から言えることとして正しいものはどれか。`,options:n(`A社はPER10倍・配当利回り5%で、B社（PER30倍・同1%）より利益と配当に対して割安に価格付けされている`,`B社は株価がA社より1,000円高く市場の評価が高いので、B社の方が割安である`,`PERが低く配当利回りも高いA社は、成長性にかかわらず投資対象として必ずB社より優れている`,`配当利回りが5%と高いA社は、配当で株価の下落分を補えるため元本割れの心配がない`),correctIds:[`a`],explanation:`A社: PER＝2,000÷200＝10倍、配当利回り＝100÷2,000＝5%。B社: PER＝3,000÷100＝30倍、配当利回り＝30÷3,000＝1%。株価の絶対水準ではなく、利益・配当に対する倍率で比較するのが相対評価です。`,wrongExplanations:{b:`株価の水準そのもの（3,000円対2,000円）に割安・割高の意味はありません。1株の単位が異なるため、倍率で比較します。`,c:`マルチプルが低いことは割安な価格付けを示すだけで、成長性や利益の持続性を無視して優劣は決められません。`,d:`配当利回りは価格に対する配当の比率であり、価格変動による元本割れとは無関係です。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D02-1`,lessonId:`D-02`,type:`single`,difficulty:3,skill:`calculate`,prompt:`翌年のFCFFが120、WACCが10%、永久成長率が4%のとき、定率成長モデルによるターミナルバリューはどれか。`,options:n(`1,200`,`2,000`,`3,000`,`857`),correctIds:[`b`],explanation:`ターミナルバリュー＝120÷(0.10−0.04)＝120÷0.06＝2,000です。WACC＞成長率が前提条件です。`,wrongExplanations:{a:`成長率を差し引かず120÷0.10で計算した誤りです。`,c:`120÷0.04で計算した誤りです。分母はWACC−gです。`,d:`WACCと成長率を差し引くべきところを加えた計算です（120÷（0.10＋0.04）＝120÷0.14≈857）。分母はWACC−gです。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D02-2`,lessonId:`D-02`,type:`single`,difficulty:3,skill:`understand`,prompt:`DCF法とCAPMの限界に関する説明として正しいものはどれか。`,options:n(`DCFは将来のキャッシュフローを精密に割り引くため、成長率や割引率の前提が多少誤っても算出される価値は正確である`,`CAPMのベータは企業ごとに決まった不変の定数であり、推定期間や推定方法を変えても値は変わらない`,`DCFの価値は成長率・割引率の前提に大きく依存するため、感度分析で幅を示す必要があり、CAPMも単一ファクターなどの強い前提を持つ`,`FCFFは株主に帰属するキャッシュフローなので、株主資本コストで割り引くのが正しい対応である`),correctIds:[`c`],explanation:`DCFは前提への感応度が高く、点推定だけでなくシナリオ・感度分析が不可欠です。CAPMも強い前提の上に立つモデルであり、ベータは推定期間で変動します。FCFFに対応する割引率はWACCです。`,wrongExplanations:{a:`前提の誤差が結果を支配するため誤りです。`,b:`ベータは推定期間や手法で変動します。`,d:`FCFFと割引率の対応が誤っています。正しくはWACCです。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D02-3`,lessonId:`D-02`,type:`single`,difficulty:3,skill:`calculate`,prompt:`無リスク金利が1%、ベータが1.2、市場の期待リターンが6%のとき、CAPMによる株主資本コストはどれか。`,options:n(`7%`,`8.2%`,`6%`,`5%`),correctIds:[`a`],explanation:`株主資本コスト＝無リスク金利＋β×（市場の期待リターン−無リスク金利）＝1%＋1.2×（6%−1%）＝1%＋6%＝7%です。`,wrongExplanations:{b:`βを市場の期待リターン全体に掛けた誤りです。βを掛けるのはリスクプレミアム（市場の期待リターン−無リスク金利）です。`,c:`市場の期待リターンそのものであり、この銘柄のベータを反映していません。`,d:`リスクプレミアム（6%−1%＝5%）だけの値で、無リスク金利を加えていません。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D02-4`,lessonId:`D-02`,type:`single`,difficulty:3,skill:`find-error`,prompt:`DCF法に関する次の説明のうち、誤っているものはどれか。`,options:n(`FCFFはWACCで割り引くのが、対応関係として正しい`,`配当割引モデルは、FCFEの特殊形と位置づけられる`,`永久成長率がWACCを上回る場合でも、終価の式はそのまま使える`,`DCFでは、シナリオ分析と感度分析で結果の幅を示すことが重要である`),correctIds:[`c`],explanation:`終価の式（FCFF÷（WACC−g））はWACC＞gが必須条件です。成長率がWACC以上では分母が0以下となり、式は意味を持ちません。他の選択肢はいずれも正しい説明です。`,wrongExplanations:{a:`正しい説明です。FCFEの場合は株主資本コストで割り引きます。`,b:`正しい説明です。配当が株主に帰属するキャッシュフローと一致する場合、配当割引モデルはFCFEモデルの特殊形に帰着します。`,d:`正しい説明です。前提のわずかな変更で価値が大きく変わるためです。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D03-1`,lessonId:`D-03`,type:`multi`,difficulty:2,skill:`understand`,prompt:`持続的な競争優位性の源泉として適切なものをすべて選べ。`,options:n(`利用者が増えるほど価値が高まるネットワーク効果`,`乗り換えに大きなコストがかかるスイッチングコスト`,`一時的な流行による売上増加`,`その年の為替レートの変動`),correctIds:[`a`,`b`],explanation:`ネットワーク効果とスイッチングコストは模倣や参入を難しくし、優位性を持続させる構造的要因です。一時的な流行や為替変動は持続的な優位性の源泉ではありません。`,wrongExplanations:{c:`一時的な流行は持続性がなく優位性の源泉とはいえません。`,d:`為替変動は外部環境の変動であり企業の優位性ではありません。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D03-2`,lessonId:`D-03`,type:`single`,difficulty:2,skill:`apply`,prompt:`ROICが5%、WACCが8%の事業について、経営判断として最も適切なものはどれか。`,options:n(`事業の成長率を高めて売上と利益の規模を拡大するため、その事業への投資を大幅に拡大すべきである`,`資本コストを下回るリターンしか生まないため、投資拡大は価値を毀損する可能性が高く、改善か縮小・還元を検討すべきである`,`株価が上昇している間は資本効率の問題は表面化しないので、事業は現状維持すべきである`,`負債を増やしてWACCを下げれば、ROICが改善しなくても自動的に企業価値が創造される`),correctIds:[`b`],explanation:`ROIC＜WACCの状態で投資を拡大すると、資本コストを賄えない投資が増え企業価値を毀損します。収益性の改善、事業の縮小、株主還元などの検討が適切です。これは将来の株価ではなく資本効率の根拠に基づく判断です。`,wrongExplanations:{a:`スプレッドが負のまま拡大すると価値毀損が拡大します。`,c:`株価の動きは判断根拠になりません。資本効率の問題は残ります。`,d:`負債の増加はROIC自体を改善せず、リスクを高めます。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D03-3`,lessonId:`D-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`投下資本500億円、ROIC10%、WACC7%の企業について、資本コストを上回る超過収益の目安は年間どれか。`,options:n(`50億円`,`35億円`,`3億円`,`15億円`),correctIds:[`d`],explanation:`超過収益の目安＝（ROIC−WACC）×投下資本＝（10%−7%）×500億円＝3%×500億円＝15億円です。`,wrongExplanations:{a:`ROICだけを投下資本に掛けた値で、資本コストを差し引いていません。`,b:`WACCだけを投下資本に掛けた値であり、資本コストの金額に相当します。`,c:`スプレッドの3%という割合そのものであり、金額ではありません。投下資本に掛けて金額化します。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D03-4`,lessonId:`D-03`,type:`single`,difficulty:2,skill:`find-error`,prompt:`競争優位性に関する次の説明のうち、誤っているものはどれか。`,options:n(`ネットワーク効果は、利用者が増えるほどサービスの価値が高まる性質である`,`市場シェアが高ければ、収益性が伴わなくても競争優位性があると判断できる`,`技術変化は、既存の競争優位性を急速に陳腐化させることがある`,`競争優位性の主張は、ROICの持続性などの財務データで裏付ける必要がある`),correctIds:[`b`],explanation:`市場シェアの高さ自体は優位性の証明にはならず、資本コストを上回る収益性と結びついて初めて意味を持ちます。他の選択肢はいずれも正しい説明です。`,wrongExplanations:{a:`正しい説明です。ネットワーク効果は勝者総取りに近い構造を生むことがあります。`,c:`正しい説明です。競争優位性は永続するものではありません。`,d:`正しい説明です。定性的な主張だけでは不十分です。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D04-1`,lessonId:`D-04`,type:`single`,difficulty:3,skill:`understand`,prompt:`バリュートラップに関する説明として正しいものはどれか。`,options:n(`低PERの株式はすべてバリュートラップである`,`市場縮小や競争優位性の喪失で利益が構造的に衰退する企業は、低PERでもさらに下落し得る`,`バリュートラップはPERが高い成長株にのみ起こる`,`キャッシュフローが悪化してもPERが低ければ問題ない`),correctIds:[`b`],explanation:`バリュートラップは「割安に見えるが衰退が続く」状態です。低いマルチプルが市場の正当な評価である場合があるため、事業の持続性とキャッシュフローの確認が必要です。`,wrongExplanations:{a:`低PERがすべて罠ではなく、本当に割安な場合もあります。構造的衰退の有無が論点です。`,c:`概念が逆です。バリュートラップは低評価銘柄に関する概念です。`,d:`キャッシュフローの悪化は衰退の重要な兆候であり無視できません。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D04-2`,lessonId:`D-04`,type:`single`,difficulty:3,skill:`calculate`,prompt:`ある景気敏感企業（架空の例）の株価は6,000円、景気ピーク時のEPSは600円、景気循環を通じた正常化EPSは300円である。正常化EPSで計算したPERはどれか。`,options:n(`10倍`,`20倍`,`5倍`,`2倍`),correctIds:[`b`],explanation:`正常化PER＝6,000÷300＝20倍です。ピークEPSでは6,000÷600＝10倍と割安に見えますが、正常化利益では20倍であり、ピーク利益での判断は誤認のもとになります。`,wrongExplanations:{a:`ピークEPSで計算した値であり、景気敏感株の評価としては不適切です。`,c:`5という数字は、正常化EPS÷株価＝300÷6,000＝5%という利益利回り（PERの逆数）から来ています。PERは株価÷EPSで計算します。`,d:`ピークEPSと正常化EPSの比（600÷300＝2）をPERと混同した値です。PERは株価をEPSで割って求めます。`},assumptions:`正常化EPS300円は架空の前提値であり、実在企業の数値ではありません。`,sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D04-3`,lessonId:`D-04`,type:`single`,difficulty:2,skill:`understand`,prompt:`業種の景気感応度に関する説明として正しいものはどれか。`,options:n(`半導体産業は、需要が安定したディフェンシブな業種である`,`景気敏感株は、景気循環を通して利益がほぼ一定に保たれる`,`食品や医薬品などのディフェンシブ株は、需要が安定し利益の変動が小さい傾向がある`,`業種による景気感応度の違いは、評価方法の選択に影響しない`),correctIds:[`c`],explanation:`素材・資本財・半導体などは景気敏感、食品・医薬品・公益などはディフェンシブとされ、利益の変動特性に応じて、正常化利益で評価するかどうかなどの扱いが異なります。`,wrongExplanations:{a:`半導体産業は設備投資サイクルと在庫循環が激しく、景気敏感な業種です。`,b:`景気敏感株は、景気循環で利益が大きく変動する点が特徴です。`,d:`景気敏感株では正常化利益で評価するなど、業種特性は評価方法に直結します。`},sources:[e.edinet],reviewStatus:`verified`},{id:`Q-D04-4`,lessonId:`D-04`,type:`single`,difficulty:3,skill:`apply`,prompt:`PER50倍で取引されている成長企業が、市場が期待していた通りの高い利益成長を発表した。株価の反応に関する説明として最も適切なものはどれか。`,options:n(`期待どおりの成長が実現したため、株価は必ず大きく上昇する`,`高い成長は既に株価に織り込まれているため、期待どおりの結果だけでは株価が大きく上がるとは限らない`,`PERが高い企業は、発表内容にかかわらず必ず下落する`,`成長期待の織り込みは、株価には影響しない`),correctIds:[`b`],explanation:`高いPERは、将来の高成長を前提とした価格です。期待が実現しても前提どおりの結果であり、新しい驚きがなければ株価が大きく上がるとは限りません。逆に、期待を下回れば大きく下落します。`,wrongExplanations:{a:`織り込み済みの期待の実現は、新たな買い材料にはなりにくいものです。`,c:`高PERであること自体が下落を決めるわけではありません。期待と実績の差が反応を決めます。`,d:`成長期待の織り込みは高いPERの形成そのものであり、株価に大きく影響します。`},sources:[e.edinet],reviewStatus:`verified`}],i=[{id:`Q-E01-1`,lessonId:`E-01`,type:`single`,difficulty:1,skill:`calculate`,prompt:`消費500、投資100、政府支出90、輸出70、輸入60（単位は兆円、架空の数値）のとき、支出面から計算したGDPはいくらか。`,options:[{id:`a`,text:`820兆円`},{id:`b`,text:`700兆円`},{id:`c`,text:`630兆円`},{id:`d`,text:`760兆円`}],correctIds:[`b`],explanation:`GDP ＝ 消費＋投資＋政府支出＋輸出−輸入 ＝ 500＋100＋90＋70−60 ＝ 700兆円。輸入は国内で生産されたものではないため差し引きます。`,wrongExplanations:{a:`輸入を加算してしまった計算です（500＋100＋90＋70＋60＝820）。`,c:`輸出を加え忘れた計算です（500＋100＋90−60＝630）。輸出は国内で生産された財・サービスへの海外からの需要として加算します。`,d:`輸入を差し引いていない計算です（500＋100＋90＋70＝760）。`},assumptions:`在庫変動や統計上の不突合はないものとする。`,sources:[e.caoSna],reviewStatus:`verified`},{id:`Q-E01-2`,lessonId:`E-01`,type:`single`,difficulty:1,skill:`understand`,prompt:`消費者物価の上昇率が前年比+2%から+1%に低下した。この状態の説明として正しいものはどれか。`,options:[{id:`a`,text:`物価水準そのものが下がるデフレになった`},{id:`b`,text:`物価はなお上昇しているが、上昇のペースが鈍った（ディスインフレ）`},{id:`c`,text:`実質GDPがマイナスになったことを意味する`},{id:`d`,text:`失業率が上昇したことを意味する`}],correctIds:[`b`],explanation:`上昇率がプラスのまま低下するのはディスインフレです。物価水準自体が持続的に下がる状態がデフレであり、両者は区別されます。`,wrongExplanations:{a:`上昇率がプラスである以上、物価水準は上がり続けています。デフレは物価水準の持続的な下落です。`,c:`物価上昇率の変化と実質GDPの符号は別の概念です。`,d:`雇用指標は別に確認する必要があり、物価上昇率だけからは分かりません。`},sources:[e.bojTop],reviewStatus:`verified`},{id:`Q-E02-1`,lessonId:`E-02`,type:`single`,difficulty:2,skill:`understand`,prompt:`中央銀行が市場の予想通り利下げを発表したのに、株価と長期金利がほとんど動かなかった。最も妥当な説明はどれか。`,options:[{id:`a`,text:`金融政策は市場に一切影響しないから`},{id:`b`,text:`利下げが事前に価格へ織り込まれており、反応するのは予想との差の部分だから`},{id:`c`,text:`市場参加者が発表を見落としたから`},{id:`d`,text:`利下げは常に翌日以降にしか反映されない決まりだから`}],correctIds:[`b`],explanation:`市場価格は予想される政策を事前に反映します。発表内容が予想通りであれば新たな情報は少なく、価格は大きく動きません。サプライズの部分に反応するのが「織り込み」の考え方です。`,wrongExplanations:{a:`予想外の政策変更は価格を大きく動かします。影響しないわけではありません。`,c:`見落としではなく、事前の織り込みで説明できます。`,d:`そのような決まりはなく、予想外の発表は即座に反映されることがあります。`},sources:[e.bojPolicy],reviewStatus:`verified`},{id:`Q-E02-2`,lessonId:`E-02`,type:`single`,difficulty:2,skill:`calculate`,prompt:`名目金利が年3%、期待インフレ率が年2.5%のとき、近似式（フィッシャー方程式）による実質金利はおよそいくらか。`,options:[{id:`a`,text:`5.5%`},{id:`b`,text:`3%`},{id:`c`,text:`0.5%`},{id:`d`,text:`2.5%`}],correctIds:[`c`],explanation:`実質金利 ≒ 名目金利 − 期待インフレ率 ＝ 3 − 2.5 ＝ 0.5%。厳密式でも (1.03 ÷ 1.025 − 1) × 100 ≒ 0.49% でほぼ一致します。`,wrongExplanations:{a:`名目金利と期待インフレ率を足してしまった計算です。`,b:`名目金利そのものであり、インフレ調整をしていません。`,d:`期待インフレ率そのものであり、実質金利ではありません。`},assumptions:`近似式が使える範囲（インフレ率が小さい）とする。`,sources:[e.bojPolicy],reviewStatus:`verified`},{id:`Q-E03-1`,lessonId:`E-03`,type:`single`,difficulty:2,skill:`understand`,prompt:`「逆イールド」の説明として正しいものはどれか。`,options:[{id:`a`,text:`長期金利が短期金利より高い状態`},{id:`b`,text:`短期金利が長期金利より高い状態`},{id:`c`,text:`すべての年限の金利が同じ状態`},{id:`d`,text:`国債利回りがマイナスになった状態`}],correctIds:[`b`],explanation:`逆イールドは短期金利が長期金利を上回る状態です。将来の利下げや景気後退が予想される局面で生じやすく、過去に景気後退に先行した事例が多いことは観測事実ですが、時期や有無を保証するものではありません。`,wrongExplanations:{a:`それは通常の順イールドの説明です。`,c:`金利が年限によらず一定の状態はフラット化と呼ばれ、逆イールドとは異なります。`,d:`マイナス金利と逆イールドは別の概念です。長期・短期の大小関係で定義されます。`},sources:[e.bojTop],reviewStatus:`verified`},{id:`Q-E03-2`,lessonId:`E-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`2年物国債利回り1.8%、10年物国債利回り1.2%のとき、長短金利差（10年物−2年物）とイールドカーブの状態の組み合わせとして正しいものはどれか。`,options:[{id:`a`,text:`差は+0.6ポイントで順イールド`},{id:`b`,text:`差は−0.6ポイントで逆イールド`},{id:`c`,text:`差は3.0ポイントで順イールド`},{id:`d`,text:`差は−3.0ポイントで逆イールド`}],correctIds:[`b`],explanation:`1.2 − 1.8 ＝ −0.6ポイント。短期金利が長期金利を上回っているため逆イールドです。符号と大きさを分けて確認します。`,wrongExplanations:{a:`大小関係が逆です。10年物の方が低いため差はマイナスです。`,c:`2つの利回りを足した値であり、差ではありません。符号の解釈も誤りです。`,d:`状態の判定は正しい方向ですが、大きさは足し算ではなく引き算で −0.6ポイントです。`},sources:[e.bojTop],reviewStatus:`verified`},{id:`Q-E04-1`,lessonId:`E-04`,type:`single`,difficulty:2,skill:`calculate`,prompt:`同一製品が日本で2,000円、米国で10ドルで売られている。購買力平価レート（円/ドル）はいくらか。ただし輸送費・税は無視する。`,options:[{id:`a`,text:`20円/ドル`},{id:`b`,text:`100円/ドル`},{id:`c`,text:`200円/ドル`},{id:`d`,text:`2,000円/ドル`}],correctIds:[`c`],explanation:`購買力平価レート ＝ 日本の価格 ÷ 米国の価格 ＝ 2,000 ÷ 10 ＝ 200円/ドル。これは長期的な目安であり、短期の為替予測に使えるものではありません。`,wrongExplanations:{a:`桁を取り違えた計算です。`,b:`日本の価格2,000円の桁を1つ落として1,000 ÷ 10とした誤りです。正しくは2,000 ÷ 10 ＝ 200円/ドルです。`,d:`米国の価格で割る前の日本の価格そのものです。`},assumptions:`同一の財・品質で、輸送費・税・関税がないという購買力平価の仮定に基づく。`,sources:[e.bojTop],reviewStatus:`verified`},{id:`Q-E04-2`,lessonId:`E-04`,type:`single`,difficulty:2,skill:`find-error`,prompt:`為替に関する説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`高金利通貨は、局面にかかわらず必ず値上がりする`},{id:`b`,text:`購買力平価は長期的な目安であり、短期の為替は大きく乖離し続けることがある`},{id:`c`,text:`経常収支には貿易収支のほか、海外投資からの利子・配当などの第一次所得収支が含まれる`},{id:`d`,text:`危機時には金利の高低より安全性が優先され、資金の流れが逆転することがある`}],correctIds:[`a`],explanation:`高金利通貨が買われやすいのはリスク選好が安定した局面の傾向にすぎず、危機時には高金利通貨ほど売られる場合があります。「必ず」は誤りです。他の3つは正しい説明です。`,wrongExplanations:{b:`正しい説明です。購買力平価への収束は緩やかとされます。`,c:`正しい説明です。日本の経常黒字は所得収支が中心です。`,d:`正しい説明です。安全性への逃避は危機時の典型的な資金の動きです。`},sources:[e.bojTop],reviewStatus:`verified`},{id:`Q-E01-3`,lessonId:`E-01`,type:`single`,difficulty:2,skill:`find-error`,prompt:`GDPに関する説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`実質GDPは、物価の変動を取り除いて数量の変化を測る指標である`},{id:`b`,text:`輸入が増えると、それだけでGDPは機械的に減少する`},{id:`c`,text:`GDPには家計の無償労働は含まれない`},{id:`d`,text:`景気の山・谷の公式な判定方法は国によって異なる`}],correctIds:[`b`],explanation:`輸入は、消費や投資に含まれる輸入品の分を差し引くための調整項目であり、輸入の増加それ自体がGDPを機械的に減らすわけではない。消費や投資の増加に伴って輸入が増えることも多い。他の3つは正しい説明である。`,wrongExplanations:{a:`正しい説明である。実質GDPは基準年の価格で測り、物価変動の影響を取り除く。`,c:`正しい説明である。市場で取引されない家計の無償労働はGDPに数えられず、GDPの限界の1つとされる。`,d:`正しい説明である。公式な景気判定は国ごとに専門機関が行い、定義は国によって異なる。`},sources:[e.caoSna],reviewStatus:`verified`},{id:`Q-E01-4`,lessonId:`E-01`,type:`single`,difficulty:2,skill:`calculate`,prompt:`名目成長率が5%、物価上昇率が2%のとき、厳密式（1＋実質成長率 ＝ (1＋名目成長率） ÷ (1＋物価上昇率））による実質成長率はおよそいくらか。`,options:[{id:`a`,text:`7.00%`},{id:`b`,text:`3.00%`},{id:`c`,text:`約2.94%`},{id:`d`,text:`2.50%`}],correctIds:[`c`],explanation:`実質成長率 ＝ 1.05 ÷ 1.02 − 1 ≒ 0.0294、すなわち約2.94%である。近似式（5 − 2 ＝ 3%）に近い値になるが、厳密には割り算で求める。`,wrongExplanations:{a:`名目成長率と物価上昇率を足してしまった計算である。物価の影響は差し引く側にある。`,b:`近似式（名目成長率 − 物価上昇率）による値である。本問では厳密式で計算するため約2.94%が正しく、3%は近似値にとどまる。`,d:`名目成長率を物価上昇率で割った計算（5 ÷ 2）であり、厳密式の形を取り違えている。`},assumptions:`物価上昇率はGDPデフレーターの変化率として扱う。`,sources:[e.bojTop],reviewStatus:`verified`},{id:`Q-E02-3`,lessonId:`E-02`,type:`single`,difficulty:2,skill:`apply`,prompt:`中央銀行が政策金利を引き下げたにもかかわらず、銀行の貸出態度が慎重で企業向け貸出がほとんど増えなかった。この状況の理解として最も適切なものはどれか。`,options:[{id:`a`,text:`市場参加者が利下げを事前に織り込んでいたため、利下げの効果が貸出の段階で打ち消されたためである`},{id:`b`,text:`量的緩和が自動的に効果を発揮し、企業の資金需要がすでに満たされていたためである`},{id:`c`,text:`長期金利に含まれる期間プレミアムが上昇し、政策金利の引き下げ幅をすべて打ち消したためである`},{id:`d`,text:`金融政策の波及は常に保証されるわけではなく、貸出態度や需要側の慎重さによって弱まる場合がある`}],correctIds:[`d`],explanation:`政策金利の引き下げは波及経路の出発点にすぎず、銀行の貸出態度や借り手の慎重さによっては貸出が増えない場合がある（流動性の罠や、銀行の信用収縮として議論される状況である）。波及は常に保証されない。`,wrongExplanations:{a:`織り込みは、市場価格が予想される政策を事前に反映する話であり、貸出が増えない理由の説明にはならない。`,b:`量的緩和は中央銀行による資産買入れの話であり、本問の引き下げ局面で貸出が増えない理由とは無関係である。`,c:`期間プレミアムは長期金利の構成要素であり、市中銀行の貸出が増えない直接の理由にはならない。`},sources:[e.bojPolicy],reviewStatus:`verified`},{id:`Q-E02-4`,lessonId:`E-02`,type:`single`,difficulty:1,skill:`understand`,prompt:`中央銀行が将来の政策の見通しを示す表明（フォワードガイダンス）自体が、期待インフレ率や長期金利を動かす波及経路はどれか。`,options:[{id:`a`,text:`金利経路`},{id:`b`,text:`期待経路`},{id:`c`,text:`為替経路`},{id:`d`,text:`資産価格経路`}],correctIds:[`b`],explanation:`中央銀行の見通し表明が人々の期待を通じて期待インフレ率や長期金利を動かす経路は、期待経路である。表明そのものが情報として作用する点が特徴である。`,wrongExplanations:{a:`金利経路は、政策金利の変更が市場金利・貸出金利を通じて企業投資などに及ぶ経路である。`,c:`為替経路は、金利の変化が通貨の価値を動かし、輸出入の採算などに及ぶ経路である。`,d:`資産価格経路は、金利の変化が債券・株式の現在価値を動かす経路である。`},sources:[e.bojPolicy],reviewStatus:`verified`},{id:`Q-E03-3`,lessonId:`E-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`将来の短期金利予想の平均が1.2%、観測された長期金利が2.0%のとき、期間プレミアムはおよそ何ポイントか。ただし、長期金利 ≒ 短期金利予想の平均 ＋ 期間プレミアムとする。`,options:[{id:`a`,text:`0.8ポイント`},{id:`b`,text:`3.2ポイント`},{id:`c`,text:`1.2ポイント`},{id:`d`,text:`−0.8ポイント`}],correctIds:[`a`],explanation:`期間プレミアム ＝ 長期金利 − 短期金利予想の平均 ＝ 2.0 − 1.2 ＝ 0.8ポイントである。期間プレミアムは直接観測できず、この差分は推定値として扱う。`,wrongExplanations:{b:`2つの金利を足してしまった計算である（2.0 ＋ 1.2）。期間プレミアムは差分で求める。`,c:`短期金利予想の平均そのものであり、期間プレミアムではない。`,d:`引き算の向きが逆である。長期金利の方が高いため、差はプラスになる。`},sources:[e.bojTop],reviewStatus:`verified`},{id:`Q-E03-4`,lessonId:`E-03`,type:`single`,difficulty:2,skill:`apply`,prompt:`ある国で名目金利が2%、名目成長率が3%で推移し、基礎的財政収支（プライマリーバランス）は小幅の赤字である。政府債務残高の対GDP比の見通しとして、最も適切なものはどれか。`,options:[{id:`a`,text:`金利が成長率を下回るため、小幅の赤字でも債務残高の対GDP比は安定しやすい`},{id:`b`,text:`金利が成長率を上回るため、債務残高の対GDP比は発散しやすい`},{id:`c`,text:`プライマリーバランスが赤字である以上、金利や成長率の条件にかかわらず比率は必ず発散する`},{id:`d`,text:`債務残高の対GDP比は金利とは無関係に決まる`}],correctIds:[`a`],explanation:`債務比率の安定性は、債務残高の絶対額ではなく名目金利と名目成長率の関係で評価する。金利（2%）が成長率（3%）を下回る状態では、プライマリーバランスが多少赤字でも比率が安定しやすい。`,wrongExplanations:{b:`前提が逆である。本問では金利2%が成長率3%を下回っている。金利が成長率を上回る場合の説明である。`,c:`赤字でも、金利と成長率の関係によっては比率が安定し得る。「必ず発散する」は誤りである。`,d:`利払い負担を通じて金利は債務比率の動きに直接関係する。無関係ではない。`},sources:[e.bojPolicy],reviewStatus:`verified`},{id:`Q-E04-3`,lessonId:`E-04`,type:`multi`,difficulty:2,skill:`understand`,prompt:`経常収支を構成する項目として正しいものをすべて選べ。`,options:[{id:`a`,text:`貿易・サービス収支`},{id:`b`,text:`海外投資からの利子・配当などを含む第一次所得収支`},{id:`c`,text:`外国株式を購入する資本・金融取引そのもの`},{id:`d`,text:`中央銀行の外貨準備の増減そのもの`}],correctIds:[`a`,`b`],explanation:`経常収支は、貿易・サービス収支、第一次所得収支（海外投資からの利子・配当など）、第二次所得収支の合計である。株式の購入や外貨準備の増減は資本・金融収支の側の取引であり、経常収支には含まれない。`,wrongExplanations:{c:`株式の購入は資本・金融取引であり、経常収支の構成項目ではない。その保有から生じる配当の受取は第一次所得収支に入る点と区別する。`,d:`外貨準備の増減は金融収支に記録されるものであり、経常収支の構成項目ではない。`},sources:[e.bojTop],reviewStatus:`verified`},{id:`Q-E04-4`,lessonId:`E-04`,type:`single`,difficulty:2,skill:`apply`,prompt:`過去の金融危機を振り返ると、危機に先立って信用が膨らみ、危機時には資金の引き揚げが急速に進んだ。アジア通貨危機や世界金融危機などに共通する要素として、教材の整理に合うものはどれか。`,options:[{id:`a`,text:`レバレッジの積み上がりと、流動性の過小評価`},{id:`b`,text:`購買力平価からの為替レートの大きく持続的な乖離`},{id:`c`,text:`期間プレミアムの継続的な上昇`},{id:`d`,text:`期待インフレ率の継続的な低下`}],correctIds:[`a`],explanation:`歴史的な金融危機に共通するのは、レバレッジ（借入れによる投資）の積み上がり、流動性の過小評価、危機時の資金引き揚げの速さである。ただし直接の引き金と構造は事例ごとに異なり、単一の物語で一般化はできない。`,wrongExplanations:{b:`購買力平価は長期的な為替の目安であり、危機の共通要素として教材が挙げるものではない。`,c:`期間プレミアムは長期金利の構成要素であり、危機の引き金として事例に共通に挙げられるものではない。`,d:`期待インフレ率の低下は危機の共通要素ではない。危機時に焦点になるのは資金の流れと流動性である。`},sources:[e.bojFsr],reviewStatus:`verified`},{id:`Q-F01-1`,lessonId:`F-01`,type:`single`,difficulty:2,skill:`calculate`,prompt:`価格200円、修正デュレーション4年の債券について、利回りが0.5%上昇した。一次近似による価格はおよそいくらか。`,options:[{id:`a`,text:`204円`},{id:`b`,text:`196円`},{id:`c`,text:`192円`},{id:`d`,text:`200円`}],correctIds:[`b`],explanation:`価格変化率 ≒ −修正デュレーション × 利回り変化 ＝ −4 × 0.5% ＝ −2%。価格は 200 × (1 − 0.02) ＝ 196円。利回り上昇で価格が下がる逆関係の計算です（近似値）。`,wrongExplanations:{a:`符号が逆です。利回りが上がると価格は下がります。`,c:`利回り変化を1%として計算した結果であり、本問の0.5%上昇では過大です。`,d:`金利変動の影響を無視した値です。`},assumptions:`利回り変化が小さく一次近似が使えることとし、コンベクシティは無視する。`,sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F01-2`,lessonId:`F-01`,type:`single`,difficulty:2,skill:`compare`,prompt:`満期が同じ2つの債券のうち、クーポン（表面利率）が高い債券の性質として正しいものはどれか。`,options:[{id:`a`,text:`デュレーションが長く、金利変動に弱い`},{id:`b`,text:`デュレーションが短く、金利変動に対する価格の感応度が小さい`},{id:`c`,text:`信用スプレッドが必ずゼロになる`},{id:`d`,text:`価格と利回りの逆関係が成り立たなくなる`}],correctIds:[`b`],explanation:`クーポンが高いほど現金の受け取りが早まるため、平均回収期間であるデュレーションは短くなり、金利変動への感応度は小さくなります。`,wrongExplanations:{a:`逆です。クーポンが高いほどデュレーションは短くなります。`,c:`信用スプレッドは発行体の信用力で決まり、クーポンの高低でゼロにはなりません。`,d:`価格と利回りの逆関係は現在価値の計算から常に成り立ちます。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F02-1`,lessonId:`F-02`,type:`single`,difficulty:1,skill:`calculate`,prompt:`元本200万円を1年間、運用益ゼロと仮定する。信託報酬0.2%のファンドと0.8%のファンドで、1年間の信託報酬コストの差はいくらか。`,options:[{id:`a`,text:`1,200円`},{id:`b`,text:`6,000円`},{id:`c`,text:`12,000円`},{id:`d`,text:`20,000円`}],correctIds:[`c`],explanation:`0.2%では 2,000,000 × 0.002 ＝ 4,000円、0.8%では 2,000,000 × 0.008 ＝ 16,000円。差は 16,000 − 4,000 ＝ 12,000円です。この差は運用成績と無関係に毎年発生します。`,wrongExplanations:{a:`率の差0.6%を0.06%と読み違えた計算です（200万円×0.0006＝1,200円）。`,b:`率の差を0.3%として計算した誤りです（200万円×0.003＝6,000円）。差し引くのは率同士（0.8%−0.2%＝0.6%）です。`,d:`2つの率を合計して1%として計算した誤りです（200万円×0.01＝20,000円）。求めるのは差額です。`},assumptions:`期間中の元本の増減はなく、信託報酬のみを比較する。`,sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F02-2`,lessonId:`F-02`,type:`single`,difficulty:1,skill:`compare`,prompt:`ETFと通常の投資信託の売買方法の違いとして正しいものはどれか。`,options:[{id:`a`,text:`ETFは1日1回の基準価額でのみ売買でき、投資信託は取引時間中に市場価格で売買できる`},{id:`b`,text:`ETFは取引所で取引時間中に市場価格で売買でき、投資信託は1日1回決まる基準価額で売買するのが一般的である`},{id:`c`,text:`どちらも取引所でしか売買できない`},{id:`d`,text:`どちらも価格が決まらないまま注文することはできない`}],correctIds:[`b`],explanation:`ETFは上場しているため株式のように市場価格で取引され、基準価額との乖離が生じることがあります。投資信託は一般に1日1回の基準価額で、価格が分からないまま注文する形です。`,wrongExplanations:{a:`両者の説明が入れ替わっています。`,c:`投資信託は取引所ではなく販売会社などを通じて売買します。`,d:`投資信託は注文時点では基準価額が確定していないのが一般的です。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F03-1`,lessonId:`F-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`原指数が1日目に−10%、2日目に+10%と動いた。コストなしと仮定したとき、2倍レバレッジ型商品の2日後の価値は、当初の100に対していくらになるか。`,options:[{id:`a`,text:`100`},{id:`b`,text:`99`},{id:`c`,text:`96`},{id:`d`,text:`102`}],correctIds:[`c`],explanation:`日次リセットのため、日ごとに2倍します。100 × (1 − 0.20) × (1 ＋ 0.20) ＝ 100 × 0.80 × 1.20 ＝ 96。なお原指数自体も 100 × 0.90 × 1.10 ＝ 99 であり、レバレッジ型の目減り（減価）がより大きいことが分かります。`,wrongExplanations:{a:`上下が相殺されて元に戻るという誤解です。日次で倍率をかけるため戻りません。`,b:`原指数そのものの2日後の値です。レバレッジ型ではありません。`,d:`期間騰落率に単純に2倍をかけた誤った計算です。経路依存性のためそのようにはなりません。`},assumptions:`手数料・コスト・乖離はなく、日次騰落率に正確に倍率がかかるものとする。`,sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F03-2`,lessonId:`F-03`,type:`single`,difficulty:2,skill:`find-error`,prompt:`金とREITに関する説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`金は配当や利子を生まないため、収益源は値上がり益である`},{id:`b`,text:`REITは現物不動産そのものなので、株式市場の変動の影響を受けない`},{id:`c`,text:`REITの分配金は、保有する不動産からの賃料収入などが主な原資となる`},{id:`d`,text:`金の価格は実質金利の動向に影響されることがある`}],correctIds:[`b`],explanation:`REITは取引所に上場する証券であり、価格は不動産市況だけでなく株式市場全体の動きや金利の影響も受けます。「現物そのもので市場の影響を受けない」は誤りです。`,wrongExplanations:{a:`正しい説明です。金はキャッシュフローを生まない資産です。`,c:`正しい説明です。賃料収入が分配の中心的な原資です。`,d:`正しい説明です。利子を生まない金の保有の機会費用は実質金利と関係します。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F04-1`,lessonId:`F-04`,type:`single`,difficulty:2,skill:`calculate`,prompt:`外貨建て資産が現地通貨ベースで+10%値上がりしたが、同じ期間に為替が10%円高に動いた。円換算リターン（厳密計算）はいくらか。`,options:[{id:`a`,text:`0%`},{id:`b`,text:`+1%`},{id:`c`,text:`−1%`},{id:`d`,text:`+10%`}],correctIds:[`c`],explanation:`(1 ＋ 0.10) × (1 − 0.10) − 1 ＝ 1.10 × 0.90 − 1 ＝ 0.99 − 1 ＝ −1%。現地で値上がりしても円高で円換算ではマイナスになり得ます。単純な足し引き（0%）は近似であり、厳密には掛け算です。`,wrongExplanations:{a:`足し引きによる近似の結果です。厳密計算では −1% となります。`,b:`符号を取り違えた計算です。`,d:`為替変動の影響を無視した値です。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F04-2`,lessonId:`F-04`,type:`single`,difficulty:2,skill:`understand`,prompt:`平時に相関が低かった株式と暗号資産が、市場の危機局面でともに大きく売られた。この現象が分散投資の考え方に与える示唆として正しいものはどれか。`,options:[{id:`a`,text:`相関は一度測れば将来も不変である`},{id:`b`,text:`相関は局面で変化し得るため、過去の相関だけを根拠に分散効果を保証できない`},{id:`c`,text:`資産の種類を増やせば危機でも必ず損失を防げる`},{id:`d`,text:`危機時には相関が必ずゼロになる`}],correctIds:[`b`],explanation:`相関係数は過去データから計算される統計量で、危機時に上昇する事例が観測されています。分散効果は目安として使い、過信しないことが重要です。`,wrongExplanations:{a:`相関は市場環境で変化します。不変ではありません。`,c:`相関の高い資産同士の組み合わせでは効果が小さく、損失を必ず防げるわけではありません。`,d:`危機時にはむしろ相関が上がり、ともに下がる場合があることが本問の前提です。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F01-3`,lessonId:`F-01`,type:`single`,difficulty:1,skill:`calculate`,prompt:`1年後に利子と元本を合わせて105円を受け取る債券がある。市場利回り（割引率）が年5%のとき、この債券の現在価値はいくらか。`,options:[{id:`a`,text:`100円`},{id:`b`,text:`99.75円`},{id:`c`,text:`105円`},{id:`d`,text:`110.25円`}],correctIds:[`a`],explanation:`現在価値 ＝ 105 ÷ (1 ＋ 0.05) ＝ 105 ÷ 1.05 ＝ 100円である。将来のキャッシュフローを市場利回りで割り引いた合計が債券価格になる。`,wrongExplanations:{b:`105 × (1 − 0.05) ＝ 99.75円とした計算である。割り引きは利率を引くのではなく、(1 ＋ 利回り）で割る。`,c:`割り引きをしていない、将来の受取額そのものである。`,d:`105 × 1.05 と、割り増す方向に計算した誤りである。現在価値は将来の受取額より小さくなる。`},assumptions:`1年後の単一のキャッシュフローとして計算し、税・手数料は考えない。`,sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F01-4`,lessonId:`F-01`,type:`single`,difficulty:2,skill:`find-error`,prompt:`信用スプレッドに関する説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`社債の利回りには、国債利回りに信用スプレッドが上乗せされる`},{id:`b`,text:`信用スプレッドは、デフォルトの可能性とデフォルト時の回収の見込みを反映する`},{id:`c`,text:`景気が悪化する局面では、信用スプレッドは縮小しやすい`},{id:`d`,text:`利回りが高い債券は、その分だけリスクの対価を含んでいる場合が多い`}],correctIds:[`c`],explanation:`信用スプレッドは景気悪化局面で拡大しやすい性質がある。デフォルトへの懸念が高まるためであり、「縮小しやすい」は誤りである。`,wrongExplanations:{a:`正しい説明である。信用力が低い債券ほど上乗せは大きくなる。`,b:`正しい説明である。回収の見込みが低いほどスプレッドは大きくなる。`,d:`正しい説明である。高い利回りは信用リスクや流動性リスクの対価である場合が多く、高いほど得とは限らない。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F02-3`,lessonId:`F-02`,type:`multi`,difficulty:2,skill:`understand`,prompt:`トラッキングエラーに関する説明として正しいものをすべて選べ。`,options:[{id:`a`,text:`指数とファンドの収益率の差のばらつきを表す`},{id:`b`,text:`小さいほど、指数への連動の精度が高いことを示す`},{id:`c`,text:`信託報酬率そのものを指す言葉である`},{id:`d`,text:`ETFの市場価格と基準価額の乖離率を指す言葉である`}],correctIds:[`a`,`b`],explanation:`トラッキングエラーは、対象指数とファンドの収益率の差のばらつきであり、小さいほど連動の精度が高いことを示す。信託報酬率はコストの率、乖離率は市場価格と基準価額の差であり、それぞれ別の概念である。`,wrongExplanations:{c:`信託報酬率は保有期間中に差し引かれるコストの率であり、トラッキングエラーとは別の概念である。`,d:`市場価格と基準価額の差は乖離率と呼ばれ、トラッキングエラーとは区別される。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F02-4`,lessonId:`F-02`,type:`single`,difficulty:2,skill:`apply`,prompt:`信託報酬が年0.1%と低く表示されたファンドについて、信託報酬以外も含めた実際の負担コストを確認したい。最も適切な確認方法はどれか。`,options:[{id:`a`,text:`目論見書に表示された信託報酬率だけを確認する`},{id:`b`,text:`基準価額の過去の騰落率を確認する`},{id:`c`,text:`トラッキングエラーの大きさを確認する`},{id:`d`,text:`運用報告書で、費用総額に基づく実質コスト（総経費率）を確認する`}],correctIds:[`d`],explanation:`信託報酬のほかに売買手数料、監査費用、指数の使用料などがかかる場合があり、実際に負担した総額は運用報告書の実質コスト（総経費率）で確認する。表示された信託報酬だけでは総額は分からない。`,wrongExplanations:{a:`信託報酬は主要なコストだが、それ以外の費用を含まない。総額の確認には不十分である。`,b:`騰落率は運用成果の変動であり、負担したコストの内訳を示すものではない。`,c:`トラッキングエラーは指数との連動の精度を示す指標であり、コストの総額を示すものではない。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F03-3`,lessonId:`F-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`原指数が1日目に+5%、2日目にも+5%と上昇した。コストなしと仮定したとき、−1倍のインバース型商品の2日後の価値は、当初の100に対していくらになるか。`,options:[{id:`a`,text:`90.25`},{id:`b`,text:`90`},{id:`c`,text:`110.25`},{id:`d`,text:`95`}],correctIds:[`a`],explanation:`インバース型は日次の騰落率に−1倍をかけるため、100 × (1 − 0.05) × (1 − 0.05) ＝ 100 × 0.95 × 0.95 ＝ 90.25 である。日次リセットのため、2日分の騰落をまとめて計算はしない。`,wrongExplanations:{b:`日次騰落率を単純に合計した+10%に、−1倍をまとめて適用した計算である（100×（1−0.10）＝90）。日次リセットでは1日ごとに倍率がかかるため、複数日の騰落率を合計してから倍率をかけることはできない。`,c:`原指数そのものの2日後の値（100 × 1.05 × 1.05）である。インバース型では日々の符号が逆になる。`,d:`1日分だけを反映した値である。2日目は95に対してさらに−5%がかかる。`},assumptions:`手数料・コスト・乖離はなく、日次騰落率に正確に倍率がかかるものとする。`,sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F03-4`,lessonId:`F-03`,type:`single`,difficulty:2,skill:`understand`,prompt:`レバレッジ型商品について「原指数の期間騰落率だけからは、その期間のリターンを計算できない」とされる理由はどれか。`,options:[{id:`a`,text:`運用会社が手数料率や経費を公表していないため、期間リターンを計算できないから`},{id:`b`,text:`原指数に配当が含まれており、配当込みで倍率をかけると期間騰落率と一致しないため`},{id:`c`,text:`倍率が日次でかけ直され、結果が日々の値動きの経路に依存するため`},{id:`d`,text:`商品の対象指数が日々入れ替わるため、期間中の指数を特定できないから`}],correctIds:[`c`],explanation:`レバレッジ型は日次リセットで毎日の騰落に倍率をかけるため、同じ期間騰落率でも、値動きの経路（一方向に動くか、上下を繰り返すか）によって結果が変わる。これを経路依存性という。`,wrongExplanations:{a:`手数料は結果を目減りさせる要素だが、期間騰落率から計算できない本質的な理由は経路依存性である。`,b:`配当の扱いは指数の設計の話であり、日次リセットによる経路依存性とは別の問題である。`,d:`対象指数が日々入れ替わるわけではない。倍率のかけ直しが理由である。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F04-3`,lessonId:`F-04`,type:`single`,difficulty:1,skill:`calculate`,prompt:`株式70%（リターン8%）と債券30%（リターン1%）からなるポートフォリオの加重平均リターンはいくらか。`,options:[{id:`a`,text:`4.5%`},{id:`b`,text:`9%`},{id:`c`,text:`5.6%`},{id:`d`,text:`5.9%`}],correctIds:[`d`],explanation:`加重平均リターン ＝ 0.7 × 8 ＋ 0.3 × 1 ＝ 5.6 ＋ 0.3 ＝ 5.9% である。各資産のリターンを保有比率で重み付けして合計する。`,wrongExplanations:{a:`比率で重み付けせず単純平均した計算である（(8 ＋ 1) ÷ 2）。保有比率が異なるため単純平均は使えない。`,b:`2つのリターンをそのまま合計した値である。比率の概念が抜けている。`,c:`株式の寄与（5.6%）だけを計算し、債券の寄与（0.3%）を足し忘れた値である。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-F04-4`,lessonId:`F-04`,type:`single`,difficulty:2,skill:`find-error`,prompt:`為替ヘッジに関する説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`為替ヘッジには、金利差に応じたコスト（または受取り）がかかる`},{id:`b`,text:`為替ヘッジをすれば、為替変動の影響とコストの両方を完全になくすことができる`},{id:`c`,text:`ヘッジ付きが常に有利とは限らない`},{id:`d`,text:`外貨建て資産の円換算リターンは、現地通貨建てのリターンと為替変動の両方で決まる`}],correctIds:[`b`],explanation:`為替ヘッジは為替変動の影響を抑える代わりに、金利差に応じたヘッジコストが発生する。リスクとコストの両方が消えるわけではなく、「完全になくすことができる」は誤りである。`,wrongExplanations:{a:`正しい説明である。ヘッジコストは2国間の金利差に左右される。`,c:`正しい説明である。コストの分だけ、ヘッジなしより不利になる局面もある。`,d:`正しい説明である。厳密には (1＋現地リターン） × (1＋為替変動率） − 1 で計算する。`},sources:[e.fsaInvest],reviewStatus:`verified`}];i.push({id:`Q-G01-1`,lessonId:`G-01`,type:`single`,difficulty:1,skill:`understand`,prompt:`電子署名の検証に関する説明として正しいものはどれか。`,options:[{id:`a`,text:`署名は秘密鍵で作られ、対応する公開鍵で誰でも検証できる`},{id:`b`,text:`署名は公開鍵で作られ、対応する秘密鍵を持つ者だけが検証できる`},{id:`c`,text:`署名を検証するには署名者の秘密鍵が必要である`},{id:`d`,text:`電子署名は取引内容が経済的に正しいことを保証する`}],correctIds:[`a`],explanation:`電子署名は秘密鍵で作成し、公開鍵で検証します。秘密鍵を知らない者は正しい署名を作れないため、本人性と改ざんの有無を確認できます。`,wrongExplanations:{b:`作成と検証の鍵が逆です。秘密鍵で作り、公開鍵で検証します。`,c:`検証に秘密鍵は不要です。公開鍵で誰でも検証できる点が仕組みの要です。`,d:`署名が保証するのは作成者とデータの整合性であり、取引内容の経済的な正しさではありません。`},sources:[e.bitcoinPaper],reviewStatus:`verified`},{id:`Q-G01-2`,lessonId:`G-01`,type:`single`,difficulty:1,skill:`find-error`,prompt:`ハッシュ関数に関する説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`入力がわずかに変わると出力が大きく変わる性質がある`},{id:`b`,text:`ハッシュ値から復号して元のデータをそのまま取り出せる`},{id:`c`,text:`ブロックに直前のブロックのハッシュ値を含めることで改ざんを検知しやすくしている`},{id:`d`,text:`ハッシュ化と暗号化は異なる概念である`}],correctIds:[`b`],explanation:`ハッシュ関数は一方向の変換であり、出力から入力を復元することは想定されていません。復号を前提とする暗号化とは異なります。`,wrongExplanations:{a:`正しい説明です。雪崩効果と呼ばれる性質です。`,c:`正しい説明です。過去の記録を書き換えると以降のハッシュが合わなくなります。`,d:`正しい説明です。ハッシュは復号を前提としません。`},sources:[e.nistFips1804],reviewStatus:`verified`},{id:`Q-G02-1`,lessonId:`G-02`,type:`single`,difficulty:2,skill:`calculate`,prompt:`ブロック生成間隔を約10分、ブロック報酬を3.125BTCとして、1日あたりの新規発行量の近似値はいくらか。`,options:[{id:`a`,text:`900BTC`},{id:`b`,text:`450BTC`},{id:`c`,text:`312.5BTC`},{id:`d`,text:`45BTC`}],correctIds:[`b`],explanation:`1日のブロック数は 24 × 60 ÷ 10 ＝ 144。新規発行量は 3.125 × 144 ＝ 450BTC（実際の生成間隔は変動するため近似値）。報酬が6.25BTCの時期は900BTCであり、半減期で半分になります。`,wrongExplanations:{a:`ブロック報酬6.25BTC時代の値です。本問の3.125BTCでは半分になります。`,c:`ブロック数を100として計算した誤りです。1日は144ブロックです。`,d:`桁を取り違えた計算です。`},assumptions:`ブロック生成間隔は目標値の10分で一定とみなす。`,sources:[e.bitcoinPaper],reviewStatus:`verified`},{id:`Q-G02-2`,lessonId:`G-02`,type:`single`,difficulty:2,skill:`understand`,prompt:`UTXOモデルで、使えるUTXOが10BTC分ある状態から6BTCを送金した。残りの扱いとして正しいものはどれか。`,options:[{id:`a`,text:`元のUTXOの中身が6BTC分だけ書き換えられ、4BTCがそのまま残る`},{id:`b`,text:`元のUTXOは消費され、送金先への6BTCのUTXOと、自分へのお釣り約4BTC（手数料を除く）のUTXOが新しく作られる`},{id:`c`,text:`残高という数値が中央の台帳で10から4に更新される`},{id:`d`,text:`お釣りはマイナーへの報酬として自動的に消える`}],correctIds:[`b`],explanation:`UTXOモデルでは入力のUTXOは丸ごと消費され、送金額とお釣りのUTXOが新たに出力として作られます。残高は保有するUTXOの合計として表されます。`,wrongExplanations:{a:`UTXOは部分的に書き換えるものではなく、消費と生成で扱います。`,c:`残高を中央台帳の数値として管理するのはアカウントモデルの発想です。`,d:`お釣りは自分の新しいUTXOとして戻ります。手数料とは別です。`},sources:[e.bitcoinPaper],reviewStatus:`verified`},{id:`Q-G03-1`,lessonId:`G-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`ガス使用量50,000、ガス価格30Gweiの取引の手数料はいくらか。ただし1ETH＝10^9 Gweiとする。`,options:[{id:`a`,text:`1.5ETH`},{id:`b`,text:`0.015ETH`},{id:`c`,text:`0.0015ETH`},{id:`d`,text:`0.00015ETH`}],correctIds:[`c`],explanation:`手数料 ＝ 50,000 × 30 ＝ 1,500,000Gwei。ETH換算は 1,500,000 ÷ 10^9 ＝ 0.0015ETH。手数料は送金額ではなく計算量とガス価格で決まります。`,wrongExplanations:{a:`GweiからETHへの換算（10^9で割る）をしていない誤りです。`,b:`換算の桁が1つずれています。`,d:`換算の桁が1つずれて小さくなっています。`},sources:[e.ethereumGas],reviewStatus:`verified`},{id:`Q-G03-2`,lessonId:`G-03`,type:`single`,difficulty:2,skill:`compare`,prompt:`アカウントモデルとUTXOモデルの違いとして正しいものはどれか。`,options:[{id:`a`,text:`アカウントモデルは残高を口座の数値として保持し、UTXOモデルは未使用の取引出力の集合で所有を表す`},{id:`b`,text:`UTXOモデルは中央管理者が残高を管理し、アカウントモデルは管理者がいない`},{id:`c`,text:`アカウントモデルではスマートコントラクトを実行できない`},{id:`d`,text:`両モデルに実質的な違いはない`}],correctIds:[`a`],explanation:`Ethereumはアカウント（口座）の残高として状態を管理し、BitcoinはUTXOの集合で所有を表します。どちらも分散台帳の上で管理され、中央管理者の有無の違いではありません。`,wrongExplanations:{b:`どちらも分散した参加者によって維持される台帳です。管理方式の説明が誤っています。`,c:`スマートコントラクトを実行できるのはアカウントモデルを採るEthereumの特徴です。`,d:`状態の持ち方、プライバシー特性、並行処理のしやすさなどに実質的な違いがあります。`},sources:[e.ethereumDocs,e.bitcoinPaper],reviewStatus:`verified`},{id:`Q-G04-1`,lessonId:`G-04`,type:`single`,difficulty:1,skill:`apply`,prompt:`利用中のサービスを名乗る画面が表示され、「本人確認のためシードフレーズを入力してください」と求められた。適切な対応はどれか。`,options:[{id:`a`,text:`正規の本人確認手続きの可能性があるので、指示どおり入力して確認する`},{id:`b`,text:`入力せず画面を閉じ、詐欺を疑って公式な経路で事実を確認する`},{id:`c`,text:`シードフレーズの一部だけを入力して様子を見る`},{id:`d`,text:`画面の案内に従い、電話で読み上げて伝える`}],correctIds:[`b`],explanation:`シードフレーズを入力させる正規の確認手続きは存在しません。入力を求める画面や連絡は原則として詐欺を疑い、入力せずに公式経路で確認するのが適切です。本アプリも秘密鍵・シードフレーズの入力機能を持ちません。`,wrongExplanations:{a:`シードフレーズが漏れれば資産を一方的に移転される恐れがあり、取り返しがつきません。`,c:`一部であっても漏らしてはいけません。推測や総当たりの手がかりになります。`,d:`読み上げも漏洩です。入力と同じく絶対に行ってはいけません。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-G04-2`,lessonId:`G-04`,type:`single`,difficulty:1,skill:`understand`,prompt:`ウォレットの役割の説明として正しいものはどれか。`,options:[{id:`a`,text:`ウォレットの中に暗号資産そのものがファイルとして保存されている`},{id:`b`,text:`ウォレットは鍵を管理し、取引への署名を作る道具であり、資産の記録自体はブロックチェーン上にある`},{id:`c`,text:`ウォレットは取引所の口座と全く同じものである`},{id:`d`,text:`ウォレットが壊れれば、シードフレーズがあっても資産は必ず失われる`}],correctIds:[`b`],explanation:`資産の記録はブロックチェーン上にあり、ウォレットは署名に必要な鍵を管理する道具です。だからこそ鍵とシードフレーズの保管が資産の安全性を左右します。`,wrongExplanations:{a:`資産はウォレット内ではなくブロックチェーン上に記録されています。`,c:`取引所が鍵を預かるカストディ形態と、自分で鍵を管理するウォレットは区別されます。`,d:`シードフレーズが安全に保管されていれば、別の端末やウォレットで鍵を復元できます。`},sources:[e.fsaCrypto,e.bitcoinPaper],reviewStatus:`verified`},{id:`Q-G01-3`,lessonId:`G-01`,type:`single`,difficulty:1,skill:`calculate`,prompt:`教材の玩具ハッシュ h ＝ （数値列の合計） mod 10 を使って、データ列 2, 5, 8 のハッシュ値を求めよ。`,options:[{id:`a`,text:`15`},{id:`b`,text:`1`},{id:`c`,text:`3`},{id:`d`,text:`5`}],correctIds:[`d`],explanation:`合計は 2 ＋ 5 ＋ 8 ＝ 15 で、h ＝ 15 mod 10 ＝ 5 である。mod 10 は、10で割った余りを取る操作である。`,wrongExplanations:{a:`余りを取る前の合計そのものである。mod 10 の計算が抜けている。`,b:`15 ÷ 10 の商（1）であり、求めるのは余りの方である。`,c:`データの個数（3個）であり、ハッシュ値ではない。`},assumptions:`玩具ハッシュは教材用の単純化モデルであり、実際の暗号学的ハッシュ関数とは強度が異なる。`,sources:[e.nistFips1804],reviewStatus:`verified`},{id:`Q-G01-4`,lessonId:`G-01`,type:`single`,difficulty:2,skill:`apply`,prompt:`ある参加者が、過去のブロックに記録された取引を書き換えた。この改ざんが検知される仕組みとして正しいものはどれか。`,options:[{id:`a`,text:`書き換えてもハッシュ値は変わらないため、検知はできない`},{id:`b`,text:`書き換えたブロックだけが無効になり、それ以外には影響しない`},{id:`c`,text:`そのブロックのハッシュ値が変わり、後続のブロックに記録された直前ブロックのハッシュ値と一致しなくなる`},{id:`d`,text:`書き換えと同時にネットワーク全体の台帳が自動的に消去される`}],correctIds:[`c`],explanation:`各ブロックには直前のブロックのハッシュ値が含まれている。過去の記録を書き換えるとそのブロックのハッシュ値が変わり、後続のブロックが保持する値と一致しなくなるため、改ざんを検知できる。`,wrongExplanations:{a:`入力がわずかに変わるだけでハッシュ値は大きく変わる（雪崩効果）。変わるからこそ検知できる。`,b:`影響はそのブロックだけにとどまらない。後続ブロックとの整合が取れなくなる点が検知の仕組みである。`,d:`台帳が消去されるわけではない。多数の参加者が台帳を共有しており、整合しない書き換えは受け入れられない。`},sources:[e.bitcoinPaper],reviewStatus:`verified`},{id:`Q-G02-3`,lessonId:`G-02`,type:`single`,difficulty:2,skill:`calculate`,prompt:`ブロック報酬が210,000ブロックごとに半減し続けるとき、理論上の総発行量はおよそいくらか。ただし最初の期間の発行量は 50BTC × 210,000ブロック ＝ 1,050万BTC であり、1 ＋ 1/2 ＋ 1/4 ＋ … ＝ 2 を使って計算する。`,options:[{id:`a`,text:`約1,050万BTC`},{id:`b`,text:`無限に増え続ける`},{id:`c`,text:`約4,200万BTC`},{id:`d`,text:`約2,100万BTC`}],correctIds:[`d`],explanation:`総発行量 ≒ 1,050万BTC × (1 ＋ 1/2 ＋ 1/4 ＋ …) ＝ 1,050万 × 2 ＝ 約2,100万BTC である。端数処理のため厳密な総量はこれをわずかに下回る。これが発行上限の根拠となる計算である。`,wrongExplanations:{a:`最初の半減期間だけの発行量である。その後の期間の発行も合計する必要がある。`,b:`半減によって各期間の発行量は等比級数的に減るため、合計は有限の値に収束する。`,c:`等比級数の和を4とした誤りである。1 ＋ 1/2 ＋ 1/4 ＋ … の和は2である。`},sources:[e.bitcoinPaper],reviewStatus:`verified`},{id:`Q-G02-4`,lessonId:`G-02`,type:`single`,difficulty:2,skill:`find-error`,prompt:`Bitcoinのファイナリティ（取引の確定）に関する説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`後ろにブロックが積み重なるほど、書き換えは困難になる`},{id:`b`,text:`取引が1つのブロックに入った時点で、数学的に完全確定し書き換えは絶対に不可能になる`},{id:`c`,text:`確定の度合いは確率的であり、絶対に確定する瞬間というものはない`},{id:`d`,text:`PoWの安全性は、攻撃者が全計算能力の過半を握ることが経済的に割に合わないという前提に依存する`}],correctIds:[`b`],explanation:`PoWの確定は確率的である。1つのブロックに入っただけでは完全確定とは言えず、後続ブロックの積み重ねによって書き換えが現実的に困難になっていく。「絶対に不可能になる」は誤りである。`,wrongExplanations:{a:`正しい説明である。書き換えには後続すべてのブロックの計算をやり直す必要が生じる。`,c:`正しい説明である。これをファイナリティの確率的性質という。`,d:`正しい説明である。計算能力の集中が進むと、この前提は弱まる。`},sources:[e.bitcoinPaper],reviewStatus:`verified`},{id:`Q-G03-3`,lessonId:`G-03`,type:`single`,difficulty:1,skill:`understand`,prompt:`PoSにおいて、不正を行った検証者（バリデーター）が預けた通貨の一部または全部を失う仕組みを何と呼ぶか。`,options:[{id:`a`,text:`ロールアップ`},{id:`b`,text:`ガス`},{id:`c`,text:`スラッシング`},{id:`d`,text:`ブリッジ`}],correctIds:[`c`],explanation:`スラッシングは、PoSで不正を行った検証者の預け資産を没収する仕組みであり、誠実な行動を促すために設けられている。`,wrongExplanations:{a:`ロールアップは、L2で多数の取引をまとめてL1に記録する技術であり、検証者への罰則ではない。`,b:`ガスはスマートコントラクト実行の手数料の単位であり、没収の仕組みではない。`,d:`ブリッジは異なるチェーン間で資産を移す仕組みであり、検証者への罰則ではない。`},sources:[e.ethereumDocs],reviewStatus:`verified`},{id:`Q-G03-4`,lessonId:`G-03`,type:`single`,difficulty:2,skill:`apply`,prompt:`L2に置いた資産を別のチェーンへ移すためブリッジを利用した。この利用に関して特に注意すべき点として、教材の内容に合うものはどれか。`,options:[{id:`a`,text:`ブリッジ経由で受け取った資産は、元のL1上の資産と常に全く同じ安全性が保証される`},{id:`b`,text:`ブリッジは資産を預かる構造を持つため、過去に大きな不正流出の対象となってきた`},{id:`c`,text:`ブリッジを使う取引では、ガス代は一切かからない`},{id:`d`,text:`ロールアップはL1に一切データを記録しないため、検証の必要がない`}],correctIds:[`b`],explanation:`ブリッジは資産を預かる構造上、不正流出の対象となってきた要注意の要素である。L2やブリッジの安全性はL1と同一ではなく、構造固有のリスクを理解して使う必要がある。`,wrongExplanations:{a:`L2の資産の安全性はL1と全く同じではない。ブリッジや運営構造に固有のリスクがある。`,c:`取引には手数料（ガス）がかかる。かからないという保証はない。`,d:`ロールアップは取引の結果やデータをL1に記録することで成り立つ。記録しないという説明は誤りである。`},sources:[e.ethereumDocs],reviewStatus:`verified`},{id:`Q-G04-3`,lessonId:`G-04`,type:`single`,difficulty:1,skill:`calculate`,prompt:`秘密鍵の候補数はビット長で決まる。8ビットの鍵は 2^8 ＝ 256通りである。では16ビットの鍵の候補数は何通りか。`,options:[{id:`a`,text:`512通り`},{id:`b`,text:`1,024通り`},{id:`c`,text:`65,536通り`},{id:`d`,text:`4,096通り`}],correctIds:[`c`],explanation:`候補数は 2^16 ＝ 65,536通りである。ビット長が2倍になると候補数は2倍ではなく 2^8 倍（256倍）になる。256ビットでは候補数がおよそ10^77通りとなり、総当たりは現実的でなくなる。`,wrongExplanations:{a:`ビット長が2倍だから候補数も2倍（256 × 2）という誤りである。候補数は指数的に増える。`,b:`2^10 で計算した値である。16ビットは 2^16 で計算する。`,d:`2^12 で計算した値である。指数の取り違えに注意する。`},sources:[e.bitcoinPaper],reviewStatus:`verified`},{id:`Q-G04-4`,lessonId:`G-04`,type:`single`,difficulty:1,skill:`find-error`,prompt:`鍵の管理形態に関する説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`ホットウォレットは、インターネットに接続した端末で鍵を扱うため利便性が高い`},{id:`b`,text:`取引所など第三者が鍵を管理するカストディでは、事業者が破綻しても利用者の資産には一切影響がない`},{id:`c`,text:`コールドウォレットは鍵をオフラインに保ち、大きな金額の保管に向く`},{id:`d`,text:`シードフレーズは、紙などオフラインの手段で安全に保管することが原則とされる`}],correctIds:[`b`],explanation:`カストディでは第三者が鍵を管理するため、その事業者の破綻リスクを利用者も引き受ける。「一切影響がない」は誤りである。`,wrongExplanations:{a:`正しい説明である。ただし利便性と引き換えに、マルウェア等のリスクにさらされる。`,c:`正しい説明である。ただし購入経路の改ざんや保管ミスなど、別のリスクは残る。`,d:`正しい説明である。写真やクラウドに保存すると漏洩の経路が広がる。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-H01-1`,lessonId:`H-01`,type:`single`,difficulty:2,skill:`calculate`,prompt:`価格5ドル、流通供給量2,000万トークン、最大供給量5,000万トークンのとき、FDV（完全希薄化後評価額）はいくらか。`,options:[{id:`a`,text:`1億ドル`},{id:`b`,text:`2.5億ドル`},{id:`c`,text:`1.5億ドル`},{id:`d`,text:`2,500万ドル`}],correctIds:[`b`],explanation:`FDV ＝ 価格 × 最大供給量 ＝ 5 × 5,000万 ＝ 2.5億ドル。なお時価総額は 5 × 2,000万 ＝ 1億ドルであり、未発行分を含むFDVとは区別します（価格が現在値のままという仮定の計算です）。`,wrongExplanations:{a:`それは流通供給量で計算した時価総額です。FDVは最大供給量を使います。`,c:`未発行分（最大供給量−流通供給量＝5,000万−2,000万＝3,000万）だけに価格を掛けた値です。FDVは最大供給量の全体に価格を掛けます。`,d:`最大供給量の桁を読み違えた計算です（5ドル×500万＝2,500万ドル）。`},assumptions:`現在の価格が全量発行時も維持されるというFDV定義上の仮定に基づく。`,sources:[e.coingeckoFdv],reviewStatus:`verified`},{id:`Q-H01-2`,lessonId:`H-01`,type:`single`,difficulty:2,skill:`understand`,prompt:`「トークンアンロック」の説明として正しいものはどれか。`,options:[{id:`a`,text:`新規発行によって、トークン供給量の上限そのものが引き上げられること`},{id:`b`,text:`ロックされていた既存の割当分が、譲渡・売却可能になること`},{id:`c`,text:`トークンがバーンされて流通から除去されること`},{id:`d`,text:`取引所が上場を廃止すること`}],correctIds:[`b`],explanation:`アンロックは、創業者や投資家への割当分などロックされていたトークンが売却可能になる出来事です。新規発行ではありませんが、市場に出回り得る量が増えるため売り圧力の観点で確認されます。`,wrongExplanations:{a:`上限の引き上げは発行スケジュールや仕様変更の話で、アンロックとは異なります。`,c:`バーンは供給を減らす操作であり、アンロックの逆方向の出来事です。`,d:`上場廃止は取引所側の措置であり、トークンのロックとは関係ありません。`},sources:[e.coingeckoFdv],reviewStatus:`verified`},{id:`Q-H02-1`,lessonId:`H-02`,type:`single`,difficulty:2,skill:`calculate`,prompt:`永久先物の建玉の想定元本が200万円、資金調達率が1回あたり+0.03%で、この建玉が支払う側だとする。1回あたりの資金調達の支払額はいくらか。`,options:[{id:`a`,text:`60円`},{id:`b`,text:`600円`},{id:`c`,text:`6,000円`},{id:`d`,text:`60,000円`}],correctIds:[`b`],explanation:`支払額 ＝ 想定元本 × 資金調達率 ＝ 2,000,000 × 0.0003 ＝ 600円。価格が動かなくても、建玉を維持するだけでこのコストが回数分積み上がります。`,wrongExplanations:{a:`率を0.003%として計算した誤りです。`,c:`率を0.3%として計算した誤りです。`,d:`桁を取り違えた計算です。`},assumptions:`資金調達率の符号と支払い側は取引所の規則に従うものとし、本問では支払う側と明示した。`,sources:[e.dydxFunding],reviewStatus:`verified`},{id:`Q-H02-2`,lessonId:`H-02`,type:`single`,difficulty:3,skill:`understand`,prompt:`オンチェーン指標の解釈の限界として正しいものはどれか。`,options:[{id:`a`,text:`取引所の内部で完結する取引はブロックチェーンの台帳に現れないため、市場全体を完全には捉えられない`},{id:`b`,text:`オンチェーンのデータはすべて改ざんされている前提で扱うべきである`},{id:`c`,text:`アドレスと所有者の対応は常に完全に公開されている`},{id:`d`,text:`大口アドレスの資金移動を見れば、売買の意図と将来の価格が確定する`}],correctIds:[`a`],explanation:`公開台帳に現れるのはオンチェーンの移転のみで、取引所内部の売買は現れません。アドレスと所有者の対応も不完全なため、指標は観測事実として扱い、意図や価格の断定には使いません。`,wrongExplanations:{b:`オンチェーン記録は改ざん困難性を持つ公開データです。問題は網羅性と解釈の側にあります。`,c:`アドレスの所有者は一般に公開されておらず、推定に頼る部分が大きいのが実情です。`,d:`自己管理ウォレット間の移動など複数の解釈があり、意図も将来価格も確定しません。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-H03-1`,lessonId:`H-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`担保資産8,000万ドル相当に対して5,000万ドル分のステーブルコインが発行されている。担保比率はいくらか。`,options:[{id:`a`,text:`62.5%`},{id:`b`,text:`100%`},{id:`c`,text:`160%`},{id:`d`,text:`260%`}],correctIds:[`c`],explanation:`担保比率 ＝ 担保価値 ÷ 発行額面総額 × 100 ＝ 8,000万 ÷ 5,000万 × 100 ＝ 160%。ただし比率は担保価格の変動で下がり得るため、この値だけで安全性が完結するわけではありません。`,wrongExplanations:{a:`分子と分母を逆にした計算です（5,000万 ÷ 8,000万）。`,b:`担保と発行額が等しい場合の値であり、本問の数値とは異なります。`,d:`担保と発行額を合計して割るなど、比率の定義を取り違えた計算です。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-H03-2`,lessonId:`H-03`,type:`single`,difficulty:2,skill:`apply`,prompt:`法定通貨担保型ステーブルコインを評価する際、価格チャート以外に確認すべき項目として最も適切なものはどれか。`,options:[{id:`a`,text:`準備資産の内訳と開示状況、および額面で償還できる条件`},{id:`b`,text:`過去1年間ペッグが一度も崩れていないという価格の実績のみ`},{id:`c`,text:`発行体の広告やSNSでの評判`},{id:`d`,text:`取引所の取扱銘柄数の多さ`}],correctIds:[`a`],explanation:`法定通貨担保型のペッグの根拠は、準備資産の実在と質、そして保有者が額面で償還できることです。担保の開示と償還条件の確認が評価の出発点になります。`,wrongExplanations:{b:`価格安定の実績は将来の安定を保証しません。裏付けの確認が先です。`,c:`宣伝や評判は検証可能な裏付けにはなりません。`,d:`取扱いの広さは流動性の目安にはなっても、担保の健全性を示しません。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-H04-1`,lessonId:`H-04`,type:`single`,difficulty:3,skill:`calculate`,prompt:`定数積AMM（x × y ＝ k、手数料なし）で、資産Aと資産Bが各200ずつ入ったプールに資産Aを20投入する。受け取れる資産Bはおよそいくらか。`,options:[{id:`a`,text:`20`},{id:`b`,text:`約18.18`},{id:`c`,text:`約16.67`},{id:`d`,text:`約22`}],correctIds:[`b`],explanation:`k ＝ 200 × 200 ＝ 40,000。投入後は A ＝ 220 になるため、Bは 40,000 ÷ 220 ≒ 181.82 がプールに残り、受け取りは 200 − 181.82 ≒ 18.18。投入量より受け取りが少ないのは、取引自体がプール内比率を動かす価格影響のためです。`,wrongExplanations:{a:`プール内比率が変わらないと仮定した誤りです。AMMでは取引で比率が動き、等量交換にはなりません。`,c:`kの計算または割り算過程の誤りです。再計算すると約18.18になります。`,d:`受け取りが投入を上回ることは、定数積の仕組み上あり得ません（手数料なし条件）。`},assumptions:`手数料なし、単一の取引のみで、外部市場との裁定は考えない。`,sources:[e.uniswapV3],reviewStatus:`verified`},{id:`Q-H04-2`,lessonId:`H-04`,type:`single`,difficulty:3,skill:`understand`,prompt:`DeFiにおけるオラクルの役割とリスクの説明として正しいものはどれか。`,options:[{id:`a`,text:`オラクルは秘密鍵を保管する装置であり、価格とは無関係である`},{id:`b`,text:`オラクルは外部の価格情報をスマートコントラクトに伝え、誤った価格が伝わると不当な清算や借入が起こり得る`},{id:`c`,text:`オラクルがあればスマートコントラクトのプログラムの欠陥は自動で修正される`},{id:`d`,text:`オラクルは取引の順序を操作して利益を得る行為そのものを指す`}],correctIds:[`b`],explanation:`レンディング等のDeFiは担保評価に外部価格を必要とし、その伝達役がオラクルです。価格情報の異常は清算や借入の誤作動に直結します。なお取引順序を利用する行為はMEVであり、オラクルとは別の概念です。`,wrongExplanations:{a:`オラクルは価格などの外部データの伝達仕組みであり、鍵の保管装置ではありません。`,c:`オラクルはデータ供給の仕組みで、プログラムの欠陥を修正する機能はありません。欠陥はそのまま実行されます。`,d:`それはMEV（フロントランニング等）の説明であり、オラクルの説明ではありません。`},sources:[e.ethereumDocs,e.fsaCrypto],reviewStatus:`verified`},{id:`Q-H01-3`,lessonId:`H-01`,type:`single`,difficulty:2,skill:`calculate`,prompt:`価格3ドル、流通供給量4,000万トークン、最大供給量8,000万トークンのとき、時価総額はいくらか。`,options:[{id:`a`,text:`1.2億ドル`},{id:`b`,text:`2.4億ドル`},{id:`c`,text:`1.8億ドル`},{id:`d`,text:`4,000万ドル`}],correctIds:[`a`],explanation:`時価総額 ＝ 価格 × 流通供給量 ＝ 3 × 4,000万 ＝ 1.2億ドルである。最大供給量で計算した2.4億ドルはFDVであり、時価総額とは区別する。`,wrongExplanations:{b:`最大供給量で計算した値であり、それはFDVである。時価総額には流通供給量を使う。`,c:`流通供給量と最大供給量の平均（6,000万）で計算した誤りである。時価総額は流通供給量のみを使う。`,d:`流通供給量そのものであり、価格を掛けていない。`},assumptions:`価格は現在の値のままとする。`,sources:[e.coingeckoFdv],reviewStatus:`verified`},{id:`Q-H01-4`,lessonId:`H-01`,type:`single`,difficulty:2,skill:`apply`,prompt:`あるトークンでは、ステーキング報酬が年率10%と表示されている。一方、そのトークンの新規発行によるインフレ率は年率12%である。ネットワーク全体に対する自分の保有割合の観点で正しいものはどれか。`,options:[{id:`a`,text:`報酬を受け取るため、保有割合は必ず10%増える`},{id:`b`,text:`インフレ率は保有割合には無関係である`},{id:`c`,text:`バーンさえあれば、保有割合は必ず増える`},{id:`d`,text:`名目の保有量は増えても、発行による希薄化が上回り、保有割合は低下し得る`}],correctIds:[`d`],explanation:`ステーキング報酬の原資が新規発行である場合、自分の報酬率（10%）が全体のインフレ率（12%）を下回れば、ネットワーク全体に対する保有割合は相対的に下がる。名目の利回りだけでなく、希薄化を差し引いて考える必要がある。`,wrongExplanations:{a:`報酬は保有量を増やすが、割合は全体の発行量との比較で決まる。必ず増えるとは言えない。`,b:`新規発行は全保有者の割合を薄めるため、保有割合に直接関係する。`,c:`バーンは供給を減らす要素だが、発行量との差し引きで決まるため、必ず増えるとは限らない。`},sources:[e.coingeckoFdv],reviewStatus:`verified`},{id:`Q-H02-3`,lessonId:`H-02`,type:`single`,difficulty:2,skill:`understand`,prompt:`永久先物と、満期のある通常の先物の違いとして正しいものはどれか。`,options:[{id:`a`,text:`永久先物には満期がなく、資金調達率の仕組みによって現物価格へ近づける`},{id:`b`,text:`永久先物は満期日に現物を受け渡して決済する`},{id:`c`,text:`通常の先物には満期が存在しない`},{id:`d`,text:`両者は仕組みの上で区別されない`}],correctIds:[`a`],explanation:`永久先物には満期がない。満期による現物価格への収束が働かない代わりに、資金調達率の授受によって現物価格へ近づける設計になっている。`,wrongExplanations:{b:`満期日の受け渡しは通常の先物の決済方法である。永久先物に満期日はない。`,c:`通常の先物には満期が存在する。説明が逆になっている。`,d:`満期の有無と、価格を現物へ寄せる仕組みに明確な違いがある。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-H02-4`,lessonId:`H-02`,type:`single`,difficulty:2,skill:`apply`,prompt:`価格が短時間に急落した局面で、レバレッジをかけた買い建玉の強制決済が次々に発生し、売りが売りを呼んで下落が加速した。この現象の説明として正しいものはどれか。`,options:[{id:`a`,text:`証拠金が維持水準を割り込んだ建玉の清算が連鎖し、決済の売りが価格下落をさらに促した`},{id:`b`,text:`資金調達率の支払いが一斉に行われたためである`},{id:`c`,text:`オンチェーン指標を市場参加者が誤って解釈したためである`},{id:`d`,text:`取引所の分別管理が不十分だったためである`}],correctIds:[`a`],explanation:`証拠金が維持水準を割り込んだ建玉は強制的に決済（清算）され、その決済の売りが価格をさらに押し下げ、次の清算を誘発する。これが清算の連鎖であり、短時間の大きな変動の要因になる。`,wrongExplanations:{b:`資金調達率は定期的な調整金の授受であり、強制決済の連鎖とは別の仕組みである。コスト要因ではあっても、急落を増幅する機構ではない。`,c:`オンチェーン指標の解釈は市場心理の背景にはなり得るが、強制決済の連鎖という増幅の仕組みそのものではない。`,d:`分別管理は事業者破綻時の資産保全の話であり、価格急落の増幅とは関係がない。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-H03-3`,lessonId:`H-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`担保資産200ドル相当に対して100ドル分の暗号資産担保型ステーブルコインが発行されている（担保比率200%）。担保価格が25%下落した後の担保比率はいくらか。`,options:[{id:`a`,text:`200%`},{id:`b`,text:`175%`},{id:`c`,text:`150%`},{id:`d`,text:`75%`}],correctIds:[`c`],explanation:`下落後の担保価値は 200 × (1 − 0.25) ＝ 150ドル相当である。担保比率 ＝ 150 ÷ 100 × 100 ＝ 150% である。過剰担保が緩衝材として働いた形だが、下落が続けば清算水準に近づく。`,wrongExplanations:{a:`担保価格の下落を反映していない値である。担保価値は市場価格で変動する。`,b:`下落率を半分の12.5%として計算した値である（200 × 0.875 ＝ 175）。本問の下落率は25%である。`,d:`下落後の担保価値を元の担保価値で割った値である（150 ÷ 200）。担保比率の分母は発行済みステーブルコインの額面総額である。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-H03-4`,lessonId:`H-03`,type:`single`,difficulty:2,skill:`find-error`,prompt:`ステーブルコインに関する説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`法定通貨担保型のペッグの根拠は、準備資産の保有と額面での償還である`},{id:`b`,text:`ステーブルコインは銀行預金と全く同じものであり、預金保険の対象になる`},{id:`c`,text:`暗号資産担保型では、担保価値の低下に備えて過剰担保と自動清算が用いられる`},{id:`d`,text:`価格が長く安定してきた実績は、将来もペッグが崩れないことの保証にはならない`}],correctIds:[`b`],explanation:`ステーブルコインは銀行預金ではなく、預金保険の対象でもない。その安定性は発行体と担保の仕組みに依存する。「銀行預金と全く同じ」は誤りである。`,wrongExplanations:{a:`正しい説明である。準備資産の実在と質、償還条件の確認が評価の出発点になる。`,c:`正しい説明である。価格変動の大きい担保を使うため、過剰担保と清算で健全性を保つ設計である。`,d:`正しい説明である。過去には安定した実績のあった設計でもペッグが大きく崩れた事例が知られている。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-H04-3`,lessonId:`H-04`,type:`single`,difficulty:2,skill:`calculate`,prompt:`あるDeFiレンディングでは、借入は担保価値の60%まで可能と定められている。担保として20万円相当の暗号資産を預けた場合、借入上限はいくらか。`,options:[{id:`a`,text:`20万円`},{id:`b`,text:`12万円`},{id:`c`,text:`8万円`},{id:`d`,text:`約33.3万円`}],correctIds:[`b`],explanation:`借入上限 ＝ 担保価値 × 60% ＝ 20万円 × 0.6 ＝ 12万円である。担保価値の全額を借りられるわけではなく、上限と清算水準の管理がレンディングの要点である。`,wrongExplanations:{a:`担保価値の全額であり、上限の割合を適用していない。過剰担保の仕組みでは全額は借りられない。`,c:`残りの40%（1 − 0.6）を掛けた値である。借入上限は担保価値に60%を掛ける。`,d:`担保価値を割合で割った値である（20 ÷ 0.6）。上限は掛け算で求める。`},assumptions:`提示した60%はこの問題のための前提であり、実際のプロトコルの条件は個別に異なる。`,sources:[e.aaveLiquidations],reviewStatus:`verified`},{id:`Q-H04-4`,lessonId:`H-04`,type:`single`,difficulty:2,skill:`apply`,prompt:`DEXで大きな額の交換を行おうとした際、自分の注文の直前に同様の買い注文が割り込み、想定より不利な価格で約定した。このような、取引の順序を決める立場を利用して利益を得る行為の理解として正しいものはどれか。`,options:[{id:`a`,text:`オラクルが誤った価格を伝えたことが原因であり、順序とは無関係である`},{id:`b`,text:`MEVと呼ばれる行為で、利用者にとって実質的なコストになり得る`},{id:`c`,text:`資金調達率の支払いにあたる`},{id:`d`,text:`インパーマネントロスと呼ばれる現象である`}],correctIds:[`b`],explanation:`取引の順序を利用して利益を得る行為はMEVと呼ばれ、フロントランニングはその代表例である。約定価格が不利になる形で、利用者の実質的なコストになる。`,wrongExplanations:{a:`オラクルの異常は不当な清算や借入の問題であり、本問のような注文の割り込みとは別の仕組みである。`,c:`資金調達率は永久先物の価格調整のための授受であり、DEXの注文順序とは関係がない。`,d:`インパーマネントロスは、流動性提供者が価格変動によって負う「保有し続けた場合」との差であり、注文の割り込みとは別の現象である。`},sources:[e.ethereumDocs],reviewStatus:`verified`});var a=[{id:`Q-I01-1`,lessonId:`I-01`,type:`single`,difficulty:2,skill:`apply`,prompt:`暗号資産を送金しようとして、アドレス帳からコピーしたはずの送金先アドレスを貼り付けたところ、自分がコピーしたものと異なるアドレスが表示された。最も適切な対応はどれか。前提：クリップボードの内容をすり替えるマルウェアが知られている。`,options:[{id:`a`,text:`送金額と通貨の種類が合っていれば、送金先の表示が違っても表示上の不具合とみなしてそのまま送金してよい`},{id:`b`,text:`送金を中止し、アドレスをアドレス帳や公式に控えた記録と再照合したうえで、端末のマルウェア検査を行う`},{id:`c`,text:`アドレスの最初と最後の数文字が一致していれば、同じアドレスとみなして送金してよい`},{id:`d`,text:`少額ならテスト送金も照合も省き、表示されたアドレスへそのまま送金してよい`}],correctIds:[`b`],explanation:`貼り付けたアドレスがコピーしたものと異なるのは、クリップボードをすり替えるマルウェアに感染している典型的な兆候です。送金を取り消せない暗号資産では、実行前に中止して照合し直すことが唯一の安全な対応です。`,wrongExplanations:{a:`問題は金額ではなく送金先そのものです。攻撃者のアドレスに送れば金額の正しさは関係ありません。`,c:`すり替えアドレスは先頭や末尾が似せて作られることがあり、部分一致では検証になりません。全長を照合する必要があります。`,d:`少額でも同じアドレスに送る限り攻撃者に渡ります。まず感染の有無を確認することが先です。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-I01-2`,lessonId:`I-01`,type:`single`,difficulty:2,skill:`calculate`,prompt:`保有する暗号資産200万円のうち、ホットウォレットに30万円、コールドウォレットに170万円を置いている。ホットウォレット側が侵害され、その全額を失った場合、全体に対する直接損失の割合はどれか。`,options:[{id:`a`,text:`1.5%`},{id:`b`,text:`15%`},{id:`c`,text:`30%`},{id:`d`,text:`85%`}],correctIds:[`b`],explanation:`30万円 ÷ 200万円 ＝ 0.15、すなわち15%です。保管を分けることで、1回の事故で失う上限を設計できます。`,wrongExplanations:{a:`30÷200は0.015ではありません。桁の取り違えです。`,c:`30万円という金額そのものを割合と混同しています。`,d:`85%はコールド側の割合（170÷200）であり、失った側の割合ではありません。`},assumptions:`コールドウォレット側は侵害の影響を受けず、価格変動はないものとする。`,sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-I01-3`,lessonId:`I-01`,type:`single`,difficulty:2,skill:`understand`,prompt:`秘密鍵とアドレス（公開鍵から作られる情報）の扱いの違いとして正しいものはどれか。`,options:[{id:`a`,text:`アドレスは公開してもよいが、秘密鍵を知る者は誰でも資産を移転できるため、秘密鍵は本人だけが保持しなければならない`},{id:`b`,text:`秘密鍵もアドレスと同じく、送金を受け取るために相手へ公開する情報である`},{id:`c`,text:`秘密鍵を紛失しても、取引所のサポートが本人確認で再発行してくれる`},{id:`d`,text:`シードフレーズは秘密鍵とは無関係な、飾りの文字列である`}],correctIds:[`a`],explanation:`移転の正当性は「秘密鍵による署名が公開鍵で検証できること」で決まります。アドレスは公開情報ですが、秘密鍵は資産そのものであり、知る者は誰でも移転できます。`,wrongExplanations:{b:`秘密鍵は署名のための本人だけの情報です。公開すれば、資産は誰でも移転できる状態になります。`,c:`銀行型の本人確認や再発行の手続きは原則として存在せず、漏洩・紛失後の回復を前提にした設計はできません。`,d:`シードフレーズは秘密鍵の復元情報です。漏洩すれば秘密鍵が漏れたのと同じ結果になります。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-I01-4`,lessonId:`I-01`,type:`single`,difficulty:2,skill:`find-error`,prompt:`ウォレットの安全対策についての説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`送金先アドレスは、複数の経路で控えた記録と照合する`},{id:`b`,text:`復元情報は、紙や金属などオフラインの媒体で保管する`},{id:`c`,text:`日常用と保管用でウォレットを分け、1回の事故で失う上限を設計する`},{id:`d`,text:`エアドロップの受け取りに必要な承認（approve）操作は、範囲を確認しなくても安全である`}],correctIds:[`d`],explanation:`誤りはdです。エアドロップを装った承認操作は典型的な攻撃の入口であり、承認の範囲と取消方法を理解してから操作する必要があります。`,wrongExplanations:{a:`正しい説明です。アドレスの照合は、すり替え型マルウェアへの基本的な対策です。`,b:`正しい説明です。復元情報はオフラインで複数保管することが対策になります。`,c:`正しい説明です。保管を分けることで、1回の事故で失う上限を設計できます。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-I02-1`,lessonId:`I-02`,type:`single`,difficulty:3,skill:`compare`,prompt:`「運営者が流動性プールから資金を引き抜いて逃げ、トークン価格が暴落した」という事例の分類として最も適切なものはどれか。`,options:[{id:`a`,text:`オラクル攻撃`},{id:`b`,text:`ブリッジへの外部侵害`},{id:`c`,text:`ラグプル（運営者による出口詐欺）`},{id:`d`,text:`スマートコントラクトの通常の手数料徴収`}],correctIds:[`c`],explanation:`外部からの侵害ではなく、運営者自身が資金を引き抜く行為はラグプルです。原因の分類によって、利用者が事前に確認できる材料（権限の集中、監査、運営の透明性）が異なります。`,wrongExplanations:{a:`オラクル攻撃は価格情報の操作によるもので、運営者の持ち逃げとは原因が異なります。`,b:`ブリッジ侵害は外部の攻撃者によるもので、本事例は運営者自身の行為です。`,d:`手数料徴収は設計どおりの動作であり、資金を引き抜いて逃げる行為とは異なります。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-I02-2`,lessonId:`I-02`,type:`single`,difficulty:3,skill:`calculate`,prompt:`担保係数（最大LTV）60%のDeFiレンディングに、担保として15万円相当を預けている。通常時の借入上限はどれか。また、オラクル価格の操作で担保評価額が30万円と表示された場合の見かけの上限はどれか。`,options:[{id:`a`,text:`通常時9万円、操作時18万円`},{id:`b`,text:`通常時15万円、操作時30万円`},{id:`c`,text:`通常時6万円、操作時12万円`},{id:`d`,text:`通常時9万円、操作時9万円（変わらない）`}],correctIds:[`a`],explanation:`借入上限 ＝ 担保評価額 × 0.60。通常時は15万円×0.6＝9万円、評価額が30万円と表示されれば30万円×0.6＝18万円となり、実質担保を超える借入が可能になります。数式が正しくても前提価格が歪めば結果は歪みます。なお担保係数（最大LTV）は借入上限を決めるパラメータであり、清算が発動する清算閾値とは別のものです。`,wrongExplanations:{b:`担保係数を掛けていません。上限は評価額そのものではありません。`,c:`15万円×（1−0.6）＝6万円など、係数の使い方を取り違えています。掛けるのは係数そのものです。`,d:`上限は表示された評価額に連動するため、価格操作の影響を受けます。これがオラクル攻撃の要点です。`},assumptions:`金利や他の利用者の借入状況は考慮せず、担保係数は60%で一定とする。`,sources:[e.aaveLiquidations],reviewStatus:`verified`},{id:`Q-I02-3`,lessonId:`I-02`,type:`single`,difficulty:3,skill:`apply`,prompt:`異なるチェーン間で資産を移すブリッジを利用する前に確認する観点として、教材の内容に最も合うものはどれか。`,options:[{id:`a`,text:`ブリッジは価格変動を避ける仕組みなので、預けた資産の価格リスクが消える`},{id:`b`,text:`ブリッジの利用者が多いほど、侵害されたときの被害は小さくなる`},{id:`c`,text:`ブリッジは大量の資産を預かる構造のため侵害時の被害が大きくなりやすく、預ける額や代替経路を検討する材料になる`},{id:`d`,text:`ブリッジには分別管理の義務主体がいるため、登録取引所と同じ保護がある`}],correctIds:[`c`],explanation:`ブリッジは大量の資産を預かる構造上、侵害時の被害が大きくなりやすい部位です。原因の分類ごとに、利用者が取れる防御や確認できる材料は異なります。`,wrongExplanations:{a:`ブリッジはチェーン間の移転の仕組みであり、価格変動リスクを消すものではありません。`,b:`逆です。預かり資産が大きい構造ほど、侵害時の被害は大きくなりやすいと教材は述べています。`,d:`DeFiプロトコルには、分別管理の義務主体が存在しない場合があります。取引所の制度とは別に考える必要があります。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-I02-4`,lessonId:`I-02`,type:`multi`,difficulty:3,skill:`understand`,prompt:`DeFiプロトコルの運営者リスクを見極める観点として正しいものをすべて選べ（2つ）。`,options:[{id:`a`,text:`管理者キーやアップグレード権限が、特定の運営者に集中していないかを確認する`},{id:`b`,text:`監査を受けていれば、欠陥による資金流出は起きないことが保証される`},{id:`c`,text:`運営が匿名かどうかなど、ラグプル（運営者による持ち逃げ）の判断材料を確認する`},{id:`d`,text:`コードで自動実行される以上、運営者の行為による損失は原理的にありえない`}],correctIds:[`a`,`c`],explanation:`ラグプルの判断材料になるのは、監査の有無だけでなく、運営の匿名性や、管理者キーなど権限の集中の度合いです。「コードで動く」ことと「運営者リスクがない」ことは同義ではありません。`,wrongExplanations:{b:`監査は範囲内の確認であり、安全の保証ではありません。`,d:`管理者キーやアップグレード権限が残る設計も多く、運営者リスクは残ります。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-I03-1`,lessonId:`I-03`,type:`single`,difficulty:2,skill:`understand`,prompt:`日本で暗号資産交換業者を利用する際、利用者保護の観点で最初に確認すべきことはどれか。`,options:[{id:`a`,text:`取り扱い銘柄の数が多く、さまざまな暗号資産を取引できること`},{id:`b`,text:`金融庁の暗号資産交換業者の登録を受けていること`},{id:`c`,text:`SNSや比較サイトでの評判が良く、利用者の数が多いこと`},{id:`d`,text:`取引手数料やスプレッドが他の業者より最も安いこと`}],correctIds:[`b`],explanation:`資金決済法に基づく登録の有無が、分別管理をはじめとする利用者保護の枠組みが及ぶかどうかを決めます。金融庁の登録一覧で確認することが出発点です。`,wrongExplanations:{a:`銘柄数は利便性の問題であり、制度上の保護の有無とは無関係です。`,c:`評判は制度的な裏付けにはなりません。無登録業者の評判操作もありえます。`,d:`手数料の安さは保護制度とは無関係です。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-I03-2`,lessonId:`I-03`,type:`single`,difficulty:2,skill:`find-error`,prompt:`日本の暗号資産制度についての説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`登録業者には利用者資産の分別管理が求められる`},{id:`b`,text:`登録業者に預ければ、暗号資産の元本が公的に保証される`},{id:`c`,text:`海外の無登録業者には日本の利用者保護の枠組みがそのまま及ぶわけではない`},{id:`d`,text:`暗号資産は預金保険の対象ではない`}],correctIds:[`b`],explanation:`誤りはbです。登録制度は業者の行為規制と利用者資産の混同防止のためのもので、元本や価格を保証する制度ではありません。`,wrongExplanations:{a:`これは正しい説明です。分別管理は制度の柱の一つです。`,c:`これは正しい説明です。保護の適用は登録と法域に依存します。`,d:`これは正しい説明です。暗号資産は預金ではなく、預金保険の対象外です。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-I03-3`,lessonId:`I-03`,type:`single`,difficulty:2,skill:`apply`,prompt:`海外の大手暗号資産サービスが「利用者資産は分別管理している」と宣伝している。日本の利用者として、この宣伝の受け止め方として最も適切なものはどれか。`,options:[{id:`a`,text:`世界的な大手で利用者も多いため、日本の登録業者と同等の利用者保護が日本でも受けられるとみなせる`},{id:`b`,text:`分別管理と明記している以上、日本の金融庁による監督・検査の裏付けがあると考えてよい`},{id:`c`,text:`分別管理されていれば、業者が破綻した場合でも暗号資産の価格下落分まで補填される`},{id:`d`,text:`日本の登録がなければ分別管理は自己申告にすぎず、日本の制度による監督・検査や利用者保護は及ばない`}],correctIds:[`d`],explanation:`保護の有無は「どの主体に、どの法域で預けるか」で決まります。日本の登録制度の枠組みは登録業者に適用されるものであり、海外の無登録業者の自己申告とは裏付けが決定的に異なります。`,wrongExplanations:{a:`規模の大きさではなく、登録と法域によって保護の適用が決まります。`,b:`自己申告と、登録制度による監督・検査の裏付けは別物です。`,c:`分別管理は資産の混同を防ぐ仕組みであり、価格下落を補填しません。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-I03-4`,lessonId:`I-03`,type:`single`,difficulty:2,skill:`understand`,prompt:`日本の登録業者に求められる分別管理の内容として正しいものはどれか。`,options:[{id:`a`,text:`利用者の金銭も暗号資産も、業者の自己資産と混ぜて一括で管理される`},{id:`b`,text:`利用者の暗号資産は、すべてホットウォレットで管理することが求められる`},{id:`c`,text:`利用者の金銭は信託等で、利用者の暗号資産は自己の暗号資産と区別して管理し、大部分はコールドウォレット等で管理する枠組みとされている`},{id:`d`,text:`分別管理とは、利用者ごとに個別のブロックチェーンアドレスを割り当てることだけを指す`}],correctIds:[`c`],explanation:`分別管理では、利用者の金銭は信託等で、利用者の暗号資産は自己の暗号資産と区別して管理することが求められ、大部分をコールドウォレット等で管理する枠組みとされています。これにより、業者が破綻しても利用者資産が業者の一般財産と混同されにくくなります。`,wrongExplanations:{a:`自己資産と区別して管理すること自体が分別管理であり、混ぜて管理する説明は逆です。`,b:`逆です。利用者の暗号資産の大部分は、コールドウォレット等で管理する枠組みとされています。`,d:`分別管理は金銭の信託等を含む制度全体を指し、アドレスの割当てだけを意味しません。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-I04-1`,lessonId:`I-04`,type:`single`,difficulty:2,skill:`calculate`,prompt:`取得価額18万円の暗号資産を50万円で売却した。譲渡費用は0円とする。雑所得の計算の素になる売却益はどれか。前提：他の取引はなく、取得価額の計算方法は確定しているものとする。`,options:[{id:`a`,text:`18万円`},{id:`b`,text:`32万円`},{id:`c`,text:`50万円`},{id:`d`,text:`68万円`}],correctIds:[`b`],explanation:`売却益 ＝ 売却価額 − 取得価額 − 譲渡費用 ＝ 50万円 − 18万円 − 0円 ＝ 32万円です。最終的な税額は他の所得や控除によって変わります。`,wrongExplanations:{a:`18万円は取得価額であり、売却益ではありません。`,c:`50万円は売却価額の全額であり、取得価額を差し引く必要があります。`,d:`売却価額と取得価額を足してはいけません。差額が売却益です。`},assumptions:`譲渡費用0円、他の暗号資産取引なし。具体的な申告・税額は国税庁の公式情報で確認すること。`,sources:[e.ntaCrypto,e.ntaCryptoCalc],reviewStatus:`verified`},{id:`Q-I04-2`,lessonId:`I-04`,type:`single`,difficulty:2,skill:`understand`,prompt:`同一年に、株式で20万円の譲渡益、暗号資産で20万円の損失があった。日本の税制（2026年時点で施行中の原則）の扱いとして正しいものはどれか。`,options:[{id:`a`,text:`暗号資産の損失を株式の譲渡益と損益通算し、課税対象を0にできる`},{id:`b`,text:`暗号資産の損失は株式の譲渡益と損益通算できない`},{id:`c`,text:`暗号資産の損失は給与所得から全額控除できる`},{id:`d`,text:`暗号資産同士の交換では課税関係は一切生じない`}],correctIds:[`b`],explanation:`暗号資産の損益は原則として雑所得に区分され、その損失を上場株式等の譲渡益など他の所得区分の利益と損益通算することはできません。`,wrongExplanations:{a:`所得区分が異なるため損益通算はできません。これが暗号資産の税制の重要な制限です。`,c:`雑所得の損失を給与所得から控除する（他の所得との損益通算）こともできません。`,d:`暗号資産同士の交換でも、その時点の時価で損益を計算し課税関係が生じます。`},sources:[e.ntaCrypto],reviewStatus:`verified`},{id:`Q-I04-3`,lessonId:`I-04`,type:`single`,difficulty:2,skill:`apply`,prompt:`暗号資産の課税時点についての判断として正しいものはどれか。`,options:[{id:`a`,text:`暗号資産同士の交換でも、その時点の時価で、保有分を売却したのと同様に損益を計算する`},{id:`b`,text:`円で売却したときだけが課税時点であり、暗号資産同士の交換や決済の時点では課税関係は生じない`},{id:`c`,text:`マイニングやステーキングで得た報酬は、円に換えるまで所得にはならない`},{id:`d`,text:`含み益が増えた時点で、その分が所得として確定する`}],correctIds:[`a`],explanation:`課税時点は円への売却に限りません。暗号資産同士の交換や決済への使用でも、その時点の時価で損益を計算します。買って保有しているだけでは課税されません。`,wrongExplanations:{b:`交換でも、受け取った資産の時価で売却価額を置き換えて損益を計算し、課税関係が生じます。`,c:`報酬として取得した場合は、取得時の時価で所得を認識します。円への換金を待つ必要はありません。`,d:`含み益は未実現であり、売却・交換・決済使用などの時点で損益を計算します。`},sources:[e.ntaCrypto],reviewStatus:`verified`},{id:`Q-I04-4`,lessonId:`I-04`,type:`single`,difficulty:2,skill:`find-error`,prompt:`暗号資産の税務（2026年時点で施行中の制度）についての説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`取得価額は移動平均法等の計算方法で算定し、計算方法の前提が変われば所得額も変わりうる`},{id:`b`,text:`取引所の破綻で資産を失えば、その損失は自動的に税務上の救済として他の所得から控除される`},{id:`c`,text:`税率は総合課税の累進課税の仕組みの中で決まるため、他の所得の大きさによって実効的な負担は変わる`},{id:`d`,text:`暗号資産で商品を購入した場合も、その時点で保有分を時価で売却したのと同様に損益を計算する`}],correctIds:[`b`],explanation:`誤りはbです。取引所の破綻や詐欺で資産を失っても、それが直ちに税務上の救済になるわけではありません。個別の扱いは国税庁の公式情報や専門家で確認する必要があります。`,wrongExplanations:{a:`正しい説明です。取得価額の計算方法の選択と継続性が、前提として重要になります。`,c:`正しい説明です。暗号資産の利益は原則として雑所得として総合課税の対象になります。`,d:`正しい説明です。決済への使用も課税関係が生じる時点の一つです。`},sources:[e.ntaCrypto,e.ntaCryptoCalc],reviewStatus:`verified`},{id:`Q-J01-1`,lessonId:`J-01`,type:`single`,difficulty:2,skill:`calculate`,prompt:`5日間の終値が50、54、58、62、66のとき、5日単純移動平均（SMA）はいくつか。`,options:[{id:`a`,text:`54`},{id:`b`,text:`58`},{id:`c`,text:`62`},{id:`d`,text:`66`}],correctIds:[`b`],explanation:`合計は50＋54＋58＋62＋66＝290。SMA＝290÷5＝58です。`,wrongExplanations:{a:`54は2日目の終値であり、平均ではありません。`,c:`62は4日目の終値であり、平均ではありません。`,d:`66は最新の終値そのものであり、平均ではありません。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J01-2`,lessonId:`J-01`,type:`single`,difficulty:2,skill:`find-error`,prompt:`テクニカル指標についての説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`RSIは買われすぎ・売られすぎの目安として使われる`},{id:`b`,text:`移動平均は過去の価格の平均であり、将来価格の予測値ではない`},{id:`c`,text:`RSIが70を超えた銘柄は、その後に必ず下落する`},{id:`d`,text:`ボリンジャーバンドの幅は価格変動の大きさを反映する`}],correctIds:[`c`],explanation:`誤りはcです。RSIは過熱の目安であり、強いトレンドでは高水準に張り付くこともあります。指標は利益や値動きを保証しません。`,wrongExplanations:{a:`正しい説明です。ただし目安であり保証ではありません。`,b:`正しい説明です。平均は過去データの要約です。`,d:`正しい説明です。標準偏差を使うため、変動が大きいと帯は広がります。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J01-3`,lessonId:`J-01`,type:`single`,difficulty:2,skill:`understand`,prompt:`移動平均、MACD、RSIが同時に買いシグナルを示した。この「一致」の解釈として最も適切なものはどれか。`,options:[{id:`a`,text:`3つの独立した証拠がそろったため、上昇はほぼ確実である`},{id:`b`,text:`指標が3つ一致すれば、決算や事故などの新しい材料の影響は受けなくなる`},{id:`c`,text:`パラメータを調整して3つの指標が一致するようになるまで試すほど、シグナルの信頼性は上がる`},{id:`d`,text:`いずれも同じ過去の価格データを変換したものなので、独立した証拠が3つそろったとは限らない`}],correctIds:[`d`],explanation:`各指標は同じ価格・出来高を入力として変換したものであり、材料は過去の価格だけです。新しい材料は織り込まれておらず、複数指標の一致は独立した証拠の複数一致とは限りません。`,wrongExplanations:{a:`入力が共通であるため独立性は低く、確実性が証拠の個数分だけ上がるわけではありません。`,b:`指標は過去価格の要約であり、決算・事故・制度変更などの新しい材料の影響を消すものではありません。`,c:`パラメータを結果に合わせて探すのは過剰最適化であり、過去にだけ合う設定になる危険があります。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J01-4`,lessonId:`J-01`,type:`single`,difficulty:2,skill:`apply`,prompt:`価格が明確な上昇トレンドを描いている局面で、RSIが70を超えた。教材の考え方に最も合う判断はどれか。`,options:[{id:`a`,text:`RSIが70を超えたので、必ず下落に転じると判断して全て売却する`},{id:`b`,text:`RSIは過熱の目安にすぎず、強いトレンドでは高水準に張り付くこともあるため、単独では売買を決めない`},{id:`c`,text:`トレンド相場ではテクニカル指標は一切機能しないので、無視する`},{id:`d`,text:`RSIの期間設定を変えて、70未満になるパラメータを探す`}],correctIds:[`b`],explanation:`RSIは買われすぎ・売られすぎの目安であり、強いトレンドでは高止まりします。指標は根拠の一つとして位置づけ、単独で売買を決めないことが前提です。`,wrongExplanations:{a:`RSIの超過は下落の保証ではありません。目安と確定を混同しています。`,c:`教材は、相場環境によって指標の有効性が「変わる」と述べています。「一切機能しない」とまでは言えません。`,d:`都合の良いパラメータを後から探すのは過剰最適化の入口であり、判断の改善にはなりません。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J02-1`,lessonId:`J-02`,type:`single`,difficulty:3,skill:`calculate`,prompt:`3期間のリターンが3%、6%、9%のとき、サンプル標準偏差はいくつか。前提：サンプル分散は偏差の二乗和を（n−1）で割る。`,options:[{id:`a`,text:`9%`},{id:`b`,text:`3%`},{id:`c`,text:`約2.45%`},{id:`d`,text:`6%`}],correctIds:[`b`],explanation:`平均は6%。偏差は−3、0、3（%）、二乗和は18。サンプル分散＝18÷（3−1）＝9（%^2）、標準偏差＝√9＝3%です。`,wrongExplanations:{a:`9はサンプル分散（%^2）であり、平方根を取った標準偏差は3%です。`,c:`約2.45%は二乗和を（n−1）ではなくn＝3で割った母分散（18÷3＝6）の平方根であり、本問の前提（分母 n−1）とは異なります。`,d:`6%はリターンの平均であり、ばらつきの指標ではありません。`},assumptions:`リターンは%表示。サンプル分散の定義（分母 n−1）を用いる。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J02-2`,lessonId:`J-02`,type:`single`,difficulty:3,skill:`compare`,prompt:`相関係数とベータについての説明として正しいものはどれか。`,options:[{id:`a`,text:`相関係数が1に近いことは、一方が他方の原因であることを示す`},{id:`b`,text:`ベータは市場全体の動きに対するその資産の感応度を表す`},{id:`c`,text:`相関係数は−1から1の範囲を超えることがある`},{id:`d`,text:`ベータが高い資産は、固有の事業リスクも必ず高い`}],correctIds:[`b`],explanation:`ベータは市場リターンへの回帰の傾きで、市場連動の感応度です。固有リスクはベータには含まれません。`,wrongExplanations:{a:`相関は線形の連動を示すだけで、因果関係は示しません。`,c:`相関係数は定義上−1から1の範囲の値です。`,d:`ベータは市場要因への感応度であり、企業固有のリスクの大きさとは別の概念です。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J02-3`,lessonId:`J-02`,type:`single`,difficulty:2,skill:`calculate`,prompt:`価格が100から125へ上昇した。単純リターンと対数リターン（ln（期末価格÷期初価格）で計算し、ln1.25≒0.223とする）の組み合わせとして正しいものはどれか。`,options:[{id:`a`,text:`単純リターン25%、対数リターン約25.0%`},{id:`b`,text:`単純リターン20%、対数リターン約22.3%`},{id:`c`,text:`単純リターン25%、対数リターン約22.3%`},{id:`d`,text:`単純リターン125%、対数リターン約0.223%`}],correctIds:[`c`],explanation:`単純リターン ＝（125−100）÷100 ＝ 25%。対数リターン ＝ ln（125÷100）＝ ln1.25 ≒ 0.223、すなわち約22.3%です。対数リターンは期間をまたいで足し合わせられる性質があり、統計モデルでよく使われます。`,wrongExplanations:{a:`対数リターンは単純リターンと一致しません。ln1.25≒0.223であり、約22.3%が正しい値です。`,b:`単純リターンを期末価格で割った誤りです（25÷125＝20%）。分母は期初価格の100です。`,d:`単純リターンは価格そのもの（125）ではなく変化率であり、対数リターンの0.223は約22.3%を表します。割合と%表示を取り違えています。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J02-4`,lessonId:`J-02`,type:`single`,difficulty:3,skill:`understand`,prompt:`価格変動の分布にファットテール（裾が正規分布より厚い性質）があることの、リスク管理上の含意として正しいものはどれか。`,options:[{id:`a`,text:`標準偏差だけで「めったに起きない」と判断すると、極端な損失の頻度を過小評価する危険がある`},{id:`b`,text:`ファットテールであれば、平均と分散だけで分布を十分に表せる`},{id:`c`,text:`裾が厚い分布では、極端な値はいっそう起きにくくなる`},{id:`d`,text:`ファットテールとは、2資産の相関係数を1に近づける性質である`}],correctIds:[`a`],explanation:`ファットテールとは、極端な上下が正規分布の想定より頻繁に起きる性質です。平均と分散は分布の要約にすぎず、極端な損失の頻度は別途確認する必要があります。`,wrongExplanations:{b:`逆です。ファットテールがあるからこそ、平均と分散だけでは捉えきれないリスクが残ります。`,c:`裾が厚いとは、極端な値の起きやすさが想定より高いという意味です。`,d:`ファットテールは1つの分布の形の性質であり、2資産間の相関とは無関係です。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J03-1`,lessonId:`J-03`,type:`single`,difficulty:3,skill:`calculate`,prompt:`有意水準5%で、互いに独立な検定を40回行った。すべての帰無仮説が正しい（すべて偶然のデータである）場合、「統計的に有意」と誤って判定される件数の期待値はいくつか。`,options:[{id:`a`,text:`0件（有意水準を使う限り誤判定は起きない）`},{id:`b`,text:`2件`},{id:`c`,text:`5件`},{id:`d`,text:`40件`}],correctIds:[`b`],explanation:`期待値は40×0.05＝2件です。多数の戦略を試して「有意なもの」だけを報告すると、偶然の産物を発見と誤認します（多重検定・データスヌーピング）。`,wrongExplanations:{a:`有意水準5%は、帰無仮説が正しいときに5%の確率で誤って棄却することを意味します。`,c:`5%は割合であり、件数は試行回数に割合を掛けて求めます。`,d:`全件が有意になるわけではありません。期待値は2件です。`},assumptions:`検定は互いに独立で、各検定の有意水準は5%とする。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J03-2`,lessonId:`J-03`,type:`single`,difficulty:3,skill:`understand`,prompt:`効率的市場仮説（EMH）についての説明として最も適切なものはどれか。`,options:[{id:`a`,text:`価格は常に企業の真の価値と一致するという主張である`},{id:`b`,text:`価格が利用可能な情報を反映するほど、公開情報だけから継続的に超過利益を得ることは難しくなるという考え方である`},{id:`c`,text:`EMHが成り立てば、ファクター投資は過去データでも超過リターンを示さないはずであり、観測例はすべて誤りである`},{id:`d`,text:`EMHはテクニカル分析の有効性を保証する理論である`}],correctIds:[`b`],explanation:`EMHは情報の価格への反映に関する主張であり、価格が常に正しいことの保証ではありません。ファクターの超過リターンの解釈は、リスクの対価か非効率かという検証上の論点として残ります。`,wrongExplanations:{a:`EMHは「真の価値との一致」を主張するものではありません。情報の反映が論点です。`,c:`EMHの検証は資産価格モデルとの同時検証になり、単純に断定はできません。過去の観測をすべて誤りとする根拠にもなりません。`,d:`むしろ弱度EMHのもとでは、過去の価格情報からの超過利益は得にくいと考えられます。保証の理論ではありません。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J03-3`,lessonId:`J-03`,type:`single`,difficulty:3,skill:`calculate`,prompt:`あるファクターの平均超過リターンの推定値が0.09、標準誤差が0.03である。t値はいくつか。`,options:[{id:`a`,text:`約0.33`},{id:`b`,text:`3.0`},{id:`c`,text:`0.09`},{id:`d`,text:`0.03`}],correctIds:[`b`],explanation:`t値 ＝ 推定値 ÷ 標準誤差 ＝ 0.09÷0.03 ＝ 3.0です。ただし、t値が基準を超えても、検定を繰り返した回数が多ければ偽陽性の可能性は別途評価する必要があります。`,wrongExplanations:{a:`割り算の向きが逆です（0.03÷0.09≒0.33）。分子が推定値、分母が標準誤差です。`,c:`0.09は推定値そのものであり、標準誤差で割る前の値です。`,d:`0.03は標準誤差そのものであり、t値ではありません。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J03-4`,lessonId:`J-03`,type:`single`,difficulty:3,skill:`apply`,prompt:`過去データで超過リターンを示したファクターを見つけた。実用を検討する前に行うべき対応として、教材の考え方に最も合うものはどれか。`,options:[{id:`a`,text:`有意水準5%を1回満たしたので、ほかの期間では検証せずにそのまま実績として採用する`},{id:`b`,text:`同じデータで期間設定を変え、最も成績の良い設定を探す`},{id:`c`,text:`取引コストや税金を除いた成績のまま評価する`},{id:`d`,text:`別の期間・市場でも検証し、経済的に説明できる理由があるかを併せて確認する`}],correctIds:[`d`],explanation:`発見したファクターには、別の期間・市場での検証と、経済的な説明可能性の両方が必要です。さらに、期間や市場によって機能しない時期があり、取引コストや税金、実装方法で結果は変わります。`,wrongExplanations:{a:`試行回数が多いと、偶然に有意なものが必ず出てきます。1回の有意だけで発見は確実とは言えません。`,b:`同じデータで最も良い設定を探すのはデータスヌーピングであり、過去への当てはめを強めます。`,c:`コストや税金を除いた成績は実装後の結果とずれます。含めて評価する必要があります。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J04-1`,lessonId:`J-04`,type:`multi`,difficulty:3,skill:`apply`,prompt:`バックテストの信頼性を高める対応として正しいものをすべて選べ（2つ）。`,options:[{id:`a`,text:`パラメータ決定に使っていない期間でアウトオブサンプル検証を行う`},{id:`b`,text:`現在も上場している銘柄だけのデータで検証する`},{id:`c`,text:`手数料・スプレッドなどの取引コストを入れて再計算する`},{id:`d`,text:`試したパラメータのうち最も成績の良いものだけを報告する`}],correctIds:[`a`,`c`],explanation:`アウトオブサンプル検証は未知データでの再現性の確認、取引コストの導入は現実性の確保です。どちらもバックテスト検証の必須要素です。`,wrongExplanations:{b:`生き残り銘柄だけの検証はサバイバーシップバイアスを生み、成績を過大評価します。`,d:`最も良いものだけの報告はデータスヌーピングであり、試行総数の記録と併せて避けるべき対応です。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J04-2`,lessonId:`J-04`,type:`single`,difficulty:3,skill:`calculate`,prompt:`グロスで年率15%の戦略がある。往復の取引コストは1回転あたり0.3%、年間40回転する。教材の近似式（ネット ≈ グロス − コスト率 × 回転回数）によるネットリターンはおよそどれか。`,options:[{id:`a`,text:`約14.7%`},{id:`b`,text:`約12%`},{id:`c`,text:`約3%`},{id:`d`,text:`約27%`}],correctIds:[`c`],explanation:`コスト負担は0.3%×40＝12%。ネットは約15%−12%＝3%です。高回転戦略ではコスト前提が結論を左右します。`,wrongExplanations:{a:`コストを1回転分（0.3%）しか差し引いていません。回転回数を掛ける必要があります。`,b:`12%はコスト負担そのものであり、ネットリターンではありません。`,d:`コストを差し引くべきところを加算しています。15＋12＝27は誤りです。`},assumptions:`コストは単純加算の近似とし、複利との相互作用や約定の成否は捨象する（教材の近似式どおり）。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J04-3`,lessonId:`J-04`,type:`single`,difficulty:3,skill:`find-error`,prompt:`バックテストのバイアスについての説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`ルックアヘッドバイアスとは、上場廃止になった銘柄を除いたデータで検証することである`},{id:`b`,text:`サバイバーシップバイアスは、生き残った銘柄だけのデータで検証し、成績を過大評価する誤りである`},{id:`c`,text:`データスヌーピングは、多数のルールやパラメータを試して、最も良かったものだけを報告する誤りである`},{id:`d`,text:`修正後の財務数値など、判断時点で知り得ない情報を使うと、ルックアヘッドバイアスが生じる`}],correctIds:[`a`],explanation:`誤りはaです。上場廃止銘柄を除くのはサバイバーシップバイアスの説明です。ルックアヘッドバイアスは、判断時点で知り得ない情報（修正後の財務数値、期末に確定する指標など）を使ってしまう誤りを指します。`,wrongExplanations:{b:`正しい説明です。現在の指数構成銘柄だけで過去を検証するのは、その典型例です。`,c:`正しい説明です。試した戦略の総数を記録することも対策の一つです。`,d:`正しい説明です。これがルックアヘッドバイアスの定義そのものです。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-J04-4`,lessonId:`J-04`,type:`single`,difficulty:3,skill:`understand`,prompt:`ウォークフォワード検証の手順の説明として正しいものはどれか。`,options:[{id:`a`,text:`全期間を一度だけ推定に使い、同じ全期間で成績を確認する`},{id:`b`,text:`推定期間だけを固定し、検証は最初の一度だけ行う`},{id:`c`,text:`推定期間と検証期間を前に進めながら、推定と検証を繰り返し、未知データでの成績を積み上げる`},{id:`d`,text:`検証期間の成績が悪ければ、その都度パラメータを検証期間に合わせて直す`}],correctIds:[`c`],explanation:`ウォークフォワード検証は、推定期間と検証期間を前に進めながら繰り返し確認する方法です。パラメータ決定に使っていないデータでの成績を積み上げることで、再現性を確認します。`,wrongExplanations:{a:`同じデータでの推定と確認では、アウトオブサンプル検証になりません。`,b:`期間を前に進めて繰り返すことがウォークフォワードの特徴であり、一度だけの検証とは異なります。`,d:`検証期間に合わせて直すのは、知り得ない情報の使用と過剰最適化にあたります。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K01-1`,lessonId:`K-01`,type:`single`,difficulty:3,skill:`calculate`,prompt:`資産A（期待リターン12%）に60%、資産B（期待リターン4%）に40%投資するポートフォリオの期待リターンはいくつか。`,options:[{id:`a`,text:`4.0%`},{id:`b`,text:`8.0%`},{id:`c`,text:`8.8%`},{id:`d`,text:`16.0%`}],correctIds:[`c`],explanation:`期待リターンは加重平均で、0.6×12%＋0.4×4%＝7.2%＋1.6%＝8.8%です。相関は期待リターンには影響しません。`,wrongExplanations:{a:`4%は資産B単独の期待リターンです。`,b:`8%は重みを無視した単純平均（12＋4）÷2であり、本問の配分は60%・40%です。`,d:`16%は単純合計であり、重み（合計1）で加重平均する必要があります。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K01-2`,lessonId:`K-01`,type:`single`,difficulty:3,skill:`calculate`,prompt:`2資産に50%ずつ投資する。資産1の標準偏差は30%（分散0.09）、資産2の標準偏差は10%（分散0.01）、相関係数は0.2とする。ポートフォリオ分散はいくつか。前提：共分散 ＝ 相関 × σ1 × σ2。`,options:[{id:`a`,text:`0.006`},{id:`b`,text:`0.025`},{id:`c`,text:`0.028`},{id:`d`,text:`0.10`}],correctIds:[`c`],explanation:`共分散＝0.2×0.3×0.1＝0.006。分散＝0.25×0.09＋0.25×0.01＋2×0.25×0.006＝0.0225＋0.0025＋0.003＝0.028です。各資産の加重平均的な水準より小さく、分散効果が数値で確認できます。`,wrongExplanations:{a:`0.006は共分散そのものの値です。分散の式全体の計算結果ではありません。`,b:`0.025は共分散項（2×0.25×0.006＝0.003）を落とした計算です。相関が0でない限り共分散項が入ります。`,d:`0.10は2資産の分散を単純に足した値（0.09＋0.01）で、重みの二乗が入っていません。`},assumptions:`重みは各0.5、標準偏差は0.3と0.1、相関係数0.2で一定とする。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K01-3`,lessonId:`K-01`,type:`single`,difficulty:2,skill:`understand`,prompt:`2資産の相関係数が1（完全に同じ動き）の場合のポートフォリオについての説明として正しいものはどれか。`,options:[{id:`a`,text:`相関が1でも、銘柄を分けさえすれば分散効果で標準偏差は大きく下がる`},{id:`b`,text:`相関が1では分散効果は得られず、ポートフォリオの標準偏差は各資産の標準偏差の加重平均の水準になる`},{id:`c`,text:`相関が1なら、期待リターンも相関の分だけ下がる`},{id:`d`,text:`相関が1なら、ポートフォリオ分散は0になる`}],correctIds:[`b`],explanation:`分散が加重平均にならないのは共分散の項があるためで、相関が1のとき共分散の項は最大化し、標準偏差は加重平均の水準に一致します。分散効果は、相関が低い・負であるほど生まれます。`,wrongExplanations:{a:`銘柄を分けるだけでは不十分です。同じ動きをする資産同士では、ばらつきは打ち消し合いません。`,c:`期待リターンは重みによる加重平均であり、相関は影響しません。相関が効くのは分散の側です。`,d:`相関が1のとき分散は0にはなりません。2資産が完全に同じ動きをするため、分散は残ります。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K01-4`,lessonId:`K-01`,type:`single`,difficulty:3,skill:`calculate`,prompt:`資産1（標準偏差20%）に60%、資産2（標準偏差10%）に40%投資し、相関係数は0とする。ポートフォリオ分散と標準偏差の組み合わせとして正しいものはどれか。`,options:[{id:`a`,text:`分散0.05、標準偏差約22.4%`},{id:`b`,text:`分散0.016、標準偏差16%`},{id:`c`,text:`分散0.0256、標準偏差16.0%`},{id:`d`,text:`分散0.016、標準偏差約12.6%`}],correctIds:[`d`],explanation:`相関0では共分散の項は0です。分散 ＝ 0.6^2×0.2^2 ＋ 0.4^2×0.1^2 ＝ 0.0144＋0.0016 ＝ 0.016。標準偏差 ＝ √0.016 ≒ 0.126、すなわち約12.6%です。標準偏差の加重平均（16%）より下がっており、分散効果が確認できます。`,wrongExplanations:{a:`0.05は2資産の分散を重みなしに単純合計した値（0.04＋0.01）です。分散の式には重みの二乗が入ります。`,b:`分散0.016は正しいものの、標準偏差はその平方根で約12.6%です。16%は標準偏差を加重平均した値であり、混同しています。`,c:`0.0256は標準偏差の加重平均16%を二乗した値です。先に標準偏差を平均してから二乗する手順は誤りです。`},assumptions:`重みは0.6と0.4、相関係数0で一定とする。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K02-1`,lessonId:`K-02`,type:`single`,difficulty:3,skill:`calculate`,prompt:`ポートフォリオのリターン12%、無リスク金利4%、リターンの標準偏差10%のとき、シャープレシオはいくつか。`,options:[{id:`a`,text:`1.2`},{id:`b`,text:`0.8`},{id:`c`,text:`約0.83`},{id:`d`,text:`0.4`}],correctIds:[`b`],explanation:`シャープレシオ ＝（12%−4%）÷10% ＝ 8÷10 ＝ 0.8です。分子は無リスク金利を差し引いた超過リターンです。`,wrongExplanations:{a:`1.2は無リスク金利を差し引かず12÷10とした結果です。分子には超過リターンを使うのが定義です。`,c:`約0.83は割り算の向きが逆（10÷12）の結果です。分子が超過リターン、分母が標準偏差です。`,d:`0.4は無リスク金利4%を二重に差し引いた（12−4−4）÷10の結果です。差し引きは1回だけです。`},assumptions:`リターン、金利、標準偏差は同一期間（年率）でそろっているものとする。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K02-2`,lessonId:`K-02`,type:`single`,difficulty:3,skill:`understand`,prompt:`「95%VaRが10%」という表示の正しい解釈はどれか。`,options:[{id:`a`,text:`どのような市場環境でも、損失は最大で10%に限られることを示している`},{id:`b`,text:`損失が10%以内に収まる確率が95%であり、残り5%の側では10%を超える損失がありうる`},{id:`c`,text:`平均的に見込まれる損失（期待損失）が、常に10%であることを示している`},{id:`d`,text:`10%ちょうどの損失が、95回に1回の頻度で必ず発生することを示している`}],correctIds:[`b`],explanation:`VaRは信頼水準における損失の境界です。境界を超えた側の損失の大きさはVaR自体は教えてくれず、その情報にはCVaR（VaRを超えた損失の平均）などが必要です。`,wrongExplanations:{a:`VaRは最大損失ではありません。5%の側ではより大きな損失がありえます。`,c:`VaRは期待値（平均損失）ではなく、分位点の情報です。`,d:`確率の解釈が不正確です。95%は「損失が境界以内に収まる」側の確率です。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K02-3`,lessonId:`K-02`,type:`single`,difficulty:3,skill:`calculate`,prompt:`ある期間の損失率について、95%水準のVaRは9%（境界）であり、VaRを超える損失は16%と12%の2件だけだったとする。この2件の平均としてのCVaR（期待ショートフォール）はいくつか。`,options:[{id:`a`,text:`14%`},{id:`b`,text:`9%`},{id:`c`,text:`12%`},{id:`d`,text:`約12.3%`}],correctIds:[`a`],explanation:`CVaRは「VaRを超えた損失の平均」です。（16%＋12%）÷2 ＝ 14%。VaRが境界の情報しか持たないのに対し、CVaRは尾の大きさを反映します。`,wrongExplanations:{b:`9%はVaR（境界値）そのものです。CVaRは境界を超えた側の平均です。`,c:`12%は、VaRを超えた2件のうち小さい方だけを見た値です。平均には両方を使います。`,d:`約12.3%は、境界ちょうどの9%まで含めた3件の平均（（16＋12＋9）÷3）です。CVaRはVaRを「超えた」損失の平均です。`},assumptions:`離散的なシナリオの単純平均として計算する。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K02-4`,lessonId:`K-02`,type:`single`,difficulty:3,skill:`find-error`,prompt:`リスク指標についての説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`シャープレシオは、上昇方向の変動も含む標準偏差を分母に使う`},{id:`b`,text:`ソルティノレシオは、下方のばらつきだけを分母に使い、シャープレシオを補完する`},{id:`c`,text:`ストレステストは、分布の仮定に基づいてVaRを精密に計算する方法である`},{id:`d`,text:`最大ドローダウンは、ピークから谷までの最大の下落率である`}],correctIds:[`c`],explanation:`誤りはcです。ストレステストは、過去の危機や仮定した悪条件のシナリオを当てはめて損失を確認する方法であり、分布の仮定に依存しない点が強みです。VaRを計算する方法ではありません。`,wrongExplanations:{a:`正しい説明です。上昇の変動まで罰する点が、シャープレシオの欠点として指摘されます。`,b:`正しい説明です。下方偏差のみを使う点がシャープレシオとの違いです。`,d:`正しい説明です。回復には下落率以上の上昇が必要になる非対称性があります。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K03-1`,lessonId:`K-03`,type:`single`,difficulty:3,skill:`calculate`,prompt:`総額200万円、目標配分は株式50%・債券50%。現在は株式130万円・債券70万円になっている。目標比率に戻すリバランスの売買として正しいものはどれか。`,options:[{id:`a`,text:`株式を30万円売り、債券を30万円買う`},{id:`b`,text:`株式を30万円買い、債券を30万円売る`},{id:`c`,text:`株式を70万円売り、債券を70万円買う`},{id:`d`,text:`売買は不要（合計200万円で変わらないため）`}],correctIds:[`a`],explanation:`目標額は株式100万円・債券100万円。株式は130−100＝30万円の超過なので30万円売り、その分で債券を買うと100万円・100万円に戻ります。`,wrongExplanations:{b:`売買の方向が逆です。超過しているのは株式の側です。`,c:`70万円は現在の債券額であり、調整額（目標との差）ではありません。`,d:`合計額が同じでも比率がずれていればリスク水準が変わるため、リバランスの対象になります。`},assumptions:`取引コストと税金は考慮しない。価格は売買中に変動しないものとする。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K03-2`,lessonId:`K-03`,type:`multi`,difficulty:3,skill:`understand`,prompt:`モンテカルロ法による将来試算についての注意として正しいものをすべて選べ（2つ）。`,options:[{id:`a`,text:`結果は、入力した平均・分散・相関・分布の形という仮定に依存する`},{id:`b`,text:`試行回数を増やせば、仮定の誤りによる誤差も自動的になくなる`},{id:`c`,text:`乱数シードと試行回数を管理すれば、同一条件で結果を再現できる`},{id:`d`,text:`出力された資産分布は、将来の予測として確定したものとみなせる`}],correctIds:[`a`,`c`],explanation:`モンテカルロの出力は仮定の帰結であり、仮定依存性（a）が本質的な注意点です。再現性の管理（c）は検証可能性のために必要です。`,wrongExplanations:{b:`試行回数は乱数のばらつき（標本誤差）を減らしますが、入力仮定そのものの誤りは減らしません。`,d:`試算は予測の確定ではありません。前提を変えた感度確認と併せて解釈します。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K03-3`,lessonId:`K-03`,type:`single`,difficulty:3,skill:`apply`,prompt:`課税口座で運用する投資家が、リバランスの方法を検討している。教材の内容に最も合う考え方はどれか。`,options:[{id:`a`,text:`比率が少しでもずれたら毎日売買し、目標比率に完全一致させるのが最適である`},{id:`b`,text:`リバランスにはコストがかかるため、一度決めた配分は永久に見直さないのが正しい`},{id:`c`,text:`定期方式と乖離幅方式があるが、売買のたびの取引コストと、課税口座での売却益への課税も考慮して、頻度や幅を決める`},{id:`d`,text:`リバランスの目的はリターンの最大化であり、リスク水準の維持ではない`}],correctIds:[`c`],explanation:`リバランスには、定期に行う方法と、目標からの乖離が一定幅を超えたら行う方法があります。どちらの方法でも、取引コストと課税の発生を考慮に入れる必要があります。`,wrongExplanations:{a:`完全一致を追求する頻繁な売買は、取引コストと税負担を増やし、かえって不利になります。`,b:`見直しをしなければ、価格変動でずれた比率のままリスク水準が目標から離れ続けます。`,d:`リバランスの主な目的は「値上がりした資産を売り、下がった資産を買う」規律と、リスク水準の維持です。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K03-4`,lessonId:`K-03`,type:`single`,difficulty:3,skill:`calculate`,prompt:`総額400万円、目標配分は株式70%・債券30%。現在は株式320万円・債券80万円である。目標比率に戻すリバランスの売買として正しいものはどれか。`,options:[{id:`a`,text:`株式を40万円買い、債券を40万円売る`},{id:`b`,text:`株式を40万円売り、債券を40万円買う`},{id:`c`,text:`株式を120万円売り、債券を120万円買う`},{id:`d`,text:`売買は不要（株式と債券の合計が400万円で変わらないため）`}],correctIds:[`b`],explanation:`目標額は株式400万円×0.7＝280万円、債券400万円×0.3＝120万円。株式は320−280＝40万円の超過なので、40万円売って債券を40万円買うと目標比率に戻ります。売買額は「現在の金額−目標金額」で決まります。`,wrongExplanations:{a:`売買の方向が逆です。超過しているのは株式の側（320万円＞目標280万円）です。`,c:`120万円は目標の債券額そのものであり、調整額（目標との差40万円）ではありません。`,d:`合計額が同じでも比率がずれていればリスク水準が変わるため、リバランスの対象になります。`},assumptions:`取引コストと税金は考慮しない。価格は売買中に変動しないものとする。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K04-1`,lessonId:`K-04`,type:`single`,difficulty:3,skill:`calculate`,prompt:`残高200から毎期末に12を取り崩す。リターンが「−10%の後に＋10%」の順だった場合の最終残高はどれか。前提：各期とも（残高×（1＋リターン）−取り崩し額）の順で計算する。`,options:[{id:`a`,text:`168`},{id:`b`,text:`172.8`},{id:`c`,text:`180`},{id:`d`,text:`175.2`}],correctIds:[`b`],explanation:`1期目：200×0.9−12＝168。2期目：168×1.1−12＝184.8−12＝172.8です。逆の順序（＋10%の後に−10%）では175.2となり、累積リターンが同じ（0.9×1.1＝0.99）でも取り崩しがあると順序で結果が変わります。`,wrongExplanations:{a:`168は1期目終了時点の残高です。2期目の計算まで行ってください。`,c:`180は取り崩しを差し引く前の1期目残高（200×0.9）です。`,d:`175.2はリターンの順序が逆（＋10%の後に−10%）の場合の結果です。本問は下落が先の順序です。`},assumptions:`取り崩しは各期末に12で固定。手数料・税金は考慮しない。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K04-2`,lessonId:`K-04`,type:`single`,difficulty:3,skill:`compare`,prompt:`シミュレーションで示された「資産枯渇確率5%」の受け止め方として最も適切なものはどれか。`,options:[{id:`a`,text:`コンピュータで多数回試行した客観的な測定結果なので、前提を確認する必要はない`},{id:`b`,text:`入力したリターン分布等の仮定に依存するモデル上の数値であり、前提を変えた場合の感度と併せて判断する`},{id:`c`,text:`5%は十分に低い確率なので、実質的に資産の枯渇は起きないとみなしてよい`},{id:`d`,text:`試行回数を増やしていけば推定が精密になり、枯渇確率は0に近づいていく`}],correctIds:[`b`],explanation:`枯渇確率は分布仮定の産物であり、仮定が楽観的であれば過小に出ます。これがモデルリスクであり、前提と感度の確認が不可欠です。`,wrongExplanations:{a:`モデル上の数値は測定された事実とは性質が異なります。前提確認は必須です。`,c:`5%は20回に1回程度の頻度であり、無視できる水準とは限りません。解釈は利用者の状況に依存します。`,d:`試行回数は推定のばらつきを減らすだけで、真の（仮定のもとの）確率そのものを0にはしません。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K04-3`,lessonId:`K-04`,type:`single`,difficulty:3,skill:`calculate`,prompt:`残高150から毎期末に15を取り崩す。リターンが「＋30%の後に−20%」の順だった場合の最終残高はどれか。前提：各期とも（残高×（1＋リターン）−取り崩し額）の順で計算する。`,options:[{id:`a`,text:`121.5`},{id:`b`,text:`180`},{id:`c`,text:`144`},{id:`d`,text:`129`}],correctIds:[`d`],explanation:`1期目：150×1.3−15＝180。2期目：180×0.8−15＝144−15＝129です。逆の順序（−20%の後に＋30%）では121.5となり、累積リターンが同じ（1.3×0.8＝1.04）でも、取り崩しがあると順序で結果が変わります。`,wrongExplanations:{a:`121.5はリターンの順序が逆（−20%の後に＋30%）の場合の結果です。本問は上昇が先の順序です。`,b:`180は1期目終了時点の残高です。2期目の計算まで行ってください。`,c:`144は2期目のリターンを掛けた後、取り崩し15を引く前の残高です。`},assumptions:`取り崩しは各期末に15で固定。手数料・税金は考慮しない。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-K04-4`,lessonId:`K-04`,type:`single`,difficulty:3,skill:`understand`,prompt:`ヘッジについての説明として正しいものはどれか。`,options:[{id:`a`,text:`ヘッジは特定のリスクを相殺する取引だが、コストがかかり、ヘッジ手段と対象の値動きのずれ（ベーシスリスク）など別のリスクが残る`},{id:`b`,text:`ヘッジ比率を100%にすれば、ヘッジ手段と対象の値動きが完全に一致するため、対象のリスクは完全にゼロになる`},{id:`c`,text:`ヘッジは保険と異なり、プレミアムや取引費用などのコストなしでリスクだけを消せる仕組みである`},{id:`d`,text:`ヘッジを行えば、価格変動リスクだけでなく、モデル自体の前提の誤り（モデルリスク）も同時に消える`}],correctIds:[`a`],explanation:`ヘッジは為替や金利などの特定リスクを相殺する取引で、保険と同様にコストがかかります。完全にリスクを消すものではなく、ヘッジ比率とコスト、ベーシスリスクを合わせて評価します。`,wrongExplanations:{b:`ヘッジ手段自体の価格変動（ベーシスリスク）などが残るため、完全にゼロにはなりません。`,c:`ヘッジにもコストがかかります。コストなしにリスクだけを消す仕組みではありません。`,d:`モデルリスクは、モデルの誤りや前提の置き違いによるリスクであり、ヘッジ取引で消えるものではありません。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-L01-1`,lessonId:`L-01`,type:`single`,difficulty:2,skill:`calculate`,prompt:`自己資金50万円でレバレッジ4倍の建玉200万円を持っている。価格が8%下落した場合の損失額と、自己資金に対する損失割合はどれか。前提：強制決済や手数料は考慮しない線形計算とする。`,options:[{id:`a`,text:`損失4万円、自己資金の8%`},{id:`b`,text:`損失16万円、自己資金の32%`},{id:`c`,text:`損失8万円、自己資金の16%`},{id:`d`,text:`損失50万円、自己資金の100%`}],correctIds:[`b`],explanation:`損失は建玉ベースで200万円×8%＝16万円。自己資金50万円に対しては16÷50＝32%です。レバレッジ倍率の分だけ損失割合が拡大します。`,wrongExplanations:{a:`4万円はレバレッジ1倍（建玉50万円）の場合の損失です。建玉は200万円です。`,c:`建玉を100万円として計算した値です。自己資金50万円×レバレッジ4倍で建玉は200万円です。`,d:`8%の下落で全額を失うのは、およそレバレッジ12.5倍の場合に相当します。`},assumptions:`価格変動は建玉全体に一律に適用され、スリッページ・金利・手数料はないものとする（線形近似）。`,sources:[e.jpxMargin],reviewStatus:`verified`},{id:`Q-L01-2`,lessonId:`L-01`,type:`single`,difficulty:2,skill:`find-error`,prompt:`レバレッジ取引についての説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`維持率が基準を割ると追証が求められ、応じなければ強制決済されることがある`},{id:`b`,text:`相場の急変時には、損失が証拠金を超えることがありうる`},{id:`c`,text:`強制決済の仕組みがあるため、損失は常時証拠金の範囲内に厳密に限られる`},{id:`d`,text:`金利や貸株料などの保有コストがかかる場合がある`}],correctIds:[`c`],explanation:`誤りはcです。価格が不連続に動く局面では、強制決済の約定価格が証拠金の範囲を超えた損失になることがあり、追加の支払い義務が生じうます。`,wrongExplanations:{a:`正しい説明です。追証と強制決済は証拠金取引の基本構造です。`,b:`正しい説明です。急変時の価格の跳び（窓）が理由の一つです。`,d:`正しい説明です。保有コストは短期向けとされる理由の一つです。`},sources:[e.jpxMargin],reviewStatus:`verified`},{id:`Q-L01-3`,lessonId:`L-01`,type:`single`,difficulty:2,skill:`calculate`,prompt:`自己資金50万円でレバレッジ2倍の建玉100万円を空売りした。価格が20%上昇した場合の損失額と、自己資金に対する損失割合はどれか。前提：強制決済や手数料・金利は考慮しない線形計算とする。`,options:[{id:`a`,text:`損失10万円、自己資金の20%`},{id:`b`,text:`損失20万円、自己資金の40%`},{id:`c`,text:`損失20万円、自己資金の20%`},{id:`d`,text:`損失50万円、自己資金の100%`}],correctIds:[`b`],explanation:`空売りでは価格の上昇が損失になります。損失は建玉ベースで100万円×20%＝20万円。自己資金50万円に対しては20÷50＝40%です。損失は建玉で発生し、割合は自己資金を分母に取る点が要点です。`,wrongExplanations:{a:`10万円はレバレッジ1倍（建玉50万円）として計算した場合の損失です。建玉は自己資金×2倍の100万円です。`,c:`損失額は正しいものの、割合を建玉100万円で割っています（20÷100＝20%）。自己資金に対する割合が、レバレッジの効果を表します。`,d:`20%の価格上昇で自己資金の全額を失うのは、およそレバレッジ5倍の空売りに相当します。本問は2倍です。`},assumptions:`価格変動は建玉全体に一律に適用され、スリッページ・金利・貸株料・手数料はないものとする（線形近似）。`,sources:[e.jpxMargin],reviewStatus:`verified`},{id:`Q-L01-4`,lessonId:`L-01`,type:`single`,difficulty:2,skill:`understand`,prompt:`レバレッジ取引の「非線形リスク」の説明として正しいものはどれか。`,options:[{id:`a`,text:`損失は常に、価格変動率にレバレッジ倍率を掛けた割合で正確に決まる`},{id:`b`,text:`手数料が高い市場ほど、非線形リスクは小さくなる`},{id:`c`,text:`強制決済や清算による売りが価格をさらに押し下げ、損失が加速する構造があり、線形の近似を超えた損失が生じうる`},{id:`d`,text:`非線形リスクは、価格が上昇するときだけに生じる`}],correctIds:[`c`],explanation:`線形の式（損益率＝価格変動率×レバレッジ倍率）は、強制決済やスリッページがない場合の近似です。実際には、清算の売りが次の下落を呼び、損失が加速する構造があり、近似の外側にレバレッジ固有の危険があります。`,wrongExplanations:{a:`それは線形近似の範囲の話です。維持率割れによる強制決済や価格の不連続な変動で、損失は近似を超えることがあります。`,b:`手数料の水準と、清算が連鎖する構造の有無は無関係です。`,d:`下落局面での清算連鎖が典型例です。上昇時だけの現象ではありません。`},sources:[e.jpxMargin],reviewStatus:`verified`},{id:`Q-L02-1`,lessonId:`L-02`,type:`single`,difficulty:3,skill:`calculate`,prompt:`現物価格250、金利4%（年率）、期間0.5年、期間中の配当なしとする。教材の簡略式による先物理論価格はいくつか。`,options:[{id:`a`,text:`240`},{id:`b`,text:`250`},{id:`c`,text:`255`},{id:`d`,text:`260`}],correctIds:[`c`],explanation:`理論価格 ＝ 250×（1＋0.04×0.5）−0 ＝ 250×1.02 ＝ 255です。現物を保有するコスト（金利）分だけ先物が高くなる関係を、裁定が支えています。`,wrongExplanations:{a:`240は金利を差し引いた結果（250×0.96）で、符号が逆です。保有コストは先物価格を押し上げます。`,b:`250は金利（保有コスト）を無視した場合です。本問では金利4%が与えられています。`,d:`260は期間を1年として計算した結果（250×1.04）です。本問の期間は0.5年です。`},assumptions:`単利の簡略式を用い、保管費用・取引コスト・貸借料は考慮しない。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-L02-2`,lessonId:`L-02`,type:`single`,difficulty:3,skill:`understand`,prompt:`ベーシス（先物価格 − 現物価格）についての説明として正しいものはどれか。`,options:[{id:`a`,text:`ベーシスは常にゼロで固定される`},{id:`b`,text:`満期には受渡しを通じて現物と先物が一致するため、ベーシスは0に収束する`},{id:`c`,text:`ベーシスがプラスであることは、将来の現物価格の値上がりが確定したことを意味する`},{id:`d`,text:`ベーシスはフォワードには存在しない概念である`}],correctIds:[`b`],explanation:`満期時点で先物と現物が異なれば受渡しによる裁定が働くため、両者は一致しベーシスは0に収束します。満期前は保有コストや需給で変動します。`,wrongExplanations:{a:`満期前は金利や配当、需給でベーシスは変動します。ゼロなのは満期時点の収束です。`,c:`ベーシスは保有コスト等を反映した価格関係であり、将来価格の確定情報ではありません。`,d:`ベーシスの概念はフォワード価格と現物価格の差にも同様に適用されます。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-L02-3`,lessonId:`L-02`,type:`single`,difficulty:3,skill:`calculate`,prompt:`現物価格200、金利3%（年率）、期間1年、期間中の配当6とする。教材の簡略式による先物理論価格はいくつか。`,options:[{id:`a`,text:`200`},{id:`b`,text:`206`},{id:`c`,text:`194`},{id:`d`,text:`212`}],correctIds:[`a`],explanation:`理論価格 ＝ 200×（1＋0.03×1）−6 ＝ 206−6 ＝ 200です。保有コスト（金利）が価格を押し上げ、保有で得られる配当が引き下げるため、本問では両者がちょうど相殺されます。`,wrongExplanations:{b:`配当を差し引いていません。保有で得られる便益は、理論価格を引き下げる方向に働きます。`,c:`金利（保有コスト）を無視し、配当だけを差し引いた値です（200−6）。金利分は加える必要があります。`,d:`配当は差し引くべきところを加算しています（206＋6）。配当は保有者が受け取る便益です。`},assumptions:`単利の簡略式を用い、保管費用・取引コスト・貸借料は考慮しない。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-L02-4`,lessonId:`L-02`,type:`single`,difficulty:3,skill:`find-error`,prompt:`先物・フォワードについての説明のうち、誤っているものはどれか。`,options:[{id:`a`,text:`先物は取引所で標準化され、日々値洗いされる`},{id:`b`,text:`フォワードは相対取引のため、相手方の信用リスクがある`},{id:`c`,text:`コンタンゴは先物が現物より高い状態を指し、保有コストや需給を反映した価格関係である`},{id:`d`,text:`コンタンゴのときは将来の値上がりが確定しているため、現物を買えば必ず利益になる`}],correctIds:[`d`],explanation:`誤りはdです。コンタンゴは将来の値上がり・値下がりの予想そのものではなく、保有コストや需給を反映した価格関係です。値上がりの確定情報ではありません。`,wrongExplanations:{a:`正しい説明です。標準化と清算機関による日々の値洗いが、先物の特徴です。`,b:`正しい説明です。相対取引では清算機関の保証がなく、相手方の信用リスクが残ります。`,c:`正しい説明です。コンタンゴとバックワーデーションは、価格関係の呼び名です。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-L03-1`,lessonId:`L-03`,type:`single`,difficulty:3,skill:`calculate`,prompt:`行使価格80のコールオプションをプレミアム4で買った。満期時の原資産価格が110の場合と70の場合の、買い手の損益（1単位あたり）の組み合わせとして正しいものはどれか。`,options:[{id:`a`,text:`110の場合 ＋30、70の場合 −4`},{id:`b`,text:`110の場合 ＋26、70の場合 −4`},{id:`c`,text:`110の場合 ＋26、70の場合 −14`},{id:`d`,text:`110の場合 ＋34、70の場合 0`}],correctIds:[`b`],explanation:`満期時110：内在価値は110−80＝30、損益は30−4＝＋26。満期時70：内在価値は0、損益は0−4＝−4で、損失はプレミアムが上限です。`,wrongExplanations:{a:`110の場合にプレミアム4を差し引いていません。損益は内在価値−プレミアムです。`,c:`70の場合の損失はプレミアムの4が上限であり、−14にはなりません。買い手の損失限定が要点です。`,d:`110の場合はプレミアムを差し引くべきところを加えており、70の場合も支払ったプレミアム4の損失が生じます。`},assumptions:`満期時点の計算とし、取引コストは考慮しない。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-L03-2`,lessonId:`L-03`,type:`single`,difficulty:3,skill:`understand`,prompt:`ブラック・ショールズモデルについての説明として最も適切なものはどれか。`,options:[{id:`a`,text:`過去の価格データから将来の値動きを推定し、現実の市場で観測される価格を正確に予測するモデルである`},{id:`b`,text:`ボラティリティが一定、価格が対数正規分布に従う等の前提のもとでの理論価格であり、前提が現実とずれる分だけ限界を持つ`},{id:`c`,text:`前提となる仮定を持たない一般的な公式であるため、どの市場のどの商品にもそのまま適用できる`},{id:`d`,text:`オプションの時間価値は満期まで一定で、残存期間が短くなっても変化しないことを示すモデルである`}],correctIds:[`b`],explanation:`ブラック・ショールズは強い前提のもとで導かれた理論価格です。現実にはボラティリティは変動し価格は跳ぶため、市場価格との乖離自体が前提のずれの情報になります。`,wrongExplanations:{a:`理論価格は観測価格の予測の保証ではありません。前提のずれが乖離を生みます。`,c:`モデルには明確な前提があり、それが適用範囲を決めます。`,d:`時間価値は残存期間とともに減少し満期で0になります。モデルもその前提と矛盾しません。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-L03-3`,lessonId:`L-03`,type:`single`,difficulty:3,skill:`calculate`,prompt:`行使価格50のプットオプションをプレミアム3で買った。満期時の原資産価格が35の場合と55の場合の、買い手の損益（1単位あたり）の組み合わせとして正しいものはどれか。`,options:[{id:`a`,text:`35の場合 ＋15、55の場合 −3`},{id:`b`,text:`35の場合 ＋12、55の場合 0`},{id:`c`,text:`35の場合 ＋12、55の場合 −3`},{id:`d`,text:`35の場合 −12、55の場合 ＋3`}],correctIds:[`c`],explanation:`プットの内在価値は max（行使価格−原資産価格, 0）です。満期時35：内在価値は50−35＝15、損益は15−3＝＋12。満期時55：内在価値は0、損益は0−3＝−3で、損失はプレミアムが上限です。`,wrongExplanations:{a:`35の場合にプレミアム3を差し引いていません。損益は内在価値−プレミアムです。`,b:`55の場合も、支払ったプレミアム3の損失が生じます。内在価値が0でも損益は0にはなりません。`,d:`符号が逆です。プットの買い手は原資産の下落で利益、上昇ではプレミアム分の損失になります。`},assumptions:`満期時点の計算とし、取引コストは考慮しない。`,sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-L03-4`,lessonId:`L-03`,type:`single`,difficulty:3,skill:`understand`,prompt:`オプションのデルタとガンマについての説明として正しいものはどれか。`,options:[{id:`a`,text:`デルタは、ボラティリティの変化に対するオプション価格の感応度である`},{id:`b`,text:`ガンマはデルタ自体の変化の速さで、満期が近く行使価格付近では大きくなり、ヘッジの再調整が頻繁になる`},{id:`c`,text:`デルタが分かれば、満期までの損益は完全に予測できる`},{id:`d`,text:`ガンマは、満期から遠いほど常に大きくなる`}],correctIds:[`b`],explanation:`デルタは原資産価格の変化に対するオプション価格の変化の近似、ガンマはデルタ自体の変化の速さです。満期が近く行使価格付近ではガンマが大きくなり、デルタが急速に変わるため、ヘッジの再調整が頻繁になります。`,wrongExplanations:{a:`デルタは原資産価格の変化に対する感応度です。ボラティリティに対する感応度は、デルタとは別の指標です。`,c:`デルタは近似であり、価格が動けばデルタ自体も変化します（それがガンマです）。損益の完全な予測にはなりません。`,d:`逆です。ガンマは満期が近く、行使価格付近で大きくなります。`},sources:[e.fsaTop],reviewStatus:`verified`},{id:`Q-L04-1`,lessonId:`L-04`,type:`single`,difficulty:2,skill:`calculate`,prompt:`永久先物で建玉100万円のロングを持っている。資金調達率が1インターバルあたり+0.01%のとき、ロングが支払う資金調達の金額はいくらか。前提：プラスの率ではロングがショートへ支払う。`,options:[{id:`a`,text:`10円`},{id:`b`,text:`100円`},{id:`c`,text:`1,000円`},{id:`d`,text:`10,000円`}],correctIds:[`b`],explanation:`支払額 ＝ 建玉金額 × 資金調達率 ＝ 1,000,000円 × 0.0001 ＝ 100円です。0.01%は小数では0.0001である点が計算の要点です。`,wrongExplanations:{a:`10円は率の換算を1桁誤った結果です。0.01%＝0.0001です。`,c:`1,000円は率を0.1%（0.001）と取り違えた結果です。`,d:`10,000円は率を1%と取り違えた結果です。`},assumptions:`建玉金額は当該インターバルを通じて100万円で一定とし、率は取引所公表の+0.01%とする。`,sources:[e.dydxFunding],reviewStatus:`verified`},{id:`Q-L04-2`,lessonId:`L-04`,type:`single`,difficulty:3,skill:`understand`,prompt:`永久先物市場で清算連鎖（カスケード）が起きる仕組みの説明として正しいものはどれか。`,options:[{id:`a`,text:`強制清算は取引所の内部で処理されて市場の価格に影響しないため、清算が次の清算を呼ぶ連鎖は起きない`},{id:`b`,text:`価格変動で強制清算が発生し、その決済注文が価格をさらに動かして次の清算水準に達することで連鎖する`},{id:`c`,text:`資金調達率の支払いが証拠金を直接減らすことが原因で、清算は常に連鎖する`},{id:`d`,text:`建玉（未決済のポジション）が少ない市場ほど、清算の連鎖は起きやすい`}],correctIds:[`b`],explanation:`レバレッジ建玉が密集している市場では、清算注文自体が価格を動かすため、清算が次の清算を誘発します。建玉の総量と偏りが連鎖の起こりやすさを左右します。`,wrongExplanations:{a:`清算は成行的な決済として実行され、価格を動かしうます。これが連鎖の起点です。`,c:`資金調達率は価格を現物へ寄せる仕組みであり、連鎖の直接原因ではありません。`,d:`逆です。建玉が大きくレバレッジが偏っているほど連鎖は起きやすくなります。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-L04-3`,lessonId:`L-04`,type:`single`,difficulty:2,skill:`calculate`,prompt:`永久先物で建玉300万円のロングを持っている。資金調達率が1インターバルあたり−0.03%のとき、ロングの資金調達の受払いはいくらか。前提：マイナスの率ではショートがロングへ支払う。`,options:[{id:`a`,text:`90円を受け取る`},{id:`b`,text:`900円を支払う`},{id:`c`,text:`9,000円を受け取る`},{id:`d`,text:`900円を受け取る`}],correctIds:[`d`],explanation:`金額 ＝ 建玉金額 × 資金調達率の絶対値 ＝ 3,000,000円 × 0.0003 ＝ 900円。率がマイナスのときはショートがロングへ支払うため、ロングは900円を受け取ります。符号で支払方向が決まる点が、プラスの率の場合との違いです。`,wrongExplanations:{a:`90円は率の換算を1桁誤った結果です。0.03%は小数では0.0003です。`,b:`金額900円は合っていますが、方向が逆です。支払うのはプラスの率のときで、マイナスの率ではロングは受け取る側です。`,c:`9,000円は率を0.3%（0.003）と取り違えた結果です。`},assumptions:`建玉金額は当該インターバルを通じて300万円で一定とし、率は取引所公表の−0.03%とする。`,sources:[e.dydxFunding],reviewStatus:`verified`},{id:`Q-L04-4`,lessonId:`L-04`,type:`single`,difficulty:3,skill:`apply`,prompt:`永久先物市場で、建玉（オープンインタレスト）が急増し、資金調達率が大きなプラスで推移している。教材の考え方に最も合う読み取り方はどれか。`,options:[{id:`a`,text:`ロング側への建玉の偏りと市場の過熱の手掛かりにはなるが、それだけで反転の時期を当てることはできない`},{id:`b`,text:`資金調達率がプラスなら価格は必ず下落に転じるので、直ちに空売りすべき局面である`},{id:`c`,text:`建玉の増加は、清算連鎖が起きにくくなったことを示す`},{id:`d`,text:`資金調達率の支払いは取引所の収入になるため、市場の過熱とは無関係である`}],correctIds:[`a`],explanation:`資金調達率の水準や建玉の偏りは、市場の過熱の手掛かりにはなります。しかし、反転の時期を当てる道具ではありません。また、建玉とレバレッジの偏りが大きい市場ほど、清算連鎖は起きやすくなります。`,wrongExplanations:{b:`プラスの率はロングがショートへ支払う状態を示すだけで、下落への転換を保証しません。手掛かりと時期の予測は別です。`,c:`逆です。建玉の総量とレバレッジの偏りが大きいほど、小さな価格変動でも多数の強制清算が連鎖しやすくなります。`,d:`資金調達率は、取引所への手数料ではなく、建玉を持つロングとショートの間の交換です。`},sources:[e.dydxFunding],reviewStatus:`verified`}],o=[{id:`Q-M01-1`,lessonId:`M-01`,type:`single`,difficulty:1,skill:`understand`,prompt:`現行NISA（2024年施行）について正しいものはどれか。`,options:[{id:`a`,text:`年間の投資枠は合計360万円で、つみたて投資枠120万円と成長投資枠240万円を併用できる`},{id:`b`,text:`生涯非課税保有限度額は3,000万円で、成長投資枠にも上限はない`},{id:`c`,text:`NISA口座で損失が出た場合、課税口座の利益と損益通算できる`},{id:`d`,text:`保有商品を売却すると、売却した年のうちにその分の非課税枠が再利用できる`}],correctIds:[`a`],explanation:`現行NISAの年間投資枠はつみたて120万円＋成長240万円＝合計360万円です。生涯非課税保有限度額は1,800万円（うち成長投資枠は1,200万円まで）です。`,wrongExplanations:{b:`生涯非課税保有限度額は1,800万円で、成長投資枠はそのうち1,200万円までです。`,c:`NISA口座内の損失は損益通算も繰越控除もできません。`,d:`売却で空いた枠（簿価分）が再利用できるのは翌年以降です。`},sources:[e.fsaNisa],reviewStatus:`verified`},{id:`Q-M01-2`,lessonId:`M-01`,type:`single`,difficulty:1,skill:`calculate`,prompt:`つみたて投資枠のみを毎年上限まで使って投資する場合、生涯非課税保有限度額1,800万円に到達するまでの年数は何年か。`,options:[{id:`a`,text:`10年`},{id:`b`,text:`15年`},{id:`c`,text:`18年`},{id:`d`,text:`20年`}],correctIds:[`b`],explanation:`つみたて投資枠の年間上限は120万円です。1,800万円÷120万円＝15年です。`,wrongExplanations:{a:`120万円×10年＝1,200万円で、生涯限度額には届きません（1,200万円は成長投資枠の上限額です）。`,c:`120万円×18年＝2,160万円となり、限度額を超えます。`,d:`120万円×20年＝2,400万円となり、限度額を超えます。`},sources:[e.fsaNisa],reviewStatus:`verified`},{id:`Q-M01-3`,lessonId:`M-01`,type:`single`,difficulty:2,skill:`apply`,prompt:`NISA口座で、簿価（取得価額）200万円で購入した株式を260万円で売却した。売却により翌年以降に再利用できる非課税枠はいくらか。`,options:[{id:`a`,text:`200万円`},{id:`b`,text:`260万円`},{id:`c`,text:`60万円`},{id:`d`,text:`0円（再利用はできない）`}],correctIds:[`a`],explanation:`非課税枠は買付金額（簿価）で管理されます。売却すると、その簿価分（200万円）の枠が翌年以降に再利用できます。売却額そのものや、利益の額が再利用されるわけではありません。`,wrongExplanations:{b:`売却額260万円ではなく、簿価（取得価額）200万円分が再利用の対象です。`,c:`利益60万円は再利用額とは関係ありません。枠は簿価ベースで管理されます。`,d:`売却した分の枠は消滅するのではなく、簿価分が翌年以降に再利用できます。`},sources:[e.fsaNisa],reviewStatus:`verified`},{id:`Q-M01-4`,lessonId:`M-01`,type:`single`,difficulty:2,skill:`find-error`,prompt:`現行NISAについて誤っているものはどれか。`,options:[{id:`a`,text:`つみたて投資枠の対象は、積立・分散・長期投資に適した一定の投資信託である`},{id:`b`,text:`成長投資枠では、整理・監理銘柄やレバレッジ型など一部の商品は対象外とされている`},{id:`c`,text:`生涯非課税保有限度額1,800万円は、その全額を成長投資枠で使うことができる`},{id:`d`,text:`保有商品を売却すると、その簿価分の非課税枠が翌年以降に再利用できる`}],correctIds:[`c`],explanation:`成長投資枠で使えるのは、生涯非課税保有限度額1,800万円のうち1,200万円までです。全額を成長投資枠で使うことはできません。`,wrongExplanations:{a:`正しい記述です。つみたて投資枠の対象は、一定の投資信託に限られます。`,b:`正しい記述です。成長投資枠でも、一部の商品は対象外とされています。`,d:`正しい記述です。再利用できるのは簿価分で、時期は翌年以降です。`},sources:[e.fsaNisa],reviewStatus:`verified`},{id:`Q-M02-1`,lessonId:`M-02`,type:`single`,difficulty:2,skill:`understand`,prompt:`iDeCoの税制優遇について正しいものはどれか。`,options:[{id:`a`,text:`掛金は所得控除の対象、運用益は非課税、受取時は退職所得または公的年金等として課税される`},{id:`b`,text:`掛金・運用益・受取金のすべてが完全に非課税である`},{id:`c`,text:`掛金の限度額は加入区分にかかわらず全員同額である`},{id:`d`,text:`60歳前でも、必要なときはいつでも引き出すことができる`}],correctIds:[`a`],explanation:`iDeCoは拠出時（所得控除）・運用時（非課税）・受取時（退職所得／公的年金等として課税）の3段階の構造です。出口で課税される点が重要です。`,wrongExplanations:{b:`受取時は退職所得または公的年金等の雑所得として課税されます。完全非課税ではありません。`,c:`掛金限度額は国民年金・厚生年金等の加入区分や企業年金の有無により異なります。`,d:`iDeCoの資産は原則として60歳まで引き出すことができません。`},sources:[e.idecoOfficial,e.mhlwIdeco],reviewStatus:`verified`},{id:`Q-M02-2`,lessonId:`M-02`,type:`single`,difficulty:2,skill:`apply`,prompt:`iDeCoの利用を検討する際の判断として最も適切なものはどれか。`,options:[{id:`a`,text:`生活防衛資金も含めて手元資金の全額をiDeCoに入れると、所得控除が最大になり最も有利になる`},{id:`b`,text:`原則60歳まで引き出せないため、近い将来に必要な資金は対象外とし、自分の加入区分の限度額を確認してから拠出額を決める`},{id:`c`,text:`受取時には課税されないため、一時金と年金のどちらで受け取るかは検討しなくてよい`},{id:`d`,text:`節税額は所得にかかわらず掛金の額だけで一律に決まるため、個別の試算は不要である`}],correctIds:[`b`],explanation:`流動性の制約（原則60歳まで引出不可）と、加入区分により異なる限度額の確認が前提です。生活防衛資金は引き出せる形で確保します。`,wrongExplanations:{a:`生活防衛資金は緊急時に使える流動性が必要です。原則60歳まで引き出せないiDeCoに入れるべきではありません。`,c:`受取時は退職所得または公的年金等として課税され、受取方法で税負担が変わるため検討が必要です。`,d:`所得控除の節税効果は限界税率によって異なり、課税所得がない場合は効果が生じません。`},sources:[e.idecoOfficial,e.mhlwIdeco],reviewStatus:`verified`},{id:`Q-M02-3`,lessonId:`M-02`,type:`single`,difficulty:2,skill:`calculate`,prompt:`iDeCoに年間36万円（月3万円）を拠出した。限界税率を所得税20%・住民税10%の合計30%と仮定すると、拠出時の節税額の概算はいくらか。`,options:[{id:`a`,text:`3.6万円`},{id:`b`,text:`10.8万円`},{id:`c`,text:`7.2万円`},{id:`d`,text:`36.0万円`}],correctIds:[`b`],explanation:`節税額の概算＝年間掛金額×限界税率です。36万円×30%＝10.8万円です。あくまで仮定に基づく概算であり、受取時の課税を含めた最終的な有利さは別に評価する必要があります。`,wrongExplanations:{a:`住民税10%だけで計算した値です。所得税と住民税を合わせた限界税率30%で計算します。`,c:`所得税20%だけで計算した値です。合計30%で計算すると10.8万円になります。`,d:`掛金の全額が戻ってくるわけではありません。節税額は掛金に限界税率を掛けた概算です。`},assumptions:`拠出限度額が月3万円以上ある加入区分（第1号被保険者など）を想定する。`,sources:[e.idecoOfficial,e.mhlwIdeco],reviewStatus:`verified`},{id:`Q-M02-4`,lessonId:`M-02`,type:`single`,difficulty:2,skill:`find-error`,prompt:`iDeCoの受取時の取扱いについて誤っているものはどれか。`,options:[{id:`a`,text:`一時金で受け取る場合は、退職所得として課税される`},{id:`b`,text:`年金で受け取る場合は、公的年金等の雑所得として課税される`},{id:`c`,text:`受取時の税負担は受取方法によって変わりうるため、生涯の税負担で評価する必要がある`},{id:`d`,text:`運用益が非課税であるため、受け取り方にかかわらず税金は一切かからない`}],correctIds:[`d`],explanation:`iDeCoは拠出時と運用時が優遇され、受取時に課税される構造です。一時金は退職所得、年金は公的年金等の雑所得として課税されるため、「税金は一切かからない」は誤りです。`,wrongExplanations:{a:`正しい記述です。一時金は退職所得として課税されます。`,b:`正しい記述です。年金は公的年金等の雑所得として課税されます。`,c:`正しい記述です。入口の節税だけでなく出口の課税を含めて評価します。`},sources:[e.idecoOfficial,e.mhlwIdeco],reviewStatus:`verified`},{id:`Q-M03-1`,lessonId:`M-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`課税口座で上場株式を売却し、譲渡益が100万円だった。申告分離課税（税率20.315%）による税額はいくらか。`,options:[{id:`a`,text:`150,000円`},{id:`b`,text:`200,000円`},{id:`c`,text:`203,150円`},{id:`d`,text:`315,000円`}],correctIds:[`c`],explanation:`1,000,000円×20.315%＝203,150円です。税率は所得税15%＋復興特別所得税0.315%＋住民税5%の合計です。`,wrongExplanations:{a:`所得税15%だけの計算で、復興特別所得税と住民税が含まれていません。`,b:`税率を20%ちょうどとした概算で、実際の税率20.315%とは異なります。`,d:`20.315%の「0.315」を31.5%と読み違えた計算です（100万円×31.5%＝315,000円）。0.315%は復興特別所得税の分で、税率の合計は20.315%です。`},sources:[e.ntaStockTax],reviewStatus:`verified`},{id:`Q-M03-2`,lessonId:`M-03`,type:`single`,difficulty:2,skill:`understand`,prompt:`上場株式等の譲渡損失の繰越控除について正しいものはどれか。`,options:[{id:`a`,text:`特定口座（源泉徴収あり）を使えば、確定申告をしなくても損失は自動で翌年以降に繰り越される`},{id:`b`,text:`確定申告により翌年以降3年間繰り越すことができ、継続して確定申告する必要がある`},{id:`c`,text:`NISA口座の損失も繰越控除の対象になる`},{id:`d`,text:`繰越期間に上限はなく、何年先の利益とも相殺できる`}],correctIds:[`b`],explanation:`繰越控除は確定申告が要件で、繰越期間は翌年以降3年間、利用には継続した確定申告が必要です。`,wrongExplanations:{a:`特定口座（源泉徴収あり）でも、繰越控除を使うには確定申告が必要です。`,c:`NISA口座内の損失は損益通算・繰越控除の対象になりません。`,d:`繰越期間は翌年以降3年間が上限です。`},sources:[e.ntaStockTax],reviewStatus:`verified`},{id:`Q-M03-3`,lessonId:`M-03`,type:`single`,difficulty:2,skill:`calculate`,prompt:`同じ年に、A口座で上場株式の譲渡益80万円、B口座で譲渡損失50万円があった。確定申告で損益通算した場合の税額はいくらか（税率20.315%）。`,options:[{id:`a`,text:`101,575円`},{id:`b`,text:`162,520円`},{id:`c`,text:`60,945円`},{id:`d`,text:`264,095円`}],correctIds:[`c`],explanation:`損益通算後の課税対象は80万円−50万円＝30万円です。税額は30万円×20.315%＝60,945円です。口座をまたぐ損益通算には確定申告が必要です。`,wrongExplanations:{a:`損失50万円に税率を掛けた値です。損失そのものに課税されるわけではありません。`,b:`損益通算をしない場合の税額です（80万円×20.315%）。通算すると課税対象は30万円になります。`,d:`利益と損失を合計した130万円に税率を掛けた値です。損失は利益から差し引いて通算します。`},sources:[e.ntaStockTax],reviewStatus:`verified`},{id:`Q-M03-4`,lessonId:`M-03`,type:`single`,difficulty:2,skill:`apply`,prompt:`取得価額100万円の投資信託で、普通分配金2万円と元本払戻金（特別分配金）3万円が支払われた。課税対象の金額と、支払い後の取得価額の組み合わせとして正しいものはどれか。`,options:[{id:`a`,text:`課税対象5万円、取得価額100万円`},{id:`b`,text:`課税対象2万円、取得価額97万円`},{id:`c`,text:`課税対象3万円、取得価額97万円`},{id:`d`,text:`課税対象0円、取得価額95万円`}],correctIds:[`b`],explanation:`元本払戻金（特別分配金）は課税対象ではなく、取得価額を引き下げる取扱いです。課税対象は普通分配金2万円で、取得価額は100万円−3万円＝97万円になります。`,wrongExplanations:{a:`分配金全額を課税対象とし、取得価額の調整もしていません。元本払戻金は非課税で、受け取ると取得価額が下がります。`,c:`元本払戻金3万円を課税対象と取り違えています。課税対象は普通分配金2万円です。`,d:`普通分配金は課税対象です。また取得価額の下げ幅は、元本払戻金の3万円分だけです。`},sources:[e.ntaStockTax,e.imajDividend],reviewStatus:`verified`},{id:`Q-M04-1`,lessonId:`M-04`,type:`single`,difficulty:2,skill:`calculate`,prompt:`元本100万円を年率5%で20年運用した（税引前で約265.33万円）。売却時に利益全体へ20.315%が一括課税される単純化モデルでは、税引後の金額はおよそいくらか。`,options:[{id:`a`,text:`約211.4万円`},{id:`b`,text:`約231.7万円`},{id:`c`,text:`約245.0万円`},{id:`d`,text:`約265.3万円`}],correctIds:[`b`],explanation:`利益は約165.33万円、税額は165.33万円×20.315%＝約33.59万円。265.33万円−33.59万円＝約231.74万円です。課税は利益部分にのみかかり、元本にはかかりません。`,wrongExplanations:{a:`資産全体（元本＋利益）に課税した場合の計算です。課税対象は利益部分のみです。`,c:`税額を元本100万円×20.315%＝約20.3万円として差し引いた計算です（265.33万円−20.3万円≒245.0万円）。課税対象は元本ではなく利益部分です。`,d:`これは税引前の金額です。非課税口座の場合に相当します。`},assumptions:`運用期間中の配当課税・売買を無視し、売却時に利益へ一括課税する単純化モデル`,sources:[e.ntaStockTax,e.fsaNisa],reviewStatus:`verified`},{id:`Q-M04-2`,lessonId:`M-04`,type:`single`,difficulty:2,skill:`find-error`,prompt:`制度情報の扱いとして誤っているものはどれか。`,options:[{id:`a`,text:`施行中の制度と、成立済みだが未施行の制度を区別し、適用開始日とともに記録する`},{id:`b`,text:`報道された税制改正の議論を、現行制度としてシミュレーションに組み込む`},{id:`c`,text:`歴史的な制度を使う計算では、対象時点の制度を適用する`},{id:`d`,text:`確認できていない制度情報は、未確認であることを明示する`}],correctIds:[`b`],explanation:`提案・検討段階の改正議論は、成立も内容も確定していません。現行制度として計算に組み込むことは誤りです。`,wrongExplanations:{a:`正しい扱いです。適用開始日が将来の制度は、現行制度とは区別しなければなりません。`,c:`正しい扱いです。過去の期間の計算には当時の制度を使います。`,d:`正しい扱いです。未確認の情報は未確認と明示し、確定値として表示しません。`},sources:[e.fsaTop,e.ntaTop],reviewStatus:`verified`},{id:`Q-M04-3`,lessonId:`M-04`,type:`single`,difficulty:2,skill:`calculate`,prompt:`元本100万円を税引前年率5%で10年間運用する。費用のない場合と、年1%の費用がかかり実質年率4%になる場合とで、10年後の金額の差はおよそいくらか。前提：1.05^10≒1.629、1.04^10≒1.480とする。`,options:[{id:`a`,text:`約14.9万円`},{id:`b`,text:`約10万円`},{id:`c`,text:`約48.0万円`},{id:`d`,text:`約62.9万円`}],correctIds:[`a`],explanation:`費用なしでは100万円×1.629＝162.9万円、費用ありでは100万円×1.480＝148.0万円です。その差は約14.9万円で、年1%の費用の差が10年の複利で元本の約15%相当に広がります。`,wrongExplanations:{b:`1%×10年＝10%と単純に掛けた計算です。複利では、差は約14.9万円に広がります。`,c:`費用ありの場合の利益額（148.0万円−100万円）そのものです。2つの場合の金額の差ではありません。`,d:`費用なしの場合の利益額（162.9万円−100万円）そのものです。2つの場合の金額の差ではありません。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-M04-4`,lessonId:`M-04`,type:`single`,difficulty:2,skill:`apply`,prompt:`ある制度改正が法律として成立したが、適用開始日は2年後である。この制度を資産形成の計算に使う際の扱いとして正しいものはどれか。`,options:[{id:`a`,text:`法律が成立したので、適用開始前である今年の計算から現行制度として組み込む`},{id:`b`,text:`適用開始が将来であることを明示し、適用時点以降の計算にのみ使う`},{id:`c`,text:`成立していても、報道された改正案と同様に無視する`},{id:`d`,text:`成立した制度は、過去の期間の計算にも遡って適用する`}],correctIds:[`b`],explanation:`成立済み未施行の制度は、施行中の制度とは区別し、適用開始日を明示したうえで将来時点の計算に使います。成立していない提案段階の議論とは扱いが異なります。`,wrongExplanations:{a:`適用開始日前の期間については現行制度ではありません。開始日以降の計算にのみ使います。`,c:`法律として成立している点で、提案・検討段階の議論とは区別されます。無視するのではなく、適用時点を明示して扱います。`,d:`過去の期間の計算には、当時の制度を適用します。成立した制度を遡って使うことはしません。`},sources:[e.fsaTop,e.ntaTop],reviewStatus:`verified`},{id:`Q-N01-1`,lessonId:`N-01`,type:`single`,difficulty:1,skill:`understand`,prompt:`「含み損の銘柄は損切りできず長く持ち続け、含み益の銘柄は早く売ってしまう」行動に最も関係が深いバイアスはどれか。`,options:[{id:`a`,text:`損失回避`},{id:`b`,text:`アンカリング`},{id:`c`,text:`確証バイアス`},{id:`d`,text:`FOMO`}],correctIds:[`a`],explanation:`損失の苦痛を利益の喜びより強く感じる損失回避により、損失の確定を避け、利益の確定を急ぐ行動が生じます。この行動パターン自体は処分効果と呼ばれ、その駆動要因が損失回避です。`,wrongExplanations:{b:`アンカリングは最初の価格等に判断が引きずられる傾向で、この行動の主因ではありません。`,c:`確証バイアスは自分の仮説を支持する情報だけを集める傾向です。`,d:`FOMOは上昇相場への乗り遅れ不安による衝動的な買いです。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-N01-2`,lessonId:`N-01`,type:`single`,difficulty:1,skill:`calculate`,prompt:`価格が100から50へ下落した後、元の100に戻るために必要な上昇率はどれか。`,options:[{id:`a`,text:`50%`},{id:`b`,text:`75%`},{id:`c`,text:`100%`},{id:`d`,text:`150%`}],correctIds:[`c`],explanation:`下落率は50%ですが、回復の基準は下落後の50です。(100−50)÷50＝100%の上昇が必要です。下落率と回復率は非対称です。`,wrongExplanations:{a:`下落率と回復率を混同しています。50から50%上昇しても75にしかなりません。`,b:`50×1.75＝87.5で、100には届きません。`,d:`150%は下落率60%（100→40）の場合の回復率です。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-N01-3`,lessonId:`N-01`,type:`single`,difficulty:2,skill:`apply`,prompt:`行動バイアスの影響を抑えるための対策として、最も適切なものはどれか。`,options:[{id:`a`,text:`相場の状況に応じて、その都度の判断で柔軟に売買する`},{id:`b`,text:`売買ルールを事前に決め、判断の根拠を記録し、反証となる情報を確認する手順を組み込む`},{id:`c`,text:`バイアスの種類と名前を覚えれば、判断への影響はなくなる`},{id:`d`,text:`判断に迷ったときは、周囲の多数派と同じ行動を取る`}],correctIds:[`b`],explanation:`バイアスは「気をつける」だけでは防ぎにくく、売買ルールの事前設定、判断根拠の記録、反証の確認といった手続きとして対策を組み込むことが有効です。`,wrongExplanations:{a:`その都度の判断は、バイアスの影響を最も受けやすい形です。事前のルール化が対策になります。`,c:`知識や経験があってもバイアスは生じます。知ることと、手続きで防ぐことは別です。`,d:`多数派に合わせる行動は群集行動そのものであり、バイアスの対策にはなりません。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-N01-4`,lessonId:`N-01`,type:`single`,difficulty:1,skill:`understand`,prompt:`「自分の予測はよく当たる」と考え、1つの銘柄に資金の大半を投じ、頻繁に売買している。この行動に最も関係が深いバイアスはどれか。`,options:[{id:`a`,text:`確証バイアス`},{id:`b`,text:`アンカリング`},{id:`c`,text:`FOMO`},{id:`d`,text:`過信`}],correctIds:[`d`],explanation:`自分の予測精度を実際より高く見積もる過信は、過剰な取引や集中投資を招きます。`,wrongExplanations:{a:`確証バイアスは、自分の仮説を支持する情報ばかりを集める傾向です。`,b:`アンカリングは、最初に見た価格等に判断が引きずられる傾向です。`,c:`FOMOは、上昇相場への乗り遅れ不安から、根拠の確認なしに飛びつく行動です。`},sources:[e.fsaInvest],reviewStatus:`verified`},{id:`Q-N02-1`,lessonId:`N-02`,type:`single`,difficulty:2,skill:`understand`,prompt:`流動性危機で価格下落が増幅する仕組みとして正しいものはどれか。`,options:[{id:`a`,text:`買い手が増えて価格が安定するため、下落は緩やかになる`},{id:`b`,text:`売りたいときに買い手が現れず、レバレッジ投資家の強制売却が「下落→担保価値低下→さらなる売却」の連鎖を起こす`},{id:`c`,text:`流動性危機は質の低い資産だけで起こり、優良資産の価格には影響しない`},{id:`d`,text:`流動性危機では取引が活発になるため、価格発見が正確になる`}],correctIds:[`b`],explanation:`流動性の枯渇と強制売却の連鎖により、資産の質と無関係に価格が下落することがあります。平時に相関の低かった資産が同時に下がることもあります。`,wrongExplanations:{a:`流動性危機は買い手が消える状態であり、価格は安定しません。`,c:`危機時には現金化の必要から、質の高い資産も売られます。`,d:`流動性危機では取引が滞り、価格は大きく飛んで形成されます。`},sources:[e.bojFsr],reviewStatus:`verified`},{id:`Q-N02-2`,lessonId:`N-02`,type:`single`,difficulty:2,skill:`find-error`,prompt:`バブルと危機に関する理解として誤っているものはどれか。`,options:[{id:`a`,text:`危機の一般的な経過を学ぶことは、危機の時期と規模を予測できることとは別である`},{id:`b`,text:`価格上昇そのものが買いの根拠になる段階は、バブルの後期に観察されることがある`},{id:`c`,text:`過去の危機の経過を理解すれば、次の危機を事前に正確に予測して回避できる`},{id:`d`,text:`危機の原因や政策対応は事例ごとに異なるため、過去の事例の単純な一般化には限界がある`}],correctIds:[`c`],explanation:`危機の時期・規模を事前に予測する確立した手法はありません。経過の理解を予測能力と混同することが誤りです。`,wrongExplanations:{a:`正しい理解です。パターンの理解と予測は別のものです。`,b:`正しい理解です。値上がり自体が根拠になる状態はバブル後期の特徴とされます。`,d:`正しい理解です。事例ごとの制度・原因・政策対応の違いを考慮する必要があります。`},sources:[e.bojFsr],reviewStatus:`verified`},{id:`Q-N02-3`,lessonId:`N-02`,type:`single`,difficulty:2,skill:`calculate`,prompt:`ある価格が25%下落した。元の価格に戻るために必要な上昇率に最も近いものはどれか。`,options:[{id:`a`,text:`20.0%`},{id:`b`,text:`25.0%`},{id:`c`,text:`33.3%`},{id:`d`,text:`50.0%`}],correctIds:[`c`],explanation:`回復に必要な上昇率＝下落率÷（1−下落率）＝0.25÷0.75≒33.3%です。価格100が75へ下がった場合、75から100へ戻るには（100−75）÷75≒33.3%の上昇が必要です。`,wrongExplanations:{a:`下落幅25を、回復後の価格125で割った計算です。上昇率の基準は下落後の価格（75）です。`,b:`下落率と同じ割合では戻りません。75×1.25＝93.75で、100には届きません。`,d:`50%は、下落率が約33.3%の場合に必要となる回復率です。`},sources:[e.bojFsr],reviewStatus:`verified`},{id:`Q-N02-4`,lessonId:`N-02`,type:`single`,difficulty:2,skill:`apply`,prompt:`ある資産について「値上がりしているから買うべきだ」「慎重に評価する人は乗り遅れる」という論調が広がっている。この状況の理解として正しいものはどれか。`,options:[{id:`a`,text:`価格上昇そのものが買いの根拠になる段階であり、価格が実体的な価値の評価から離れやすい`},{id:`b`,text:`投資家の多くが企業業績などのファンダメンタルズに基づいて、慎重な評価を行っている段階である`},{id:`c`,text:`売りたいときに買い手が見つからない流動性危機が、すでに始まっている段階である`},{id:`d`,text:`価格が企業業績などの実体的な価値に収束しつつある段階である`}],correctIds:[`a`],explanation:`バブルの一般的な経過では、価格上昇そのものが買いの根拠になり、慎重な評価が「乗り遅れ」と見なされる段階があります。これはバブルの後期に観察される特徴です。`,wrongExplanations:{b:`慎重な評価が軽視される論調であり、逆の状況です。`,c:`流動性危機は、売りたいときに買い手が現れず大きく下げなければ売れない状態で、この段階とは異なります。`,d:`価格上昇を根拠にする買いが広がる局面は、実体的な価値への収束ではなく、乖離が進みやすい段階です。`},sources:[e.bojFsr],reviewStatus:`verified`},{id:`Q-N03-1`,lessonId:`N-03`,type:`single`,difficulty:1,skill:`understand`,prompt:`ポンジスキームが構造的に破綻する理由として正しいものはどれか。`,options:[{id:`a`,text:`運用者の手腕次第では実際の運用益で配当を賄い続けられ、長期間継続できる仕組みだから`},{id:`b`,text:`配当の原資が新規出資者の資金であり、約束利回りを賄う新規流入が指数的に必要になって必ず行き詰まるから`},{id:`c`,text:`市場の金利が上昇し、他の金融商品の利回りが魅力的になったときだけ破綻するから`},{id:`d`,text:`参加者の全員が同じ日に一斉に出金を求めたときに限って、支払いができずに破綻するから`}],correctIds:[`b`],explanation:`運用の実収益がないため、支払いは新規資金でしか賄えません。必要な新規流入は増え続け、有限の資金では必ず条件を満たせなくなります。`,wrongExplanations:{a:`運用実態がない（または乏しい）ことが前提の詐欺であり、手腕で継続できる仕組みではありません。`,c:`破綻の原因は資金繰りの構造であり、金利環境に限定されません。`,d:`全員同時の出金がなくても、新規流入が細れば支払いは滞ります。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-N03-2`,lessonId:`N-03`,type:`single`,difficulty:1,skill:`apply`,prompt:`「元本保証で月3%の配当」をうたう未登録の事業者から勧誘を受けた。最も適切な対応はどれか。`,options:[{id:`a`,text:`少額から試し、毎月の配当が実際に支払われているうちは安全なので、様子を見ながら追加で出資する`},{id:`b`,text:`信頼できる知人からの紹介なので、契約書の内容と元本保証の記載だけを確認して契約する`},{id:`c`,text:`月3%は年率約42.6%（複利）で元本保証と両立しにくく、無登録業者でもあるため、契約せず金融庁の登録情報を確認する`},{id:`d`,text:`有名人がSNSで紹介しており、利用者の体験談も多数投稿されているため、信頼できると判断する`}],correctIds:[`c`],explanation:`1.03^12≒1.426、つまり年率換算約42.6%の利回りを元本保証で安定的に実現することは通常の市場運用では説明がつきません。登録の有無の確認と契約の見送りが適切です。`,wrongExplanations:{a:`ポンジスキームでも破綻前は配当が出ます。少額でも出資すべきではありません。`,b:`紹介経路は安全性の根拠になりません。無登録業者である時点で重大な問題です。`,d:`有名人の紹介や広告は、運用実態の裏付けにはなりません。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-N03-3`,lessonId:`N-03`,type:`single`,difficulty:1,skill:`understand`,prompt:`インサイダー取引が禁止される理由として正しいものはどれか。`,options:[{id:`a`,text:`取引が行われると株価が大きく変動し、ほかの投資家が損失を被るから`},{id:`b`,text:`未公表の重要情報を知る者だけが有利になる取引を許すと、市場の公平性が損なわれるから`},{id:`c`,text:`重要な情報が外部に漏れることで、その会社の業績が悪化するから`},{id:`d`,text:`内部者の取引が加わると、市場全体の取引の数量が増えすぎるから`}],correctIds:[`b`],explanation:`インサイダー取引は、上場会社の未公表の重要情報を知る者が、それを利用して売買する行為です。情報開示によって投資家間の情報格差を縮める仕組みと、市場参加者間の公平性を損なうため、禁止されています。`,wrongExplanations:{a:`株価の変動そのものではなく、情報を知る者だけが有利になる不公平が問題です。`,c:`禁止の理由は会社の業績ではなく、市場参加者間の公平性です。`,d:`取引量の多寡は、禁止の理由ではありません。`},sources:[e.jpxInsider],reviewStatus:`verified`},{id:`Q-N03-4`,lessonId:`N-03`,type:`single`,difficulty:2,skill:`find-error`,prompt:`勧誘や助言の評価について誤っているものはどれか。`,options:[{id:`a`,text:`金融庁の登録業者であっても、元本が保証されるわけではない`},{id:`b`,text:`助言者が何で報酬を得ているかは、助言を評価する際の確認事項である`},{id:`c`,text:`販売手数料が高い商品ほど、顧客にとって有利な商品である`},{id:`d`,text:`利益相反とは、販売する側の利益と顧客の利益が一致しない構造を指す`}],correctIds:[`c`],explanation:`手数料の高さは、顧客にとっての有利さを示しません。販売側の報酬が大きい商品には、販売側が勧める動機が生じる利益相反の構造があり、顧客の利益と一致するとは限りません。`,wrongExplanations:{a:`正しい理解です。登録は業務の許可であり、元本や商品の安全性の保証ではありません。`,b:`正しい理解です。報酬の出どころは、助言の立場を評価する材料になります。`,d:`正しい理解です。利益相反は、販売側と顧客の利益が一致しない構造を指します。`},sources:[e.fsaCrypto],reviewStatus:`verified`},{id:`Q-N04-1`,lessonId:`N-04`,type:`single`,difficulty:1,skill:`understand`,prompt:`投資判断の根拠として、最も信頼性が高い情報の組み合わせはどれか。`,options:[{id:`a`,text:`SNSで広く拡散されている投稿と、フォロワー数の多い発信者の予測`},{id:`b`,text:`発行体の有価証券報告書・決算短信と、金融庁・国税庁等の一次資料`},{id:`c`,text:`同じ内容を報じる複数のまとめ記事`},{id:`d`,text:`販売会社のパンフレットに記載された将来の想定利回り`}],correctIds:[`b`],explanation:`発行体の開示資料と官公庁の一次資料が、事実確認の基盤です。他の情報は一次情報で裏を取ってから使います。`,wrongExplanations:{a:`拡散の規模やフォロワー数は正確さの裏付けになりません。予測は事実とも区別が必要です。`,c:`同じ元の転載は独立した裏付けにはなりません。`,d:`販売資料の想定利回りは予測であり、利益相反の観点からも一次情報による確認が必要です。`},sources:[e.edinet,e.jpxTdnet],reviewStatus:`verified`},{id:`Q-N04-2`,lessonId:`N-04`,type:`multi`,difficulty:2,skill:`apply`,prompt:`投資情報を評価する際の確認手順として適切なものをすべて選べ。`,options:[{id:`a`,text:`主張の出典をたどり、一次情報で裏を取る`},{id:`b`,text:`数値の時点・単位・定義を確認する`},{id:`c`,text:`事実・仮定・予測を区別し、予測を事実として扱わない`},{id:`d`,text:`発信者の知名度が高ければ、出典の確認は省略する`}],correctIds:[`a`,`b`,`c`],explanation:`出典の確認、数値の前提（時点・単位・定義）の確認、事実／仮定／予測の区別が基本手順です。発信者の属性は確認を省略する理由にはなりません。`,wrongExplanations:{d:`知名度と正確さは無関係です。誰の情報でも出典確認が必要です。`},sources:[e.edinet,e.jpxTdnet],reviewStatus:`verified`},{id:`Q-N04-3`,lessonId:`N-04`,type:`single`,difficulty:2,skill:`find-error`,prompt:`事実・仮定・予測の区別について誤っているものはどれか。`,options:[{id:`a`,text:`アナリストの来期業績予想は、公表資料に基づく分析であるため「事実」として扱ってよい`},{id:`b`,text:`公表された決算数値は「事実」に当たる`},{id:`c`,text:`計算に置いた将来の成長率は「仮定」であり、結果を左右する前提として明示すべきものである`},{id:`d`,text:`予測は外れる可能性があり、事実とは区別して扱う必要がある`}],correctIds:[`a`],explanation:`業績予想は、根拠に公表資料を使っていても、将来についての見解である「予測」です。事実として扱うと、判断の確実性を誤認します。`,wrongExplanations:{b:`正しい区別です。公表された決算数値は、観測や公的記録で確認できる事実です。`,c:`正しい区別です。分析の前提として置く数値は仮定であり、明示することが求められます。`,d:`正しい区別です。予測は外れる可能性を前提に扱います。`},sources:[e.edinet,e.jpxTdnet],reviewStatus:`verified`},{id:`Q-N04-4`,lessonId:`N-04`,type:`single`,difficulty:2,skill:`apply`,prompt:`「この投資信託は過去1年で30%上昇」という宣伝を見た。投資判断の材料として扱う際の対応として最も適切なものはどれか。`,options:[{id:`a`,text:`宣伝された過去1年の上昇率を、そのまま今後1年の期待リターンとして資産計画に使う`},{id:`b`,text:`上昇率が高い商品ほど運用がうまく、値下がりしにくい安全な商品だと判断する`},{id:`c`,text:`過去の実績が数値で表示されていれば、出典や期間・前提の確認は不要と判断する`},{id:`d`,text:`実績を運用会社の資料で確認し、同期間の市場全体の動きと比べ、手数料・税引後で考える`}],correctIds:[`d`],explanation:`実績の数値は、表示する期間の切り取り方で印象が変わります。発行体の資料で実績を確認し、市場全体の動きと比較し、税引後で評価することが、宣伝を判断材料に変える手順です。`,wrongExplanations:{a:`過去の実績は将来の成果を保証するものではなく、期待値としてそのまま使うことはできません。`,b:`上昇率の高さは、将来の安全性を示すものではありません。`,c:`実績の表示があっても、期間・前提・出典の確認は必要です。`},sources:[e.edinet,e.jpxTdnet],reviewStatus:`verified`}],s=(e,t,n,r)=>[{id:`a`,text:e},{id:`b`,text:t},{id:`c`,text:n},{id:`d`,text:r}],c=[{id:`Q-G01-5`,lessonId:`G-01`,type:`single`,difficulty:2,skill:`calculate`,prompt:`4,096件の取引をマークル木（完全な二分木とする）でまとめたブロックがある。特定の1件が含まれることを示すマークル証明に必要なハッシュの数はいくつか。`,options:s(`64個`,`12個`,`2,048個`,`4,096個`),correctIds:[`b`],explanation:`4,096＝2^12なので木の高さは12で、葉から根までの各段で兄弟ノードのハッシュを1つずつ示せば根まで再計算できます。必要なのは12個です。全件を渡さずに検証できる点がマークル木の利点です。`,wrongExplanations:{a:`64は4,096の平方根です。必要な数は段数（log₂4,096＝12）で決まります。`,c:`取引数の半分を数えた誤りです。証明に必要なのは各段に1つずつのハッシュです。`,d:`全取引を渡すのはマークル証明を使わない検証方法です。`},sources:[e.bitcoinPaper],reviewStatus:`verified`},{id:`Q-L03-5`,lessonId:`L-03`,type:`single`,difficulty:3,skill:`calculate`,prompt:`配当のない株式のヨーロピアン・オプションで、株価100円、行使価格100円、満期1年、無リスク金利0%、コール価格9円のとき、プット・コール・パリティから求めたプット価格はいくらか。`,options:s(`0円`,`18円`,`91円`,`9円`),correctIds:[`d`],explanation:`C − P ＝ S − K·e^(−rT) に代入すると、9 − P ＝ 100 − 100×e^0 ＝ 0 なので P＝9円です。金利0%で権利行使価格と株価が等しいとき、コールとプットの価格は一致します。`,wrongExplanations:{a:`権利行使価格と株価が等しくても、満期までに値下がりする可能性があるためプットには時間価値があります。`,b:`コール価格を2倍にした誤りです。パリティでは差 C − P が S − K の割引現在価値に等しくなります。`,c:`行使価格からコール価格を引いた値（100 − 9）で、パリティの式ではありません。`},sources:[e.stoll1969],reviewStatus:`verified`},{id:`Q-E02-5`,lessonId:`E-02`,type:`single`,difficulty:2,skill:`calculate`,prompt:`テイラー・ルール（政策金利 ＝ 均衡実質金利 ＋ インフレ率 ＋ 0.5×（インフレ率 − 目標インフレ率） ＋ 0.5×GDPギャップ）で、均衡実質金利0.5%、インフレ率2.5%、目標インフレ率2%、GDPギャップ −1%のとき、目安となる政策金利はいくらか。`,options:s(`3.25%`,`3.00%`,`2.75%`,`2.25%`),correctIds:[`c`],explanation:`0.5 ＋ 2.5 ＋ 0.5×（2.5 − 2）＋ 0.5×（−1）＝ 0.5 ＋ 2.5 ＋ 0.25 − 0.5 ＝ 2.75%です。需給の緩み（負のGDPギャップ）は金利を下げる方向、目標を上回るインフレは上げる方向に働きます。`,wrongExplanations:{a:`GDPギャップの符号を正として加えた計算です（0.5＋2.5＋0.25＋0.5）。`,b:`2つの調整項（インフレ・ギャップとGDPギャップ）をどちらも省いた計算です。`,d:`インフレ率が目標を上回る分の調整項を、加えずに引いた計算です。`},sources:[e.bojPolicy],reviewStatus:`verified`},{id:`Q-E03-5`,lessonId:`E-03`,type:`single`,difficulty:3,skill:`calculate`,prompt:`債務残高の対GDP比が200%、名目金利と名目成長率の差（r − g）が＋0.5%、名目成長率はほぼ0%とする。比率を一定に保つために必要なプライマリーバランス（対GDP比）に最も近いものはどれか。`,options:s(`0.5%の黒字`,`均衡（0%）で足りる`,`1.0%の黒字`,`2.0%の黒字`),correctIds:[`c`],explanation:`Δb ≒（r − g）÷（1 ＋ g）× b − pb を0にする pb は、0.005 × 2.00 ＝ 0.01、すなわち対GDP比1.0%の黒字です。債務比率が高いほど、同じ r − g でも必要な黒字は大きくなります。`,wrongExplanations:{a:`r − g をそのまま答えた誤りで、債務残高の比率200%を掛けていません。`,b:`r＞g のときは、利払いの増加分を黒字で賄わないと比率は上昇します。`,d:`r − g を1%として計算した誤りです（0.01×2＝0.02）。`},sources:[e.bojTop],reviewStatus:`verified`},{id:`Q-J03-5`,lessonId:`J-03`,type:`single`,difficulty:2,skill:`understand`,prompt:`ある売買戦略のバックテストで「平均超過リターンのp値＝0.03」と報告された。この数値の解釈として正しいものはどれか。`,options:s(`この戦略に本当に超過リターンがある確率が97%であり、同じ成績が将来もほぼ確実に続く`,`真の超過リターンが0だと仮定したとき、これ以上に極端な結果が偶然に得られる確率が3%である`,`多数の戦略を試した中の最良のものでも、p値が0.03ならそのまま有意な発見として扱ってよい`,`戦略の平均超過リターンの大きさが3%であることを示し、経済的に重要な効果だと判断できる`),correctIds:[`b`],explanation:`p値は帰無仮説が正しいという仮定のもとで、観測以上に極端な結果が出る確率です。仮説が正しい確率ではなく、効果の大きさでもありません。多数の候補から選んだ結果には多重検定の補正が必要です。`,wrongExplanations:{a:`p値から「仮説が正しい確率」は直接求まりません。将来の成績の保証にもなりません。`,c:`多数の候補を試すと偶然の有意が増えるため（多重検定）、試行回数を考慮した評価が必要です。`,d:`p値は効果の大きさではありません。統計的有意性と経済的な重要性は別の問題です。`},sources:[e.asaPvalue2016,e.harveyLiuZhu2016],reviewStatus:`verified`},{id:`Q-C04-6`,lessonId:`C-04`,type:`single`,difficulty:3,skill:`compare`,prompt:`同じ規模の買収でのれんを計上した2社がある。A社は日本基準、B社はIFRSを適用している。買収後の利益の見え方の比較として正しいものはどれか（減損の兆候はないものとする）。`,options:s(`B社はIFRSに従ってのれんを毎期償却するため、A社より毎期の営業利益が償却分だけ小さく見える`,`どちらの基準でものれんは償却も減損もしないため、2社の利益の見え方に違いは生じない`,`日本基準のA社はのれんを買収した年に全額費用処理するため、翌年以降の利益が大きく見える`,`A社はのれんを規則的に償却するため、B社より毎期の営業利益が償却分だけ小さく見える`),correctIds:[`d`],explanation:`日本基準ではのれんを20年以内のその効果の及ぶ期間で規則的に償却し、IFRSでは償却せず減損テストを行います。減損がなければ、A社の営業利益は償却費の分だけB社より小さく見えます。比較時は償却前の利益などで基準の差をそろえます。`,wrongExplanations:{a:`償却するのは日本基準で、IFRSは償却しません（減損テストのみ）。`,b:`IFRSでも減損テストは行い、日本基準では規則的に償却します。`,c:`日本基準でも一括費用処理ではなく、効果の及ぶ期間で規則的に償却します。`},sources:[e.asbjBusinessCombinations],reviewStatus:`verified`}],l=[...r,...i,...a,...o,...c],u=new Map(l.map(e=>[e.id,e]));function d(e){let n=e.trim().toLowerCase();if(!n)return{lessons:[],questions:[]};let r=e=>e.toLowerCase().includes(n);return{lessons:t.filter(e=>r(`${e.id} ${e.title}`)||e.terms.some(r)||Object.values(e.layers).some(r)||e.misconceptions.some(r)||e.objectives.some(r)),questions:l.filter(e=>r(e.id)||r(e.prompt)||e.options.some(e=>r(e.text))||r(e.explanation))}}function f(e,t){let n=0;for(let e of t)n=n*31+e.charCodeAt(0)>>>0;let r=[...e];for(let e=r.length-1;e>0;e--){n=n*1664525+1013904223>>>0;let t=n%(e+1);[r[e],r[t]]=[r[t],r[e]]}return r}export{f as i,u as n,d as r,l as t};